import{f as o}from"./index-Dmj3m66V.js";const l={"Soll ich Ihnen die Einkaufstaschen in den dritten Stock tragen?":{de:"Oh, das wäre sehr nett! Der Lift ist ja schon wieder kaputt.",es:"¡Ay, qué amable! El ascensor vuelve a estar roto.",mas:[{de:"Kein Problem, ich wohne sowieso im vierten Stock.",es:"No es problema, total vivo en el cuarto."},{de:"Ich glaube, wir haben uns noch gar nicht vorgestellt. Ich bin Frau Novak.",es:"Creo que todavía no nos hemos presentado. Soy la señora Novak."},{de:"Freut mich! Ich heiße Daniel, ich bin letzten Monat eingezogen.",es:"¡Encantado! Me llamo Daniel, me mudé el mes pasado."},{de:"Ach, Sie sind der Neue! Willkommen im Haus.",es:"¡Ah, usted es el nuevo! Bienvenido al edificio."},{de:"Danke! Und wenn Sie mal etwas brauchen, läuten Sie einfach bei mir.",es:"¡Gracias! Y si alguna vez necesita algo, llame a mi puerta sin más."},{de:"Das mache ich. Und Sie kommen nächste Woche zum Hausfest, ja?",es:"Así lo haré. Y la semana que viene viene a la fiesta de vecinos, ¿verdad?"},{de:"Natürlich komme ich! Soll ich etwas mitbringen?",es:"¡Claro que iré! ¿Quiere que lleve algo?"},{de:"Wenn Sie Lust haben, einen Kuchen. Aber nur, wenn es keine Mühe macht.",es:"Si le apetece, un bizcocho. Pero solo si no es molestia."}]},"Das ist wirklich lieb von dir, vielen Dank für deine Hilfe!":{de:"Gern geschehen! Unter Nachbarn hilft man sich doch.",es:"¡De nada! Entre vecinos hay que ayudarse.",mas:[{de:"Ohne dich hätte ich das Regal nie aufgebaut.",es:"Sin ti nunca habría montado la estantería."},{de:"Ach was, zu zweit ging es ganz schnell.",es:"Qué va, entre los dos ha ido rapidísimo."},{de:"Darf ich dich wenigstens auf ein Bier einladen?",es:"¿Te puedo invitar al menos a una cerveza?"},{de:"Da sage ich nicht Nein. Vielleicht am Freitag?",es:"No te voy a decir que no. ¿Quizá el viernes?"},{de:"Gern. Und wenn du mal Hilfe brauchst, revanchiere ich mich.",es:"Vale. Y si algún día necesitas ayuda, te devuelvo el favor."},{de:"Abgemacht! Mein Balkon braucht nämlich dringend neue Farbe.",es:"¡Trato hecho! Mi balcón necesita pintura con urgencia."},{de:"Dann bringe ich am Samstag die Pinsel mit.",es:"Entonces el sábado traigo los pinceles."},{de:"Perfekt. Und ich sorge für die Pizza danach.",es:"Perfecto. Y yo me encargo de la pizza de después."}]},"Danke, das ist nett, aber ich schaffe das schon allein.":{de:"Sicher? Die Kiste sieht ziemlich schwer aus.",es:"¿Seguro? La caja parece bastante pesada.",mas:[{de:"Ja, wirklich. Es sind nur Bücher, und ich trage sie in zwei Etappen.",es:"Sí, de verdad. Solo son libros, y los subo en dos viajes."},{de:"Na gut. Aber sagen Sie Bescheid, wenn es doch zu viel wird.",es:"Bueno. Pero avíseme si al final es demasiado."},{de:"Mache ich, versprochen. Trotzdem danke für das Angebot!",es:"Lo haré, prometido. ¡Gracias igualmente por ofrecerse!"},{de:"Keine Ursache. Ich bin heute den ganzen Nachmittag zu Hause.",es:"No hay de qué. Hoy estoy en casa toda la tarde."},{de:"Gut zu wissen. Dann läute ich im Notfall bei Ihnen.",es:"Bueno es saberlo. Entonces, si hay algún apuro, llamo a su puerta."},{de:"Machen Sie das. Und viel Erfolg beim Einräumen!",es:"Hágalo. ¡Y que vaya bien la colocación!"},{de:"Danke! Und falls Sie mal ein Buch brauchen, ich habe jetzt genug.",es:"¡Gracias! Y si alguna vez necesita un libro, ahora tengo de sobra."},{de:"Ha, das merke ich mir. Ich lese gern Krimis.",es:"Ja, me lo apunto. Me gustan las novelas policiacas."}]},"Entschuldigung, wissen Sie zufällig, wann der Biomüll abgeholt wird?":{de:"Ja, immer am Donnerstag in der Früh. Die Tonne muss am Mittwochabend draußen stehen.",es:"Sí, siempre el jueves por la mañana. El contenedor tiene que estar fuera el miércoles por la noche.",mas:[{de:"Und wer stellt die Tonne raus? Muss ich das machen?",es:"¿Y quién saca el contenedor? ¿Lo tengo que hacer yo?"},{de:"Nein, das macht der Hausmeister. Sie müssen nur den Müll richtig trennen.",es:"No, eso lo hace el conserje. Usted solo tiene que separar bien la basura."},{de:"Verstehe. Darf man Kaffeefilter in den Biomüll werfen?",es:"Entiendo. ¿Los filtros de café se pueden tirar a la orgánica?"},{de:"Ja, die schon, aber bitte keine Plastiksackerl.",es:"Sí, esos sí, pero bolsas de plástico no, por favor."},{de:"Gut, dass Sie es mir sagen. Das wusste ich nicht.",es:"Menos mal que me lo dice. No lo sabía."},{de:"Kein Problem. Der Plan hängt auch im Müllraum, wenn Sie nachschauen wollen.",es:"No pasa nada. El calendario también está colgado en el cuarto de basuras, por si quiere mirarlo."},{de:"Danke, das mache ich gleich heute Abend.",es:"Gracias, lo miro esta misma tarde."},{de:"Gern. Und willkommen im Haus, falls ich das noch nicht gesagt habe!",es:"De nada. ¡Y bienvenido al edificio, por si no se lo he dicho todavía!"}]},"Entschuldigen Sie, aber die Musik war gestern wieder bis ein Uhr nachts zu laut.":{de:"Oh, wirklich? Das tut mir leid, wir hatten Geburtstag.",es:"¿De verdad? Lo siento, celebrábamos un cumpleaños.",mas:[{de:"Ich verstehe, dass man mal feiert. Aber ich muss um sechs aufstehen.",es:"Entiendo que de vez en cuando se celebre algo. Pero yo me levanto a las seis."},{de:"Das wusste ich nicht. Ich dachte, man hört oben nichts.",es:"No lo sabía. Pensaba que arriba no se oía nada."},{de:"Leider schon, vor allem den Bass. Die Wände sind sehr dünn.",es:"Pues sí, sobre todo los graves. Las paredes son muy finas."},{de:"Dann sage ich beim nächsten Mal vorher Bescheid und mache um zehn leiser.",es:"Entonces la próxima vez aviso antes y a las diez bajo la música."},{de:"Das wäre super. Dann kann ich mich darauf einstellen.",es:"Sería estupendo. Así me puedo hacer a la idea."},{de:"Abgemacht. Und nochmals Entschuldigung für gestern.",es:"Trato hecho. Y otra vez perdón por lo de ayer."},{de:"Kein Problem. Feiern Sie ruhig, nur nicht jeden Abend.",es:"No pasa nada. Celebren lo que quieran, solo que no todas las noches."},{de:"Versprochen. Nächstes Mal laden wir Sie einfach ein!",es:"Prometido. ¡La próxima vez le invitamos directamente!"}]},"Das war mir gar nicht bewusst, entschuldigen Sie bitte!":{de:"Schon gut. Aber der Kinderwagen steht jeden Tag mitten im Gang.",es:"No pasa nada. Pero el cochecito está todos los días en medio del pasillo.",mas:[{de:"Ich weiß nicht, wo ich ihn sonst abstellen soll. Er passt nicht in den Lift.",es:"No sé dónde dejarlo si no. No cabe en el ascensor."},{de:"Im Fahrradraum ist eigentlich genug Platz dafür.",es:"En el cuarto de las bicis hay sitio de sobra para él."},{de:"Ach so, das wusste ich nicht. Darf man den Raum auch dafür benutzen?",es:"Ah, no lo sabía. ¿Se puede usar el cuarto también para eso?"},{de:"Ja, das steht sogar in der Hausordnung. Ich zeige Ihnen, wo.",es:"Sí, viene incluso en las normas de la comunidad. Le enseño dónde."},{de:"Danke, das ist sehr freundlich. Ab heute stelle ich ihn dort hin.",es:"Gracias, es muy amable. A partir de hoy lo dejo allí."},{de:"Wunderbar. Dann kommen auch die Rollstühle wieder gut vorbei.",es:"Estupendo. Así también vuelven a poder pasar bien las sillas de ruedas."},{de:"Daran habe ich gar nicht gedacht. Das tut mir wirklich leid.",es:"No había pensado en eso. Lo siento de verdad."},{de:"Kein Problem. Gut, dass wir darüber gesprochen haben.",es:"No pasa nada. Me alegro de que lo hayamos hablado."}]},"Wie wäre es, wenn ich nur am Samstagvormittag bohre?":{de:"Das klingt fair. Unter der Woche ist es für uns schwierig, das Baby schläft viel.",es:"Me parece justo. Entre semana nos cuesta, el bebé duerme mucho.",mas:[{de:"Verstehe. Wann schläft das Baby denn am Samstag?",es:"Entiendo. ¿Y cuándo duerme el bebé el sábado?"},{de:"Meistens von zwölf bis zwei. Davor und danach ist es kein Problem.",es:"Casi siempre de doce a dos. Antes y después no hay problema."},{de:"Dann mache ich von neun bis zwölf und höre dann auf.",es:"Pues lo hago de nueve a doce y luego paro."},{de:"Super, danke, dass Sie fragen. Das machen nicht alle.",es:"Estupendo, gracias por preguntar. No todo el mundo lo hace."},{de:"Ich will ja auch keinen Streit im Haus.",es:"Yo tampoco quiero problemas en el edificio."},{de:"Eben. Und wenn Sie fertig sind, kommen Sie doch auf einen Kaffee vorbei!",es:"Eso es. ¡Y cuando acabe, pásese a tomar un café!"},{de:"Sehr gern. Dann sehe ich auch endlich das Baby.",es:"Con mucho gusto. Así por fin conozco al bebé."},{de:"Er heißt Jonas. Am Nachmittag ist er meistens gut gelaunt.",es:"Se llama Jonas. Por la tarde suele estar de buen humor."}]},"Ich habe Ihren Zettel am Schwarzen Brett gesehen – ist das Kinderbett noch zu verschenken?":{de:"Ja, es ist noch da! Haben Sie Nachwuchs bekommen?",es:"¡Sí, todavía la tengo! ¿Han tenido un bebé?",mas:[{de:"Noch nicht, aber im März ist es so weit.",es:"Todavía no, pero en marzo nace."},{de:"Wie schön, herzlichen Glückwunsch! Dann können Sie es gut brauchen.",es:"¡Qué bien, enhorabuena! Entonces le vendrá bien."},{de:"Ja, sehr. Wann könnte ich es abholen?",es:"Sí, mucho. ¿Cuándo podría ir a buscarla?"},{de:"Heute Abend ab sieben passt gut. Ich wohne auf Top 12.",es:"Esta tarde a partir de las siete va bien. Vivo en la puerta 12."},{de:"Perfekt. Soll ich Ihnen etwas dafür geben?",es:"Perfecto. ¿Quiere que le dé algo a cambio?"},{de:"Nein, gar nicht. Bringen Sie mir nur einmal ein Foto vom Baby!",es:"No, nada. ¡Solo enséñeme algún día una foto del bebé!"},{de:"Das mache ich gern. Bis heute Abend!",es:"Lo haré con gusto. ¡Hasta esta tarde!"},{de:"Bis dann! Ich lege noch die Matratze dazu, die ist fast neu.",es:"¡Hasta luego! Le pongo también el colchón, que está casi nuevo."}]},"Mich interessiert an dieser Stelle besonders die Arbeit mit Menschen.":{de:"Das freut mich. Mit wem haben Sie denn bisher gearbeitet?",es:"Me alegra oírlo. ¿Y con quién ha trabajado hasta ahora?",mas:[{de:"Drei Jahre lang habe ich in einem Seniorenheim in Lima gearbeitet.",es:"Durante tres años trabajé en una residencia de mayores en Lima."},{de:"Und was hat Ihnen dort am besten gefallen?",es:"¿Y qué es lo que más le gustó allí?"},{de:"Die Gespräche mit den Bewohnern. Viele hatten niemanden zum Reden.",es:"Las conversaciones con los residentes. Muchos no tenían a nadie con quien hablar."},{de:"Das verstehe ich gut. Bei uns ist es ganz ähnlich.",es:"Lo entiendo muy bien. Aquí pasa algo muy parecido."},{de:"Deshalb möchte ich auch hier wieder in der Pflege arbeiten.",es:"Por eso quiero volver a trabajar en cuidados también aquí."},{de:"Wie sieht es mit der Anerkennung Ihrer Ausbildung aus?",es:"¿Y cómo va la homologación de su formación?"},{de:"Der Antrag ist gestellt, ich warte nur noch auf den Bescheid.",es:"La solicitud está presentada, solo espero la resolución."},{de:"Sehr gut. Bis dahin könnten Sie bei uns schon als Pflegehelferin anfangen.",es:"Muy bien. Hasta entonces podría empezar con nosotros como auxiliar."}]},"Am liebsten arbeite ich im Team, aber ich kann auch gut allein arbeiten.":{de:"Das ist gut, bei uns gibt es beides. Arbeiten Sie lieber früh oder spät?",es:"Bien, aquí hay de las dos cosas. ¿Prefiere trabajar temprano o tarde?",mas:[{de:"Lieber früh. Ich bin ein Morgenmensch.",es:"Prefiero temprano. Soy de mañanas."},{de:"Perfekt, die Frühschicht beginnt um sechs.",es:"Perfecto, el turno de mañana empieza a las seis."},{de:"Das ist kein Problem, ich wohne nur zehn Minuten entfernt.",es:"No hay problema, vivo a solo diez minutos."},{de:"Und wie finden Sie Arbeit mit vielen Kunden?",es:"¿Y qué le parece trabajar con muchos clientes?"},{de:"Das mag ich sehr. Ich rede gern mit Leuten.",es:"Me gusta mucho. Me encanta hablar con la gente."},{de:"Gibt es etwas, was Sie nicht so gern machen?",es:"¿Hay algo que no le guste tanto hacer?"},{de:"Ehrlich gesagt, lange Telefonate auf Deutsch sind noch anstrengend.",es:"Si le soy sincero, las llamadas largas en alemán todavía me cuestan."},{de:"Danke für die Ehrlichkeit. Das wird mit der Zeit bestimmt leichter.",es:"Gracias por la sinceridad. Seguro que con el tiempo será más fácil."}]},"Ich spreche fließend Englisch und kenne mich gut mit Kassensystemen aus.":{de:"Sehr schön. Haben Sie auch Erfahrung mit Reklamationen?",es:"Muy bien. ¿Tiene también experiencia con reclamaciones?",mas:[{de:"Ja, im Elektrogeschäft war das jeden Tag ein Thema.",es:"Sí, en la tienda de electrónica era el pan de cada día."},{de:"Wie reagieren Sie, wenn ein Kunde laut wird?",es:"¿Cómo reacciona cuando un cliente levanta la voz?"},{de:"Ich bleibe ruhig, höre zu und suche eine Lösung.",es:"Mantengo la calma, escucho y busco una solución."},{de:"Das klingt gut. Können Sie mir ein Beispiel geben?",es:"Suena bien. ¿Me puede dar un ejemplo?"},{de:"Einmal war ein Fernseher kaputt, und ich habe sofort einen Ersatz organisiert.",es:"Una vez un televisor venía roto y organicé un cambio en el momento."},{de:"Und war der Kunde danach zufrieden?",es:"¿Y después el cliente quedó contento?"},{de:"Sehr. Er hat sich später sogar bei meiner Chefin bedankt.",es:"Mucho. Después hasta le dio las gracias a mi jefa."},{de:"Genau solche Leute suchen wir.",es:"Justo gente así es la que buscamos."}]},"Von 2019 bis 2023 habe ich als Lagerarbeiter in einer Spedition gearbeitet.":{de:"Interessant. Welche Aufgaben hatten Sie dort genau?",es:"Interesante. ¿Qué tareas tenía allí exactamente?",mas:[{de:"Ich habe Waren angenommen, kontrolliert und für den Versand vorbereitet.",es:"Recibía la mercancía, la revisaba y la preparaba para el envío."},{de:"Haben Sie auch mit dem Stapler gearbeitet?",es:"¿Trabajó también con la carretilla elevadora?"},{de:"Ja, ich habe den Staplerschein seit 2020.",es:"Sí, tengo el carné de carretillero desde 2020."},{de:"Sehr gut. Und warum haben Sie die Firma verlassen?",es:"Muy bien. ¿Y por qué dejó la empresa?"},{de:"Die Firma hat den Standort geschlossen, leider.",es:"La empresa cerró la sede, por desgracia."},{de:"Das tut mir leid. Was haben Sie seitdem gemacht?",es:"Lo siento. ¿Y qué ha hecho desde entonces?"},{de:"Ich habe einen Deutschkurs besucht und einen Lehrgang für Logistik gemacht.",es:"He hecho un curso de alemán y otro de logística."},{de:"Das sieht man auch: Ihr Deutsch ist wirklich gut.",es:"Se nota: su alemán es muy bueno de verdad."}]},"Was würdest du mir raten: Soll ich die Stelle in Linz annehmen?":{de:"Hm, das kommt darauf an. Was spricht denn dafür?",es:"Mmm, depende. ¿Qué tiene a favor?",mas:[{de:"Das Gehalt ist besser, und es ist eine Festanstellung.",es:"El sueldo es mejor y es un contrato fijo."},{de:"Und was spricht dagegen?",es:"¿Y qué tiene en contra?"},{de:"Ich müsste jeden Tag zwei Stunden pendeln.",es:"Tendría que hacer dos horas de trayecto cada día."},{de:"Das ist viel. Könntest du nicht nach Linz ziehen?",es:"Eso es mucho. ¿No podrías mudarte a Linz?"},{de:"Vielleicht später, aber meine Kinder gehen hier zur Schule.",es:"Quizá más adelante, pero mis hijos van al colegio aquí."},{de:"Dann frag doch, ob du zwei Tage Homeoffice machen kannst.",es:"Pues pregunta si puedes trabajar dos días desde casa."},{de:"Gute Idee, daran habe ich gar nicht gedacht.",es:"Buena idea, no se me había ocurrido."},{de:"Frag einfach im nächsten Gespräch. Mehr als Nein sagen können sie nicht.",es:"Pregúntalo en la próxima entrevista. Lo más que pueden decirte es que no."}]},"Du könntest dich doch zuerst telefonisch nach der Stelle erkundigen.":{de:"Meinst du? Ich habe ein bisschen Angst vor Telefonaten auf Deutsch.",es:"¿Tú crees? Me dan un poco de miedo las llamadas en alemán.",mas:[{de:"Das verstehe ich. Schreib dir vorher die wichtigsten Fragen auf.",es:"Lo entiendo. Apúntate antes las preguntas más importantes."},{de:"Welche Fragen sollte ich denn stellen?",es:"¿Y qué preguntas debería hacer?"},{de:"Zum Beispiel, wann die Stelle frei wird und wie die Arbeitszeiten sind.",es:"Por ejemplo, cuándo queda libre el puesto y cuál es el horario."},{de:"Und wenn ich etwas nicht verstehe?",es:"¿Y si no entiendo algo?"},{de:"Dann sag einfach: Könnten Sie das bitte langsamer wiederholen?",es:"Pues di simplemente: ¿Podría repetirlo más despacio, por favor?"},{de:"Das kann ich mir merken. Hilfst du mir, die Fragen zu schreiben?",es:"Eso me lo puedo aprender. ¿Me ayudas a escribir las preguntas?"},{de:"Klar, setzen wir uns heute Abend zusammen.",es:"Claro, nos sentamos esta tarde."},{de:"Danke, du bist die Beste! Ich bringe den Kuchen mit.",es:"¡Gracias, eres la mejor! Yo llevo el bizcocho."}]},"Könnten Sie mir sagen, wie die Arbeitszeiten geregelt sind?":{de:"Gern. Wir arbeiten von Montag bis Freitag, mit Gleitzeit zwischen sieben und neun.",es:"Con mucho gusto. Trabajamos de lunes a viernes, con horario flexible de entrada entre las siete y las nueve.",mas:[{de:"Das klingt gut. Gibt es auch Wochenenddienste?",es:"Suena bien. ¿Hay también turnos de fin de semana?"},{de:"Nur einmal im Monat, und dafür bekommen Sie eine Zulage.",es:"Solo una vez al mes, y por eso recibe un plus."},{de:"Und wie lange dauert die Einarbeitung?",es:"¿Y cuánto dura el periodo de formación inicial?"},{de:"Etwa vier Wochen. In der Zeit hat jeder Neue einen Paten im Team.",es:"Unas cuatro semanas. Durante ese tiempo cada nuevo tiene un padrino en el equipo."},{de:"Das finde ich sehr hilfreich. Darf ich noch nach dem Urlaub fragen?",es:"Me parece muy útil. ¿Puedo preguntar también por las vacaciones?"},{de:"Natürlich. Sie haben fünf Wochen Urlaub im Jahr.",es:"Por supuesto. Tiene cinco semanas de vacaciones al año."},{de:"Wunderbar. Dann habe ich im Moment keine Fragen mehr.",es:"Estupendo. Entonces de momento no tengo más preguntas."},{de:"Gut, dann melden wir uns bis Ende der Woche bei Ihnen.",es:"Bien, pues nos pondremos en contacto con usted antes de que acabe la semana."}]},"Vielen Dank für das Gespräch, ich würde mich über eine positive Antwort sehr freuen.":{de:"Wir danken Ihnen auch. Sie hören spätestens nächste Woche von uns.",es:"Gracias a usted también. Tendrá noticias nuestras como muy tarde la semana que viene.",mas:[{de:"Darf ich Sie anrufen, falls ich noch eine Frage habe?",es:"¿Puedo llamarle si me surge alguna otra pregunta?"},{de:"Selbstverständlich. Meine Nummer steht auf der Visitenkarte.",es:"Por supuesto. Mi número está en la tarjeta."},{de:"Danke. Soll ich noch Unterlagen nachschicken?",es:"Gracias. ¿Tengo que enviarle algún documento más?"},{de:"Ja, bitte schicken Sie uns noch eine Kopie Ihres Diploms.",es:"Sí, por favor, envíenos todavía una copia de su título."},{de:"Das mache ich gleich heute Nachmittag.",es:"Lo hago esta misma tarde."},{de:"Sehr gut. Finden Sie allein zum Ausgang?",es:"Muy bien. ¿Encuentra sola la salida?"},{de:"Ja, danke, gleich links zum Lift.",es:"Sí, gracias, a la izquierda hacia el ascensor."},{de:"Genau. Auf Wiedersehen und einen schönen Tag noch!",es:"Eso es. ¡Adiós y que tenga un buen día!"}]},"Guten Tag, ich hätte gern einen Termin bei Frau Doktor Lang, möglichst noch diese Woche.":{de:"Diese Woche ist es leider schwierig. Ist es dringend?",es:"Esta semana es complicado, lo siento. ¿Es urgente?",mas:[{de:"Ich habe seit zehn Tagen starke Rückenschmerzen.",es:"Llevo diez días con un dolor de espalda muy fuerte."},{de:"Dann schauen wir. Am Donnerstag um halb acht wäre noch frei.",es:"Entonces vamos a ver. El jueves a las siete y media queda un hueco."},{de:"Halb acht in der Früh? Das schaffe ich.",es:"¿A las siete y media de la mañana? Llego."},{de:"Gut. Sind Sie schon Patientin bei uns?",es:"Bien. ¿Ya es usted paciente nuestra?"},{de:"Nein, ich bin neu. Was muss ich mitbringen?",es:"No, soy nueva. ¿Qué tengo que traer?"},{de:"Bitte die E-Card und, wenn Sie haben, alte Befunde.",es:"La tarjeta sanitaria y, si tiene, resultados antiguos."},{de:"In Ordnung. Soll ich früher kommen, für die Anmeldung?",es:"De acuerdo. ¿Vengo antes, por lo del registro?"},{de:"Ja, kommen Sie bitte zehn Minuten früher. Gute Besserung!",es:"Sí, venga diez minutos antes, por favor. ¡Que se mejore!"}]},"Ich muss meinen Termin am Donnerstag leider verschieben, mein Kind ist krank.":{de:"Das ist kein Problem. Auf wann möchten Sie ihn verschieben?",es:"No pasa nada. ¿A cuándo quiere cambiarla?",mas:[{de:"Ginge es nächste Woche, am Dienstag oder Mittwoch?",es:"¿Podría ser la semana que viene, el martes o el miércoles?"},{de:"Am Mittwoch um elf hätte ich etwas frei.",es:"El miércoles a las once tengo un hueco."},{de:"Um elf arbeite ich leider. Gibt es auch etwas am Nachmittag?",es:"A las once trabajo, por desgracia. ¿Hay algo por la tarde?"},{de:"Dienstag um sechzehn Uhr dreißig, das ist der letzte Termin.",es:"El martes a las cuatro y media, que es la última cita."},{de:"Perfekt, den nehme ich.",es:"Perfecto, me la quedo."},{de:"Gut, ich habe Sie eingetragen. Und gute Besserung für Ihr Kind!",es:"Bien, ya la he apuntado. ¡Y que se mejore su hijo!"},{de:"Danke. Und Entschuldigung, dass ich so spät absage.",es:"Gracias. Y perdone que avise tan tarde."},{de:"Kein Problem, Sie haben ja angerufen. Das machen nicht alle.",es:"No pasa nada, por lo menos ha llamado. No todo el mundo lo hace."}]},"Könnten Sie Herrn Doktor Kaya bitte ausrichten, dass er mich zurückrufen soll?":{de:"Natürlich. Unter welcher Nummer erreicht er Sie am besten?",es:"Por supuesto. ¿A qué número le puede llamar mejor?",mas:[{de:"Unter 0664 815 22 37, am besten am Nachmittag.",es:"Al 0664 815 22 37, mejor por la tarde."},{de:"Ich wiederhole: 0664 815 22 37. Worum geht es denn?",es:"Repito: 0664 815 22 37. ¿Y de qué se trata?"},{de:"Um meinen Befund vom Montag. Ich habe noch Fragen dazu.",es:"De mi resultado del lunes. Tengo alguna pregunta."},{de:"Verstehe. Er ruft meistens nach der Sprechstunde zurück, so gegen eins.",es:"Entiendo. Suele devolver las llamadas después de la consulta, hacia la una."},{de:"Gegen eins bin ich noch in der Arbeit. Geht es auch später?",es:"Hacia la una todavía estoy trabajando. ¿Puede ser más tarde?"},{de:"Ich schreibe dazu: bitte nach fünfzehn Uhr.",es:"Lo apunto: por favor, después de las tres."},{de:"Vielen Dank, das ist sehr freundlich.",es:"Muchas gracias, es muy amable."},{de:"Gern. Sollte es heute nicht klappen, meldet er sich morgen.",es:"De nada. Si hoy no puede ser, le llamará mañana."}]},"In letzter Zeit bin ich total gestresst und schlafe richtig schlecht.":{de:"Oje. Liegt das an der Arbeit oder ist zu Hause etwas los?",es:"Vaya. ¿Es por el trabajo o pasa algo en casa?",mas:[{de:"Beides. Im Job haben wir Termindruck, und meine Mutter ist krank.",es:"Las dos cosas. En el trabajo vamos con los plazos justos y mi madre está enferma."},{de:"Das ist wirklich eine Doppelbelastung. Hast du mal mit deiner Chefin gesprochen?",es:"Eso sí que es una doble carga. ¿Has hablado con tu jefa?"},{de:"Noch nicht. Ich habe Angst, dass sie mich für schwach hält.",es:"Todavía no. Me da miedo que piense que soy débil."},{de:"Ach was, es ist doch normal, dass man mal Hilfe braucht.",es:"Qué va, es normal necesitar ayuda alguna vez."},{de:"Du hast recht. Vielleicht kann ich ein paar Tage Urlaub nehmen.",es:"Tienes razón. A lo mejor puedo cogerme unos días de vacaciones."},{de:"Gute Idee. Und was machst du, um abends abzuschalten?",es:"Buena idea. ¿Y qué haces para desconectar por las noches?"},{de:"Eigentlich nichts, ich grüble meistens nur.",es:"La verdad es que nada, casi siempre le doy vueltas a las cosas."},{de:"Probier mal Atemübungen. Mir haben sie wirklich geholfen.",es:"Prueba con ejercicios de respiración. A mí me han ayudado mucho."}]},"Seit einer Woche habe ich starke Verspannungen im Nacken und Kopfweh.":{de:"Hm. Sitzen Sie viel am Computer?",es:"Mmm. ¿Pasa mucho tiempo sentado delante del ordenador?",mas:[{de:"Ja, acht Stunden am Tag, und abends noch am Handy.",es:"Sí, ocho horas al día, y por la noche el móvil."},{de:"Das erklärt einiges. Haben Sie auch Schwindel oder Übelkeit?",es:"Eso explica muchas cosas. ¿Tiene también mareos o náuseas?"},{de:"Nein, das nicht. Aber ich schlafe schlecht.",es:"No, eso no. Pero duermo mal."},{de:"Ich verschreibe Ihnen Physiotherapie, zehn Einheiten.",es:"Le receto fisioterapia, diez sesiones."},{de:"Muss ich auch Tabletten nehmen?",es:"¿Tengo que tomar también pastillas?"},{de:"Nur wenn die Schmerzen sehr stark sind. Wichtiger ist Bewegung.",es:"Solo si el dolor es muy fuerte. Lo más importante es moverse."},{de:"Bewegung? Ich habe kaum Zeit.",es:"¿Moverme? Si apenas tengo tiempo."},{de:"Zehn Minuten Rückengymnastik am Tag reichen schon. Ich gebe Ihnen ein Blatt mit.",es:"Con diez minutos de gimnasia de espalda al día ya basta. Le doy una hoja."}]},"Ich mache mir wirklich Sorgen um dich, du siehst so müde aus.":{de:"Danke, dass du fragst. Ich arbeite gerade einfach zu viel.",es:"Gracias por preguntar. Es que ahora trabajo demasiado.",mas:[{de:"Wie viele Stunden sind es denn pro Woche?",es:"¿Y cuántas horas son a la semana?"},{de:"Mit den Überstunden fast fünfzig.",es:"Con las horas extra, casi cincuenta."},{de:"Das ist viel zu viel. Darauf musst du achten.",es:"Eso es demasiado. Tienes que tener cuidado."},{de:"Ich weiß, aber im Moment geht es nicht anders.",es:"Lo sé, pero ahora mismo no puede ser de otra manera."},{de:"Kann dir jemand im Team helfen?",es:"¿Te puede ayudar alguien del equipo?"},{de:"Ab nächstem Monat kommt ein neuer Kollege. Dann wird es besser.",es:"El mes que viene llega un compañero nuevo. Entonces mejorará."},{de:"Hoffentlich! Und bis dahin gönnst du dir wenigstens den Sonntag.",es:"¡Ojalá! Y hasta entonces date al menos el domingo libre."},{de:"Versprochen. Sonntag gehen wir zusammen spazieren, okay?",es:"Prometido. El domingo vamos a pasear juntos, ¿vale?"}]},"Das tut mir so leid, dass du schon wieder ins Krankenhaus musst.":{de:"Danke. Es ist nur eine Kontrolle, aber ich habe trotzdem Angst.",es:"Gracias. Solo es una revisión, pero aun así tengo miedo.",mas:[{de:"Das verstehe ich gut. Wie lange musst du bleiben?",es:"Te entiendo perfectamente. ¿Cuánto tiempo te tienes que quedar?"},{de:"Wahrscheinlich nur zwei Nächte.",es:"Seguramente solo dos noches."},{de:"Soll ich dich besuchen kommen?",es:"¿Quieres que vaya a verte?"},{de:"Das wäre schön. Am zweiten Tag habe ich sicher Langeweile.",es:"Me encantaría. El segundo día seguro que me aburro."},{de:"Dann komme ich am Mittwoch und bringe dir Zeitschriften mit.",es:"Pues voy el miércoles y te llevo revistas."},{de:"Du bist ein Schatz. Und vielleicht ein Stück Kuchen?",es:"Eres un sol. ¿Y a lo mejor un trozo de pastel?"},{de:"Wenn du das essen darfst, natürlich!",es:"¡Si te dejan comerlo, claro!"},{de:"Ich frage den Arzt. Danke, dass du für mich da bist.",es:"Se lo pregunto al médico. Gracias por estar a mi lado."}]},"Hoffentlich ist der Befund in Ordnung, dann kann ich endlich wieder arbeiten.":{de:"Ich drücke dir ganz fest die Daumen! Wann bekommst du ihn?",es:"¡Cruzo los dedos muy fuerte por ti! ¿Cuándo te lo dan?",mas:[{de:"Am Freitag. Bis dahin bin ich ziemlich nervös.",es:"El viernes. Hasta entonces estoy bastante nerviosa."},{de:"Das ist normal. Was hat die Ärztin denn gesagt?",es:"Es normal. ¿Y qué te ha dicho la médica?"},{de:"Sie meint, es sieht eigentlich gut aus.",es:"Dice que en principio tiene buena pinta."},{de:"Na siehst du! Dann denk positiv.",es:"¡Lo ves! Pues piensa en positivo."},{de:"Ich versuche es. Ich hoffe nur, dass ich keine Reha machen muss.",es:"Lo intento. Solo espero no tener que hacer rehabilitación."},{de:"Und wenn doch, ist das auch kein Weltuntergang.",es:"Y si la tienes que hacer, tampoco es el fin del mundo."},{de:"Stimmt. Hauptsache, ich werde wieder gesund.",es:"Es verdad. Lo importante es ponerme bien."},{de:"Genau. Ruf mich am Freitag gleich an, ja?",es:"Eso es. Llámame el viernes en cuanto lo sepas, ¿vale?"}]},"Hast du am Sonntag Lust auf einen Ausflug zum Badesee?":{de:"Ja, gern! Wie wollen wir hinfahren?",es:"¡Sí, claro! ¿Cómo vamos?",mas:[{de:"Mit dem Rad, das sind nur zwanzig Kilometer.",es:"En bici, solo son veinte kilómetros."},{de:"Zwanzig Kilometer? Ich habe aber kein Fahrrad.",es:"¿Veinte kilómetros? Pero yo no tengo bici."},{de:"Kein Problem, am Bahnhof gibt es Leihräder.",es:"No pasa nada, en la estación hay bicis de alquiler."},{de:"Super. Und was nehmen wir zum Essen mit?",es:"Genial. ¿Y qué llevamos para comer?"},{de:"Ich mache Brote und du bringst Obst mit, okay?",es:"Yo hago bocadillos y tú traes fruta, ¿vale?"},{de:"Abgemacht. Wann treffen wir uns?",es:"Hecho. ¿A qué hora quedamos?"},{de:"Um zehn am Bahnhof, beim Fahrradverleih.",es:"A las diez en la estación, en el alquiler de bicis."},{de:"Perfekt. Ich freue mich schon!",es:"Perfecto. ¡Ya tengo ganas!"}]},"Wann hättest du nächste Woche Zeit für einen Kaffee?":{de:"Montag und Dienstag arbeite ich lange. Wie wäre es mit Mittwoch?",es:"Lunes y martes trabajo hasta tarde. ¿Qué tal el miércoles?",mas:[{de:"Mittwoch passt. Vormittag oder Nachmittag?",es:"El miércoles me va bien. ¿Por la mañana o por la tarde?"},{de:"Lieber am Nachmittag, so gegen vier?",es:"Mejor por la tarde, ¿hacia las cuatro?"},{de:"Gut. Gehen wir in das neue Café am Markt?",es:"Vale. ¿Vamos al café nuevo del mercado?"},{de:"Das soll super sein, da wollte ich schon lange hin.",es:"Dicen que está genial, hace tiempo que quería ir."},{de:"Dann machen wir das so. Schreibst du mir noch die Adresse?",es:"Pues lo hacemos así. ¿Me mandas la dirección?"},{de:"Mache ich. Und wenn etwas dazwischenkommt, sag einfach Bescheid.",es:"Lo hago. Y si te surge algo, me avisas."},{de:"Klar. Bis Mittwoch dann!",es:"Claro. ¡Hasta el miércoles, entonces!"},{de:"Bis Mittwoch, ich freue mich!",es:"¡Hasta el miércoles, qué ganas!"}]},"Schade, dass du am Samstag nicht mitkommen kannst!":{de:"Ja, finde ich auch. Ich muss leider arbeiten.",es:"Sí, a mí también me da pena. Tengo que trabajar, por desgracia.",mas:[{de:"Den ganzen Tag?",es:"¿Todo el día?"},{de:"Bis drei. Danach bin ich zu müde für eine Wanderung.",es:"Hasta las tres. Después estoy demasiado cansada para andar."},{de:"Verstehe. Wir schicken dir Fotos vom Gipfel.",es:"Entiendo. Te mandamos fotos desde la cumbre."},{de:"Oh ja, bitte! Und erzählt mir am Montag alles.",es:"¡Ay, sí, por favor! Y el lunes me lo contáis todo."},{de:"Machen wir. Vielleicht können wir die Tour im Mai wiederholen.",es:"Hecho. A lo mejor podemos repetir la ruta en mayo."},{de:"Das wäre toll. Dann nehme ich mir frei.",es:"Sería estupendo. Entonces me cojo el día libre."},{de:"Versprochen? Ich schreibe es mir schon in den Kalender.",es:"¿Prometido? Ya lo apunto en el calendario."},{de:"Versprochen! Und viel Spaß am Samstag!",es:"¡Prometido! ¡Y que lo paséis bien el sábado!"}]},"Macht nichts, das holen wir bestimmt bald nach!":{de:"Danke, dass du nicht böse bist. Mir tut es wirklich leid.",es:"Gracias por no enfadarte. Lo siento de verdad.",mas:[{de:"Ach was, krank sein kann jeder mal.",es:"Qué va, ponerse malo le puede pasar a cualquiera."},{de:"Ich hätte mich so auf das Konzert gefreut.",es:"Con las ganas que tenía del concierto."},{de:"Die Band spielt im Herbst noch einmal in Linz.",es:"El grupo vuelve a tocar en otoño en Linz."},{de:"Wirklich? Dann kaufe ich die Karten, sobald es geht.",es:"¿De verdad? Pues compro las entradas en cuanto pueda."},{de:"Gute Idee, die sind sonst schnell ausverkauft.",es:"Buena idea, que si no se agotan enseguida."},{de:"Und was machst du jetzt mit meiner Karte?",es:"¿Y qué haces ahora con mi entrada?"},{de:"Ich frage meinen Bruder, der kommt bestimmt gern mit.",es:"Le pregunto a mi hermano, seguro que viene encantado."},{de:"Sehr gut. Und erhol dich gut!",es:"Muy bien. ¡Y que te recuperes!"}]},"Das war echt ein gelungener Tag, die Idee mit der Fähre war genial!":{de:"Freut mich, dass es dir gefallen hat!",es:"¡Me alegro de que te haya gustado!",mas:[{de:"Und das Essen in der Hütte war super.",es:"Y la comida en el refugio estuvo de lujo."},{de:"Ja, die Suppe war wirklich beeindruckend gut.",es:"Sí, la sopa estaba buenísima de verdad."},{de:"Wie hast du das Lokal überhaupt gefunden?",es:"¿Y cómo encontraste el sitio?"},{de:"Eine Kollegin hat es mir empfohlen.",es:"Me lo recomendó una compañera."},{de:"Dann sag ihr bitte danke von mir!",es:"¡Pues dale las gracias de mi parte!"},{de:"Mache ich. Nächstes Mal planst aber du den Ausflug.",es:"Lo haré. Pero la próxima excursión la planeas tú."},{de:"Gern. Ich hätte schon eine Idee: eine Höhle im Süden.",es:"Con gusto. Ya tengo una idea: una cueva en el sur."},{de:"Klingt spannend. Ich bin dabei!",es:"Suena emocionante. ¡Me apunto!"}]},"Laut Wetterbericht soll es am Samstag gewittrig werden.":{de:"Echt? Für den ganzen Tag?",es:"¿En serio? ¿Para todo el día?",mas:[{de:"Nein, erst ab dem Nachmittag. Vormittags soll es heiter sein.",es:"No, a partir de la tarde. Por la mañana estará despejado."},{de:"Dann fahren wir einfach früher los.",es:"Pues salimos antes y ya está."},{de:"Gute Idee. Um sieben?",es:"Buena idea. ¿A las siete?"},{de:"Um sieben ist hart, aber gut. Dann sind wir mittags zurück.",es:"A las siete es duro, pero vale. Así a mediodía estamos de vuelta."},{de:"Und nimm eine Regenjacke mit, für alle Fälle.",es:"Y llévate un chubasquero, por si acaso."},{de:"Mache ich. Bei Gewitter sollte man nicht auf dem Gipfel sein.",es:"Lo haré. Con tormenta no se debe estar en la cumbre."},{de:"Genau. Notfalls gehen wir nur bis zur Hütte.",es:"Eso es. Si hace falta, solo subimos hasta el refugio."},{de:"Einverstanden. Ich schaue morgen früh noch einmal auf die Wetter-App.",es:"De acuerdo. Mañana por la mañana vuelvo a mirar la aplicación del tiempo."}]},"Entschuldigung, gibt es eine Ermäßigung für Studenten?":{de:"Ja, mit Studentenausweis kostet der Eintritt sechs statt zwölf Euro.",es:"Sí, con carné de estudiante la entrada cuesta seis euros en vez de doce.",mas:[{de:"Super. Und für meine Tochter? Sie ist acht.",es:"Estupendo. ¿Y para mi hija? Tiene ocho años."},{de:"Kinder unter zehn sind gratis.",es:"Los menores de diez entran gratis."},{de:"Gibt es auch einen Audioguide?",es:"¿Hay también audioguía?"},{de:"Ja, in zwölf Sprachen, er kostet drei Euro extra.",es:"Sí, en doce idiomas, cuesta tres euros más."},{de:"Dann nehme ich einen auf Spanisch, bitte.",es:"Pues me llevo una en español, por favor."},{de:"Gern. Bitte geben Sie mir dafür kurz einen Ausweis.",es:"Con gusto. Para eso déjeme un momento un documento."},{de:"Hier, bitte. Bis wann haben Sie heute geöffnet?",es:"Tenga. ¿Hasta qué hora abren hoy?"},{de:"Bis achtzehn Uhr. Die letzte Führung ist um sechzehn Uhr.",es:"Hasta las seis. La última visita guiada es a las cuatro."}]},"Gestern war ich auf dem Straßenfest, das war total mitreißend!":{de:"Erzähl! Was war denn so toll?",es:"¡Cuenta! ¿Qué fue tan estupendo?",mas:[{de:"Es gab Musik aus zehn Ländern, und alle haben getanzt.",es:"Había música de diez países y bailaba todo el mundo."},{de:"Und das Essen? Ich habe gehört, es soll sehr gut gewesen sein.",es:"¿Y la comida? He oído que estaba muy buena."},{de:"Ja, ich habe syrische Süßigkeiten und peruanische Suppe probiert.",es:"Sí, probé dulces sirios y sopa peruana."},{de:"Klingt lecker. Waren viele Leute da?",es:"Suena rico. ¿Había mucha gente?"},{de:"Sehr viele, man musste sich überall anstellen.",es:"Muchísima, había que hacer cola en todas partes."},{de:"Und wie lange bist du geblieben?",es:"¿Y cuánto tiempo te quedaste?"},{de:"Bis Mitternacht, am Ende gab es noch ein Konzert.",es:"Hasta medianoche, al final todavía hubo un concierto."},{de:"Schade, dass ich nicht dabei war. Nächstes Jahr komme ich mit!",es:"Qué pena no haber estado. ¡El año que viene me apunto!"}]},"Entschuldigung, in welchem Stock finde ich die Haushaltswaren?":{de:"Im zweiten Obergeschoss, gleich neben der Rolltreppe.",es:"En la segunda planta, justo al lado de la escalera mecánica.",mas:[{de:"Und gibt es hier auch Elektrogeräte?",es:"¿Y aquí también hay electrodomésticos?"},{de:"Ja, die sind im Untergeschoss, beim Ausgang zur U-Bahn.",es:"Sí, están en el sótano, junto a la salida al metro."},{de:"Danke. Wo ist denn der Aufzug? Ich habe den Kinderwagen dabei.",es:"Gracias. ¿Dónde está el ascensor? Llevo el carrito."},{de:"Hinter der Parfümerie. Folgen Sie einfach dem Wegweiser.",es:"Detrás de la perfumería. Siga simplemente los carteles."},{de:"Und gibt es eine Kundentoilette mit Wickeltisch?",es:"¿Y hay un aseo para clientes con cambiador?"},{de:"Ja, im dritten Stock, neben dem Restaurant.",es:"Sí, en la tercera planta, al lado del restaurante."},{de:"Super. Bis wann haben Sie heute geöffnet?",es:"Genial. ¿Hasta qué hora abren hoy?"},{de:"Bis acht. Und samstags bis sechs.",es:"Hasta las ocho. Y los sábados hasta las seis."}]},"Ich suche so ein Ding, mit dem man Knoblauch zerdrückt.":{de:"Ah, Sie meinen eine Knoblauchpresse! Die haben wir hier.",es:"¡Ah, se refiere a un prensador de ajos! Los tenemos aquí.",mas:[{de:"Genau! Gibt es die auch aus Edelstahl?",es:"¡Eso! ¿Los hay también de acero inoxidable?"},{de:"Ja, diese hier. Sie ist robust und kann in die Spülmaschine.",es:"Sí, este de aquí. Es resistente y se puede meter en el lavavajillas."},{de:"Und noch etwas: Wie heißt das Teil, mit dem man Flaschen öffnet?",es:"Y otra cosa: ¿cómo se llama el chisme con el que se abren botellas?"},{de:"Meinen Sie einen Flaschenöffner oder einen Korkenzieher?",es:"¿Se refiere a un abridor o a un sacacorchos?"},{de:"Für Weinflaschen, also einen Korkenzieher.",es:"Para botellas de vino, o sea, un sacacorchos."},{de:"Die liegen da vorne, neben den Gläsern.",es:"Están allí delante, al lado de los vasos."},{de:"Vielen Dank, Sie haben mir sehr geholfen!",es:"¡Muchas gracias, me ha ayudado mucho!"},{de:"Gern geschehen. Brauchen Sie sonst noch etwas?",es:"De nada. ¿Necesita algo más?"}]},"Welchen Staubsauger würden Sie nehmen, den mit Kabel oder den mit Akku?":{de:"Das kommt darauf an. Der mit Akku ist handlicher, aber der andere ist stärker.",es:"Depende. La de batería es más manejable, pero la otra es más potente.",mas:[{de:"Und wie lange hält der Akku?",es:"¿Y cuánto dura la batería?"},{de:"Ungefähr vierzig Minuten. Für eine kleine Wohnung reicht das.",es:"Unos cuarenta minutos. Para un piso pequeño basta."},{de:"Meine Wohnung ist eher klein. Ist er auch leiser?",es:"Mi piso es más bien pequeño. ¿Y es más silenciosa?"},{de:"Ja, deutlich. Dafür ist er etwas teurer.",es:"Sí, bastante. A cambio es algo más cara."},{de:"Wie viel teurer denn?",es:"¿Cuánto más cara?"},{de:"Fünfzig Euro. Aber das Preis-Leistungs-Verhältnis ist sehr gut.",es:"Cincuenta euros. Pero la relación calidad-precio es muy buena."},{de:"Gut, dann nehme ich lieber das leichtere Modell.",es:"Bien, entonces prefiero el modelo más ligero."},{de:"Eine gute Wahl. Ich hole Ihnen einen neuen aus dem Lager.",es:"Buena elección. Le traigo una nueva del almacén."}]},"Können Sie mich kurz beraten? Ich suche eine gute Pfanne.":{de:"Gern. Kochen Sie mit Gas oder mit Induktion?",es:"Con gusto. ¿Cocina con gas o con inducción?",mas:[{de:"Mit Induktion. Ist das wichtig?",es:"Con inducción. ¿Es importante?"},{de:"Ja, nicht jede Pfanne funktioniert auf Induktion.",es:"Sí, no todas las sartenes funcionan en inducción."},{de:"Ah, das wusste ich nicht. Was empfehlen Sie mir?",es:"Ah, no lo sabía. ¿Qué me recomienda?"},{de:"Diese hier aus Edelstahl. Sie ist langlebig und hitzebeständig.",es:"Esta de acero inoxidable. Es duradera y resistente al calor."},{de:"Ist sie nicht ziemlich schwer?",es:"¿No pesa bastante?"},{de:"Ein bisschen, aber dafür hält sie ein Leben lang.",es:"Un poco, pero a cambio le dura toda la vida."},{de:"Und gibt es einen passenden Deckel dazu?",es:"¿Y hay una tapa a juego?"},{de:"Ja, den bekommen Sie heute sogar gratis dazu.",es:"Sí, hoy incluso se la regalamos con la sartén."}]},"Liefern Sie den Schrank auch nach Hause?":{de:"Ja, innerhalb von Wien ist die Lieferung kostenlos.",es:"Sí, dentro de Viena la entrega es gratuita.",mas:[{de:"Und wie lange ist die Lieferzeit?",es:"¿Y cuál es el plazo de entrega?"},{de:"Der Schrank ist leider nicht vorrätig, er muss nachbestellt werden.",es:"Por desgracia el armario no está en stock, hay que encargarlo."},{de:"Wie lange dauert das ungefähr?",es:"¿Cuánto tarda más o menos?"},{de:"Etwa zwei Wochen. Wir rufen Sie an, sobald er da ist.",es:"Unas dos semanas. Le llamamos en cuanto llegue."},{de:"Wird er auch aufgebaut?",es:"¿También lo montan?"},{de:"Ja, aber die Montage kostet vierzig Euro extra.",es:"Sí, pero el montaje cuesta cuarenta euros más."},{de:"In Ordnung. Kann ich in Raten zahlen?",es:"De acuerdo. ¿Puedo pagar a plazos?"},{de:"Ja, ab dreihundert Euro ist Ratenzahlung möglich.",es:"Sí, a partir de trescientos euros se puede pagar a plazos."}]},"Kann man diesen Pullover in der Maschine waschen?":{de:"Leider nicht. Er ist aus Kaschmir und darf nur von Hand gewaschen werden.",es:"Por desgracia no. Es de cachemira y solo se puede lavar a mano.",mas:[{de:"Das ist mir zu kompliziert. Haben Sie etwas Pflegeleichteres?",es:"Eso es demasiado complicado para mí. ¿Tiene algo más fácil de cuidar?"},{de:"Dieser hier ist aus Baumwolle und bei vierzig Grad waschbar.",es:"Este es de algodón y se puede lavar a cuarenta grados."},{de:"Muss er gebügelt werden?",es:"¿Hay que plancharlo?"},{de:"Nein, er ist knitterfrei. Einfach aufhängen.",es:"No, no se arruga. Basta con tenderlo."},{de:"Und darf er in den Trockner?",es:"¿Y se puede meter en la secadora?"},{de:"Lieber nicht, sonst wird er kleiner.",es:"Mejor no, si no encoge."},{de:"Gut zu wissen. Wo steht das denn?",es:"Bueno saberlo. ¿Y dónde lo pone?"},{de:"Innen auf dem Etikett stehen alle Pflegehinweise.",es:"Por dentro, en la etiqueta, vienen todas las instrucciones de lavado."}]},"Ich suche ein Geschenk für meine Schwiegermutter. Haben Sie eine Idee?":{de:"Was mag sie denn? Kocht sie gern oder liest sie lieber?",es:"¿Qué le gusta? ¿Le gusta cocinar o prefiere leer?",mas:[{de:"Sie trinkt sehr gern Tee und sitzt viel im Garten.",es:"Le encanta el té y pasa mucho tiempo en el jardín."},{de:"Wie wäre es mit einer Thermoskanne aus Edelstahl?",es:"¿Qué tal un termo de acero inoxidable?"},{de:"Hm, das ist ein bisschen unpersönlich.",es:"Mm, es algo impersonal."},{de:"Dann vielleicht eine Teetasse aus Porzellan mit Blumenmuster?",es:"¿Entonces quizá una taza de té de porcelana con flores?"},{de:"Die ist schön! Kann ich sie umtauschen, falls sie ihr nicht gefällt?",es:"¡Qué bonita! ¿La puedo cambiar si no le gusta?"},{de:"Natürlich, Sie haben vierzehn Tage Rückgaberecht.",es:"Claro, tiene catorce días para devolverla."},{de:"Perfekt. Können Sie sie mir als Geschenk einpacken?",es:"Perfecto. ¿Me la puede envolver para regalo?"},{de:"Gern, das Einpacken ist bei uns gratis.",es:"Con gusto, aquí envolver para regalo es gratis."}]},"Kaufst du eigentlich viel Neues oder lieber gebraucht?":{de:"Fast alles gebraucht. Im Secondhandladen findet man echte Schnäppchen.",es:"Casi todo de segunda mano. En las tiendas de segunda mano hay auténticos chollos.",mas:[{de:"Und was machst du, wenn etwas kaputtgeht?",es:"¿Y qué haces cuando se rompe algo?"},{de:"Ich bringe es in die Reparaturwerkstatt, bevor ich es wegwerfe.",es:"Lo llevo al taller antes de tirarlo."},{de:"Lohnt sich das denn? Neue Geräte sind oft billiger.",es:"¿Pero compensa? Los aparatos nuevos a menudo salen más baratos."},{de:"Nicht immer, aber reparierte Sachen halten oft viel länger.",es:"No siempre, pero las cosas reparadas a menudo duran mucho más."},{de:"Stimmt. Mein Toaster hat nur zwei Jahre gehalten.",es:"Es verdad. Mi tostador solo duró dos años."},{de:"Siehst du! Bei der Qualität sollte man nicht sparen.",es:"¡Lo ves! En calidad no hay que escatimar."},{de:"Und beim Einkaufen nimmst du immer einen Stoffbeutel mit, oder?",es:"Y cuando vas a comprar siempre llevas una bolsa de tela, ¿no?"},{de:"Klar, Plastiktüten kaufe ich schon lange nicht mehr.",es:"Claro, hace mucho que no compro bolsas de plástico."}]},"Ich möchte dieses Paket nach Spanien schicken.":{de:"Gern. Legen Sie es bitte auf die Waage.",es:"Con gusto. Póngalo en la báscula, por favor.",mas:[{de:"Was ist denn drin?",es:"¿Qué lleva dentro?"},{de:"Kleidung und ein paar Bücher, nichts Zerbrechliches.",es:"Ropa y unos libros, nada frágil."},{de:"Es wiegt vier Kilo. Normal oder als Expresssendung?",es:"Pesa cuatro kilos. ¿Normal o urgente?"},{de:"Was kostet das, und wie lange dauert es?",es:"¿Cuánto cuesta y cuánto tarda?"},{de:"Normal sind es zwanzig Euro und etwa fünf Tage.",es:"Normal son veinte euros y unos cinco días."},{de:"Das reicht mir. Muss ich ein Formular ausfüllen?",es:"Me vale. ¿Tengo que rellenar algún formulario?"},{de:"Innerhalb der EU brauchen Sie keine Zollerklärung.",es:"Dentro de la UE no necesita declaración de aduana."},{de:"Super. Und bekomme ich eine Sendungsnummer?",es:"Genial. ¿Y me dan un número de envío?"}]},"Mein Paket sollte schon seit drei Tagen da sein.":{de:"Haben Sie die Sendungsnummer? Dann schaue ich nach.",es:"¿Tiene el número de envío? Entonces lo miro.",mas:[{de:"Ja, hier ist sie, auf dem Beleg.",es:"Sí, aquí está, en el resguardo."},{de:"Laut Sendungsverfolgung wurde es gestern zugestellt.",es:"Según el seguimiento, se entregó ayer."},{de:"Aber ich war den ganzen Tag zu Hause!",es:"¡Pero estuve todo el día en casa!"},{de:"Hier steht: beim Nachbarn abgegeben, Hausnummer zwölf.",es:"Aquí pone: entregado al vecino, número doce."},{de:"Komisch, ich habe keinen Abholschein bekommen.",es:"Qué raro, no he recibido ningún aviso de recogida."},{de:"Fragen Sie am besten zuerst beim Nachbarn.",es:"Lo mejor es que pregunte primero al vecino."},{de:"Und wenn es dort nicht ist?",es:"¿Y si no está allí?"},{de:"Dann rufen Sie uns an, und wir starten eine Suche.",es:"Entonces llámenos y abrimos una búsqueda."}]},"Entschuldigung, haben Sie ein Paket für mich angenommen?":{de:"Ja, gestern Vormittag. Warten Sie, ich hole es.",es:"Sí, ayer por la mañana. Espere, que se lo traigo.",mas:[{de:"Vielen Dank, das ist wirklich nett von Ihnen.",es:"Muchas gracias, es muy amable por su parte."},{de:"Kein Problem, ich bin ja meistens zu Hause.",es:"No hay de qué, casi siempre estoy en casa."},{de:"Es ist ziemlich schwer, oder?",es:"Pesa bastante, ¿no?"},{de:"Ja, der Zusteller hat es kaum die Treppe hinaufgeschafft.",es:"Sí, al repartidor casi no le dio para subirlo por la escalera."},{de:"Das sind neue Küchengeräte. Darf ich Ihnen als Dank Kekse vorbeibringen?",es:"Son electrodomésticos nuevos. ¿Le puedo traer unas galletas para darle las gracias?"},{de:"Ach, das brauchen Sie nicht. Das mache ich gern.",es:"Ay, no hace falta. Lo hago con gusto."},{de:"Und wenn Sie mal nicht da sind, nehme ich Ihre Pakete an.",es:"Y si alguna vez no está, le recojo yo los paquetes."},{de:"Abgemacht, so helfen wir uns gegenseitig.",es:"Trato hecho, así nos ayudamos mutuamente."}]},"Seit dem letzten Update stürzt mein Laptop ständig ab.":{de:"Das tut mir leid. Seit wann genau haben Sie das Problem?",es:"Lo siento. ¿Desde cuándo exactamente tiene el problema?",mas:[{de:"Seit Montag. Immer wenn ich den Browser öffne.",es:"Desde el lunes. Siempre que abro el navegador."},{de:"Erscheint dabei eine Fehlermeldung?",es:"¿Aparece algún mensaje de error?"},{de:"Ja, irgendetwas mit Speicherplatz. Ich habe es nicht ganz verstanden.",es:"Sí, algo del espacio de almacenamiento. No lo entendí del todo."},{de:"Haben Sie das Gerät schon neu gestartet?",es:"¿Ha reiniciado ya el aparato?"},{de:"Schon mehrmals, aber es hilft nichts.",es:"Varias veces, pero no sirve de nada."},{de:"Dann löschen Sie bitte zuerst alte Dateien und Downloads.",es:"Entonces borre primero archivos y descargas antiguos, por favor."},{de:"Und wenn das nicht funktioniert?",es:"¿Y si eso no funciona?"},{de:"Dann schicken Sie ihn ein. Er hat ja noch Garantie.",es:"Entonces envíenoslo. Todavía tiene garantía."}]},"Oma, ich zeige dir jetzt, wie man einen Videoanruf macht.":{de:"Gut, aber langsam, bitte. Ich bin nicht so schnell wie du.",es:"Bien, pero despacio, por favor. No soy tan rápida como tú.",mas:[{de:"Zuerst entsperrst du das Handy mit deiner PIN.",es:"Primero desbloqueas el móvil con tu PIN."},{de:"So? Ah, jetzt sehe ich die Apps.",es:"¿Así? Ah, ya veo las apps."},{de:"Genau. Dann tippst du auf das grüne Symbol.",es:"Eso es. Luego tocas el símbolo verde."},{de:"Und danach suche ich deinen Namen, oder?",es:"Y después busco tu nombre, ¿no?"},{de:"Richtig. Und zum Schluss drückst du auf die Kamera.",es:"Correcto. Y por último pulsas la cámara."},{de:"Oh, da bist du ja! Ich kann dich sehen!",es:"¡Oh, ahí estás! ¡Te veo!"},{de:"Siehst du, du brauchst gar keine Angst vor der Technik zu haben.",es:"¿Ves? No tienes por qué tenerle miedo a la tecnología."},{de:"Schreib mir das bitte trotzdem auf einen Zettel.",es:"Pero apúntamelo igualmente en un papel, por favor."}]},"Ich suche einen günstigeren Tarif. Was können Sie mir anbieten?":{de:"Wie viel Datenvolumen brauchen Sie ungefähr im Monat?",es:"¿Cuántos datos necesita más o menos al mes?",mas:[{de:"Nicht so viel, zu Hause habe ich ja WLAN.",es:"No mucho, en casa tengo wifi."},{de:"Dann passt dieser hier: zehn Gigabyte für zwölf Euro.",es:"Entonces le va bien esta: diez gigas por doce euros."},{de:"Und wie lange ist die Laufzeit?",es:"¿Y cuánto dura el contrato?"},{de:"Es gibt keine Mindestlaufzeit, Sie können jeden Monat kündigen.",es:"No hay permanencia, puede darse de baja cualquier mes."},{de:"Gibt es eine Grundgebühr oder Extrakosten im Ausland?",es:"¿Hay cuota fija o costes extra en el extranjero?"},{de:"In der EU telefonieren und surfen Sie ohne Extrakosten.",es:"En la UE llama y navega sin costes extra."},{de:"Klingt gut. Kann ich meine Nummer behalten?",es:"Suena bien. ¿Puedo mantener mi número?"},{de:"Ja, wir kümmern uns um alles. Sie bekommen nur eine neue SIM-Karte.",es:"Sí, nos encargamos de todo. Usted solo recibe una tarjeta SIM nueva."}]},"Ich möchte meinen Internetvertrag zum Monatsende kündigen.":{de:"Darf ich fragen, warum Sie kündigen möchten?",es:"¿Puedo preguntarle por qué quiere darse de baja?",mas:[{de:"Ich ziehe um, und an der neuen Adresse bieten Sie kein Internet an.",es:"Me mudo, y en la nueva dirección ustedes no ofrecen internet."},{de:"Verstehe. Haben Sie Ihre Kundennummer zur Hand?",es:"Entiendo. ¿Tiene a mano su número de cliente?"},{de:"Ja, die Nummer lautet vier, sieben, eins, eins, null, neun.",es:"Sí, el número es cuatro, siete, uno, uno, cero, nueve."},{de:"Danke. Ihre Kündigungsfrist beträgt leider drei Monate.",es:"Gracias. Por desgracia su plazo de preaviso es de tres meses."},{de:"Drei Monate? Gibt es bei einem Umzug keine Ausnahme?",es:"¿Tres meses? ¿No hay excepción en caso de mudanza?"},{de:"Doch, mit einer Meldebestätigung geht es schneller.",es:"Sí, con un certificado de empadronamiento va más rápido."},{de:"Gut, die schicke ich Ihnen per E-Mail.",es:"Bien, se lo mando por correo electrónico."},{de:"Perfekt. Sie bekommen dann eine schriftliche Bestätigung.",es:"Perfecto. Luego recibirá una confirmación por escrito."}]},"Hallo Petra, hier ist Ana. Ich habe eine neue Handynummer, ruf mich bitte zurück.":{de:"Hallo Ana, ich habe gerade deine Nachricht auf der Mailbox abgehört.",es:"Hola, Ana, acabo de escuchar tu mensaje en el buzón de voz.",mas:[{de:"Super. Warum hast du denn eine neue Nummer?",es:"Genial. ¿Y por qué tienes número nuevo?"},{de:"Ich habe den Anbieter gewechselt, der alte Vertrag war zu teuer.",es:"He cambiado de compañía, el contrato antiguo era demasiado caro."},{de:"Konntest du deine alte Nummer nicht behalten?",es:"¿No podías mantener tu número antiguo?"},{de:"Doch, aber das hätte noch zwei Wochen gedauert.",es:"Sí, pero habría tardado dos semanas más."},{de:"Verstehe. Deine Nachricht war übrigens kaum zu hören.",es:"Entiendo. Por cierto, tu mensaje casi no se oía."},{de:"Ich war im Zug, da gibt es viele Funklöcher.",es:"Iba en el tren, ahí hay muchas zonas sin cobertura."},{de:"Kein Wunder. Ich speichere die neue Nummer gleich ein.",es:"Normal. Ahora mismo guardo el número nuevo."},{de:"Danke! Und schick sie bitte auch an Jonas weiter.",es:"¡Gracias! Y pásaselo también a Jonas, por favor."}]},"Guten Tag, ich möchte gern ein Girokonto eröffnen.":{de:"Gern. Haben Sie einen Ausweis und eine Meldebestätigung dabei?",es:"Con gusto. ¿Trae un documento de identidad y el certificado de empadronamiento?",mas:[{de:"Ja, hier sind beide. Was kostet das Konto?",es:"Sí, aquí tiene los dos. ¿Cuánto cuesta la cuenta?"},{de:"Drei Euro neunzig im Monat. Für Studierende ist es gebührenfrei.",es:"Tres euros noventa al mes. Para estudiantes no tiene comisiones."},{de:"Ich bin leider keine Studentin mehr.",es:"Por desgracia ya no soy estudiante."},{de:"Kein Problem. Dazu bekommen Sie eine Karte und Onlinebanking.",es:"No pasa nada. Además le damos una tarjeta y banca online."},{de:"Und wann kann ich die Karte benutzen?",es:"¿Y cuándo podré usar la tarjeta?"},{de:"Sie kommt in etwa einer Woche per Post, die Geheimzahl getrennt.",es:"Le llega por correo en una semana más o menos, y el PIN por separado."},{de:"Gut. Muss ich sonst noch etwas unterschreiben?",es:"Bien. ¿Tengo que firmar algo más?"},{de:"Nur hier unten, dann ist Ihr Konto eröffnet.",es:"Solo aquí abajo, y su cuenta queda abierta."}]},"Entschuldigung, der Geldautomat hat meine Karte nicht mehr herausgegeben.":{de:"Oh, das tut mir leid. Was ist denn passiert?",es:"Vaya, lo siento. ¿Qué ha pasado?",mas:[{de:"Ich habe dreimal die falsche Geheimzahl eingegeben.",es:"Metí mal el PIN tres veces."},{de:"Dann behält der Automat die Karte aus Sicherheitsgründen.",es:"Entonces el cajero se queda la tarjeta por seguridad."},{de:"Und wie bekomme ich sie zurück?",es:"¿Y cómo la recupero?"},{de:"Sind Sie Kundin bei uns? Dann bekommen Sie sie morgen am Schalter.",es:"¿Es usted clienta nuestra? Entonces se la damos mañana en la ventanilla."},{de:"Ja, ich habe hier mein Konto. Brauchen Sie meinen Ausweis?",es:"Sí, tengo aquí mi cuenta. ¿Necesita mi documento?"},{de:"Ja, bitte. Und die Geheimzahl sollten Sie sich gut merken.",es:"Sí, por favor. Y conviene que recuerde bien el PIN."},{de:"Ich weiß, ich habe sie irgendwo aufgeschrieben.",es:"Lo sé, lo tengo apuntado en algún sitio."},{de:"Am besten nicht neben der Karte aufbewahren!",es:"¡Mejor no lo guarde junto a la tarjeta!"}]},"Ich möchte diese Rechnung überweisen, aber ich habe kein Onlinebanking.":{de:"Kein Problem, das können wir hier am Schalter machen.",es:"No pasa nada, lo podemos hacer aquí en la ventanilla.",mas:[{de:"Wie lautet die IBAN des Empfängers?",es:"¿Cuál es el IBAN del destinatario?"},{de:"Sie steht hier unten auf der Rechnung.",es:"Viene aquí abajo, en la factura."},{de:"Danke. Und was soll als Verwendungszweck stehen?",es:"Gracias. ¿Y qué pongo como concepto?"},{de:"Bitte die Rechnungsnummer, sonst finden sie die Zahlung nicht.",es:"El número de factura, por favor; si no, no encuentran el pago."},{de:"Gut. Der Betrag ist 245 Euro 60, richtig?",es:"Bien. El importe es de 245 euros con 60, ¿correcto?"},{de:"Ja, genau. Wann kommt das Geld an?",es:"Sí, exacto. ¿Cuándo llega el dinero?"},{de:"Normalerweise am nächsten Werktag.",es:"Normalmente al siguiente día laborable."},{de:"Perfekt, die Rechnung ist nämlich übermorgen fällig.",es:"Perfecto, porque la factura vence pasado mañana."}]},"Mir wurde gerade die Geldbörse gestohlen, ich muss meine Karte sperren.":{de:"Das machen wir sofort. Wie ist Ihr Name und Ihr Geburtsdatum?",es:"Lo hacemos enseguida. ¿Me dice su nombre y su fecha de nacimiento?",mas:[{de:"Laura Pérez, geboren am dritten Mai 1990.",es:"Laura Pérez, nacida el tres de mayo de 1990."},{de:"Danke. Können Sie mir noch Ihre Sicherheitsfrage beantworten?",es:"Gracias. ¿Puede contestarme también la pregunta de seguridad?"},{de:"Mein erster Hund hieß Bruno.",es:"Mi primer perro se llamaba Bruno."},{de:"Richtig. Die Karte ist jetzt gesperrt.",es:"Correcto. La tarjeta ya está bloqueada."},{de:"Gott sei Dank. Wurde schon etwas abgebucht?",es:"Menos mal. ¿Han cargado ya algo?"},{de:"Nein, es gibt keine verdächtigen Abbuchungen.",es:"No, no hay ningún cargo sospechoso."},{de:"Und wie bekomme ich eine neue Karte?",es:"¿Y cómo consigo una tarjeta nueva?"},{de:"Die schicken wir Ihnen zu. Machen Sie bitte auch eine Anzeige bei der Polizei.",es:"Se la enviamos. Ponga también una denuncia en la policía, por favor."}]},"Wir möchten eine Wohnung kaufen und brauchen dafür einen Kredit.":{de:"Gern berate ich Sie. Wie viel Eigenkapital haben Sie ungefähr?",es:"Con gusto les asesoro. ¿Cuánto capital propio tienen más o menos?",mas:[{de:"Ungefähr ein Drittel des Kaufpreises haben wir gespart.",es:"Hemos ahorrado aproximadamente un tercio del precio."},{de:"Das ist eine gute Basis. Wie hoch soll die monatliche Rate sein?",es:"Es una buena base. ¿De cuánto quieren que sea la cuota mensual?"},{de:"Höchstens achthundert Euro, sonst wird es knapp.",es:"Como mucho ochocientos euros; si no, vamos justos."},{de:"Dann kommt eine Laufzeit von fünfundzwanzig Jahren in Frage.",es:"Entonces podría ser un plazo de veinticinco años."},{de:"Und wie hoch sind die Zinsen im Moment?",es:"¿Y cómo están los intereses ahora?"},{de:"Etwa drei Komma fünf Prozent, fest für zehn Jahre.",es:"Alrededor del tres coma cinco por ciento, fijo durante diez años."},{de:"Können wir den Kredit auch früher zurückzahlen?",es:"¿Podemos devolver el préstamo antes?"},{de:"Ja, jedes Jahr können Sie bis zu fünf Prozent extra zurückzahlen.",es:"Sí, cada año pueden devolver hasta un cinco por ciento extra."}]},"Ich möchte zweihundert Euro in Schweizer Franken wechseln.":{de:"Gern. Der Wechselkurs liegt heute bei null Komma neun fünf.",es:"Con gusto. El cambio hoy está a cero coma noventa y cinco.",mas:[{de:"Gibt es dafür eine Gebühr?",es:"¿Hay alguna comisión?"},{de:"Ja, ein Prozent, mindestens aber drei Euro.",es:"Sí, un uno por ciento, pero como mínimo tres euros."},{de:"Hm, ist es nicht günstiger, in der Schweiz abzuheben?",es:"Mm, ¿no sale más barato sacar dinero en Suiza?"},{de:"Das kommt auf Ihre Karte an. Fragen Sie am besten Ihre Bank.",es:"Depende de su tarjeta. Lo mejor es que pregunte a su banco."},{de:"Ich nehme trotzdem ein bisschen Bargeld für die ersten Tage.",es:"De todos modos me llevo algo de efectivo para los primeros días."},{de:"Möchten Sie lieber große oder kleine Scheine?",es:"¿Prefiere billetes grandes o pequeños?"},{de:"Lieber kleine, und ein paar Münzen für den Bus.",es:"Mejor pequeños, y unas monedas para el autobús."},{de:"Bitte sehr, zählen Sie ruhig nach.",es:"Aquí tiene; cuéntelo si quiere."}]},"Du, kannst du mir vielleicht bis Ende des Monats fünfzig Euro leihen?":{de:"Klar, kein Problem. Was ist denn passiert?",es:"Claro, sin problema. ¿Qué ha pasado?",mas:[{de:"Die Waschmaschine ist kaputt, und die Reparatur war teurer als gedacht.",es:"Se ha estropeado la lavadora y la reparación ha salido más cara de lo que pensaba."},{de:"So was passiert immer im falschen Moment.",es:"Estas cosas siempre pasan en el peor momento."},{de:"Eben. Und mein Gehalt kommt erst am Ersten.",es:"Eso. Y mi sueldo no llega hasta el día uno."},{de:"Soll ich es dir überweisen oder lieber bar geben?",es:"¿Te lo transfiero o prefieres que te lo dé en efectivo?"},{de:"Überweisen ist super, dann muss ich nicht zum Automaten.",es:"Por transferencia es genial, así no tengo que ir al cajero."},{de:"Gut, ich mache es gleich mit dem Handy.",es:"Vale, lo hago ahora mismo con el móvil."},{de:"Danke! Am Ersten bekommst du es sofort zurück.",es:"¡Gracias! El día uno te lo devuelvo enseguida."},{de:"Keine Eile, ich weiß ja, dass du es zurückzahlst.",es:"Sin prisa, ya sé que me lo vas a devolver."}]},"Wie schaffst du es eigentlich, jeden Monat etwas zu sparen?":{de:"Ich führe ein Haushaltsbuch, da sehe ich genau, wohin mein Geld geht.",es:"Llevo un libro de cuentas, así veo exactamente adónde va mi dinero.",mas:[{de:"Ein Haushaltsbuch? Auf Papier?",es:"¿Un libro de cuentas? ¿En papel?"},{de:"Nein, in einer App. Ich trage alle Ausgaben ein.",es:"No, en una app. Apunto todos los gastos."},{de:"Und was hast du dabei herausgefunden?",es:"¿Y qué has descubierto?"},{de:"Dass ich viel zu viel Geld fürs Essengehen ausgegeben habe.",es:"Que me gastaba demasiado en comer fuera."},{de:"Das kenne ich. Bei mir sind es die Onlinekäufe.",es:"Me suena. En mi caso son las compras por internet."},{de:"Ich habe jetzt einen Dauerauftrag aufs Sparkonto, gleich am Monatsanfang.",es:"Ahora tengo una transferencia periódica a la cuenta de ahorro, justo a principio de mes."},{de:"Clever, dann gibt man das Geld gar nicht erst aus.",es:"Muy listo; así ni llegas a gastarte el dinero."},{de:"Genau. Und für Notfälle habe ich einen kleinen Notgroschen.",es:"Exacto. Y para emergencias tengo un pequeño colchón."}]},"Vielen Dank für die Einladung zu eurer Hochzeit!":{de:"Schön, dass du dich meldest! Kannst du denn kommen?",es:"¡Qué bien que me escribas! ¿Puedes venir?",mas:[{de:"Ja, sehr gern! Ich komme mit meinem Freund, wenn das in Ordnung ist.",es:"¡Sí, encantada! Vendré con mi novio, si os parece bien."},{de:"Klar, er ist herzlich willkommen. Kommt ihr auch schon zur Trauung?",es:"Claro, es muy bienvenido. ¿Venís también a la ceremonia?"},{de:"Ja. Wann fängt die standesamtliche Trauung an?",es:"Sí. ¿A qué hora empieza la boda civil?"},{de:"Um elf Uhr, danach feiern wir im Gasthof am See.",es:"A las once; después lo celebramos en el restaurante del lago."},{de:"Gibt es einen Dresscode?",es:"¿Hay código de vestimenta?"},{de:"Nicht wirklich, nur bitte nicht ganz in Weiß.",es:"No mucho; solo que nadie vaya todo de blanco, por favor."},{de:"Haha, verstanden. Habt ihr eine Wunschliste?",es:"Jaja, entendido. ¿Tenéis lista de bodas?"},{de:"Am meisten freuen wir uns über einen Beitrag zu den Flitterwochen.",es:"Lo que más nos alegraría es una aportación para la luna de miel."}]},"Herzlichen Glückwunsch zur Geburt eurer Tochter!":{de:"Danke! Wir sind noch ganz müde, aber unglaublich glücklich.",es:"¡Gracias! Todavía estamos muy cansados, pero increíblemente felices.",mas:[{de:"Wie heißt die Kleine denn?",es:"¿Y cómo se llama la pequeña?"},{de:"Sie heißt Mia. Sie kam am Sonntag um drei Uhr morgens zur Welt.",es:"Se llama Mia. Nació el domingo a las tres de la mañana."},{de:"Und wie geht es dir nach der Entbindung?",es:"¿Y tú cómo estás después del parto?"},{de:"Gut, die Hebamme war super. Als ich Mia im Arm hatte, war aller Stress vergessen.",es:"Bien, la comadrona fue genial. Cuando tuve a Mia en brazos, se me olvidó todo el estrés."},{de:"Wann dürfen wir euch besuchen?",es:"¿Cuándo podemos ir a veros?"},{de:"Am besten nächste Woche, sobald wir zu Hause etwas Routine haben.",es:"Mejor la semana que viene, en cuanto tengamos un poco de rutina en casa."},{de:"Gern! Braucht ihr noch etwas? Windeln vielleicht?",es:"¡Claro! ¿Necesitáis algo? ¿Pañales, quizá?"},{de:"Windeln haben wir genug, aber über etwas Gekochtes würden wir uns riesig freuen!",es:"Pañales tenemos de sobra, ¡pero algo de comida hecha nos haría muchísima ilusión!"}]},"Nächsten Monat wird Papa sechzig. Sollen wir eine Überraschungsparty machen?":{de:"Gute Idee! Aber er darf auf keinen Fall etwas merken.",es:"¡Buena idea! Pero no puede enterarse de nada.",mas:[{de:"Ich mache die Gästeliste. Wen sollen wir einladen?",es:"Yo hago la lista de invitados. ¿A quién invitamos?"},{de:"Die ganze Familie und seine alten Kollegen. Das sind etwa vierzig Leute.",es:"A toda la familia y a sus antiguos compañeros. Serán unas cuarenta personas."},{de:"Wo feiern wir? Unser Wohnzimmer ist zu klein.",es:"¿Dónde lo celebramos? Nuestro salón es demasiado pequeño."},{de:"Wir könnten den Saal im Sportverein mieten.",es:"Podríamos alquilar el salón del club deportivo."},{de:"Und wie bekommen wir ihn dorthin, ohne dass er etwas ahnt?",es:"¿Y cómo lo llevamos allí sin que sospeche nada?"},{de:"Mama sagt einfach, sie will mit ihm essen gehen.",es:"Mamá le dice que quiere salir a cenar con él, y ya está."},{de:"Perfekt. Sobald er reinkommt, rufen alle «Überraschung!».",es:"Perfecto. En cuanto entre, todos gritan «¡Sorpresa!»."},{de:"Und dann bringe ich den Geburtstagskuchen mit sechzig Kerzen!",es:"¡Y entonces saco la tarta de cumpleaños con sesenta velas!"}]},"Und, wie war die Hochzeit deiner Cousine?":{de:"Unvergesslich! Aber am Anfang ging fast alles schief.",es:"¡Inolvidable! Pero al principio casi todo salió mal.",mas:[{de:"Wirklich? Was ist denn passiert?",es:"¿En serio? ¿Pues qué pasó?"},{de:"Der Bräutigam hatte die Ringe zu Hause vergessen.",es:"El novio se había dejado los anillos en casa."},{de:"Oh nein! Und dann?",es:"¡Oh, no! ¿Y entonces?"},{de:"Sein Bruder ist schnell zurückgefahren. Als er wiederkam, hatte die Trauung schon angefangen.",es:"Su hermano volvió corriendo a por ellos. Cuando regresó, la ceremonia ya había empezado."},{de:"Und das Fest danach?",es:"¿Y la fiesta de después?"},{de:"Traumhaft. Nachdem der Vater der Braut eine rührende Rede gehalten hatte, haben alle geweint.",es:"De ensueño. Después del discurso tan conmovedor del padre de la novia, lloró todo el mundo."},{de:"Habt ihr lange gefeiert?",es:"¿Estuvisteis de fiesta hasta tarde?"},{de:"Bis in die Morgenstunden! Ich habe die ganze Nacht getanzt.",es:"¡Hasta la madrugada! Bailé toda la noche."}]},"Wie feiert ihr eigentlich das Ende vom Ramadan?":{de:"Mit dem Zuckerfest! Das dauert bei uns drei Tage.",es:"¡Con la fiesta del fin del ramadán! En mi familia dura tres días.",mas:[{de:"Und was macht man an diesen Tagen?",es:"¿Y qué se hace esos días?"},{de:"Wir besuchen die ganze Verwandtschaft, und überall gibt es Süßigkeiten.",es:"Visitamos a todos los parientes, y en todas partes hay dulces."},{de:"Bekommen die Kinder auch Geschenke?",es:"¿Los niños también reciben regalos?"},{de:"Ja, meistens etwas Geld. Als ich klein war, war das für mich das Beste.",es:"Sí, normalmente algo de dinero. Cuando era pequeño, eso era lo mejor para mí."},{de:"Das klingt ein bisschen wie Weihnachten bei uns.",es:"Suena un poco a nuestra Navidad."},{de:"Stimmt! Wie feiert ihr denn Weihnachten?",es:"¡Es verdad! ¿Y vosotros cómo celebráis la Navidad?"},{de:"Ganz traditionell: Am Heiligabend gibt es die Geschenke unter dem Weihnachtsbaum.",es:"Muy tradicional: en Nochebuena abrimos los regalos bajo el árbol."},{de:"Das würde ich gern einmal miterleben!",es:"¡Me encantaría vivirlo alguna vez!"}]},"Danke noch mal für den schönen Abend gestern!":{de:"Gern geschehen! Schön, dass ihr da wart.",es:"¡No hay de qué! Qué bien que vinierais.",mas:[{de:"Das Essen war fantastisch. Hast du das alles selbst gekocht?",es:"La comida estaba buenísima. ¿Lo cocinaste todo tú?"},{de:"Nein, nur den Nachtisch. Den Rest hat ein Caterer geliefert.",es:"No, solo el postre. El resto lo trajo un catering."},{de:"Und die Dekoration mit den Girlanden war so liebevoll!",es:"¡Y la decoración con las guirnaldas estaba tan cuidada!"},{de:"Danke! Meine Kinder hatten den ganzen Nachmittag dekoriert.",es:"¡Gracias! Mis hijos se habían pasado toda la tarde decorando."},{de:"Wir sind leider früh gegangen, weil der Babysitter nur bis elf konnte.",es:"Por desgracia nos fuimos pronto porque el canguro solo podía hasta las once."},{de:"Kein Problem. Die anderen sind auch bald danach gegangen.",es:"No pasa nada. Los demás se fueron también poco después."},{de:"Nächstes Mal feiern wir bei uns, versprochen!",es:"La próxima vez lo celebramos en casa, ¡prometido!"},{de:"Da sage ich nicht Nein!",es:"¡No diré que no!"}]},"Ich habe gehört, dass dein Vater gestorben ist. Mein herzliches Beileid.":{de:"Danke, das ist lieb von dir. Am Ende ging es sehr schnell.",es:"Gracias, es muy amable por tu parte. Al final fue todo muy rápido.",mas:[{de:"Das tut mir so leid. Wie geht es dir und deiner Mutter?",es:"Lo siento muchísimo. ¿Cómo estáis tu madre y tú?"},{de:"Es ist schwer, aber wir halten zusammen.",es:"Es duro, pero nos apoyamos mucho."},{de:"Wann ist die Beerdigung?",es:"¿Cuándo es el entierro?"},{de:"Am Freitag um zehn auf dem Friedhof in seinem Heimatdorf.",es:"El viernes a las diez en el cementerio de su pueblo."},{de:"Ich würde gern kommen, wenn das für euch in Ordnung ist.",es:"Me gustaría ir, si os parece bien."},{de:"Natürlich, er hat dich immer sehr gemocht.",es:"Claro, siempre te tuvo mucho cariño."},{de:"Wenn ich irgendwie helfen kann, sag einfach Bescheid.",es:"Si puedo ayudar en algo, dímelo sin más."},{de:"Danke. Es tut gut zu wissen, dass ihr da seid.",es:"Gracias. Me hace bien saber que estáis ahí."}]},"Weißt du noch, als wir zusammen in der Schule waren?":{de:"Klar! Das ist jetzt schon zwanzig Jahre her.",es:"¡Claro! Ya hace veinte años de eso.",mas:[{de:"Damals hatten wir noch keine Handys. Wir haben uns Zettel geschrieben!",es:"Entonces todavía no teníamos móvil. ¡Nos escribíamos notitas!"},{de:"Und immer wenn der Lehrer einen Zettel erwischt hat, hat er ihn laut vorgelesen.",es:"Y siempre que el profesor pillaba una, la leía en voz alta."},{de:"Stimmt! Was ist eigentlich aus den anderen geworden?",es:"¡Es verdad! ¿Y qué ha sido de los demás?"},{de:"Die meisten wohnen inzwischen woanders. Tom hat sogar schon drei Kinder.",es:"La mayoría ya vive en otro sitio. Tom incluso tiene ya tres hijos."},{de:"Wahnsinn! Wir sollten mal ein Klassentreffen organisieren.",es:"¡Qué fuerte! Deberíamos organizar un reencuentro de la clase."},{de:"Gute Idee! Nächsten Sommer vielleicht?",es:"¡Buena idea! ¿El verano que viene, quizá?"},{de:"Ich schreibe allen, sobald ich die Adressen habe.",es:"Les escribo a todos en cuanto tenga las direcciones."},{de:"Super, ich freue mich schon auf das Wiedersehen!",es:"¡Genial, ya tengo ganas del reencuentro!"}]}},i={"Guten Tag, ich bin Álvaro Romero.":{de:"Guten Tag, Herr Romero. Freut mich sehr. Ich bin Frau Berger und arbeite hier im Büro.",es:"Buenos días, señor Romero. Encantada. Soy la señora Berger y trabajo aquí en la oficina.",mas:[{de:"Freut mich, Sie kennenzulernen.",es:"Encantado de conocerle."},{de:"Ganz meinerseits. Ich habe schon viel von Ihnen gehört.",es:"Igualmente. Ya he oído hablar mucho de usted."},{de:"Das ist mein Kollege, Herr Öztürk.",es:"Este es mi compañero, el señor Öztürk."},{de:"Guten Tag, Herr Öztürk. Freut mich. Arbeiten Sie auch schon lange hier?",es:"Buenos días, señor Öztürk. Encantado. ¿Usted también lleva mucho tiempo trabajando aquí?"},{de:"Sagen Sie ruhig du zu mir.",es:"Puede tutearme tranquilamente."},{de:"Gern, dann sind wir per du. Ich bin die Martina.",es:"Con mucho gusto, entonces nos tuteamos. Yo soy Martina."}]},"Darf ich fragen, wie Sie heißen?":{de:"Natürlich. Ich heiße Ayla Öztürk.",es:"Por supuesto. Me llamo Ayla Öztürk.",mas:[{de:"Wie schreibt man Ihren Namen?",es:"¿Cómo se escribe su nombre?"},{de:"Ö-Z-T-Ü-R-K. Das Ö am Anfang vergessen die meisten.",es:"Ö-Z-T-Ü-R-K. La mayoría se olvida de la Ö del principio."},{de:"Entschuldigung, wie spricht man Ihren Namen aus?",es:"Perdone, ¿cómo se pronuncia su nombre?"},{de:"Öztürk, der Ton kommt auf die erste Silbe. Das ist für alle schwierig.",es:"Öztürk, el acento va en la primera sílaba. A todo el mundo le cuesta."},{de:"Wie heißen Sie, bitte?",es:"¿Cómo se llama usted, por favor?"},{de:"Wagner, Peter Wagner. Ich bin mit Frau Öztürk gekommen.",es:"Wagner, Peter Wagner. He venido con la señora Öztürk."}]},"Wie geht's? – Danke, gut.":{de:"Und dir? Alles in Ordnung?",es:"¿Y tú? ¿Todo bien?",mas:[{de:"Sehr gut. · Es geht. · Nicht so gut.",es:"Muy bien. · Va tirando. · No muy bien."},{de:"Das freut mich. Bei mir ist diese Woche auch alles ruhig.",es:"Me alegro. Esta semana a mí también me va todo tranquilo."},{de:"Und selbst?",es:"¿Y tú qué tal?"},{de:"Auch gut, danke. Viel Arbeit im Moment, aber das ist kein Problem.",es:"Bien también, gracias. Ahora hay mucho trabajo, pero no pasa nada."},{de:"Wie läuft es gerade bei dir?",es:"¿Cómo te va ahora mismo?"},{de:"Ganz gut. Viel Arbeit, aber ich beschwere mich nicht.",es:"Bastante bien. Mucho trabajo, pero no me quejo."}]},"Woher kommst du? Wo wohnst du?":{de:"Aus Spanien, aber ich wohne schon lange hier.",es:"De España, pero llevo ya mucho aquí.",mas:[{de:"Aus welchem Land kommst du?",es:"¿De qué país eres?"},{de:"Aus Spanien, aus der Nähe von Madrid.",es:"De España, de cerca de Madrid."},{de:"In welchem Bezirk wohnst du?",es:"¿En qué distrito vives?"},{de:"Im zehnten Bezirk, gleich beim Hauptbahnhof. Die Verbindung ist perfekt.",es:"En el distrito diez, al lado de la estación central. La conexión es perfecta."},{de:"Wohnst du allein oder mit anderen zusammen?",es:"¿Vives solo o con más gente?"},{de:"Ich teile eine Wohnung mit zwei Studenten, das ist deutlich billiger.",es:"Comparto piso con dos estudiantes; sale bastante más barato."}]},"Du bist sicher Maria, oder?":{de:"Ja, genau. Und du bist …?",es:"Sí, exacto. ¿Y tú eres…?",mas:[{de:"Kommst du aus Italien?",es:"¿Vienes de Italia?"},{de:"Nein, aus Spanien. Aus Valencia.",es:"No, de España. De Valencia."},{de:"Du sprichst Spanisch, oder?",es:"Hablas español, ¿verdad?"},{de:"Ja, das ist meine Muttersprache. Hörst du das am Akzent?",es:"Sí, es mi lengua materna. ¿Se me nota en el acento?"},{de:"Du bist sicher nicht von hier.",es:"Seguro que no eres de aquí."},{de:"Stimmt, ich bin erst im März gekommen. Wie hast du das gemerkt?",es:"Es verdad, llegué en marzo. ¿Cómo te has dado cuenta?"}]},"Ja, genau. · Richtig. · Stimmt.":{de:"Gut, dann ist ja alles klar.",es:"Bien, entonces todo claro.",mas:[{de:"Das sehe ich genauso.",es:"Yo lo veo igual."},{de:"Gut. Ich dachte schon, ich bin der Einzige mit dieser Meinung.",es:"Bien. Ya pensaba que era el único que opinaba así."},{de:"Ja, das stimmt wirklich.",es:"Sí, eso es verdad."},{de:"Nicht wahr? Am Anfang habe ich das auch nicht geglaubt.",es:"¿Verdad que sí? Al principio yo tampoco me lo creía."},{de:"Genau das wollte ich auch sagen.",es:"Justo eso quería decir yo."},{de:"Dann sind wir uns ja einig, machen wir es einfach so.",es:"Pues entonces estamos de acuerdo; hagámoslo así."}]},"Welche Sprachen sprichst du?":{de:"Spanisch, Englisch und ein bisschen Deutsch. Französisch verstehe ich nur.",es:"Español, inglés y un poco de alemán. El francés solo lo entiendo.",mas:[{de:"Was ist deine Muttersprache?",es:"¿Cuál es tu lengua materna?"},{de:"Spanisch, und ein bisschen Katalanisch.",es:"El español, y un poco de catalán."},{de:"Welche Sprache fällt dir am leichtesten?",es:"¿Qué idioma te resulta más fácil?"},{de:"Englisch, ganz klar. Deutsch kostet mich immer noch Kraft.",es:"El inglés, sin duda. El alemán todavía me cuesta esfuerzo."},{de:"Wie lange lernst du schon Deutsch?",es:"¿Cuánto tiempo llevas aprendiendo alemán?"},{de:"Seit einem Jahr. Ich gehe zweimal pro Woche in den Kurs.",es:"Desde hace un año. Voy dos veces por semana a clase."}]},"Auf Wiedersehen und einen schönen Tag noch!":{de:"Danke, gleichfalls. Bis morgen um neun im Büro.",es:"Gracias, igualmente. Hasta mañana a las nueve en la oficina.",mas:[{de:"Es war schön, Sie kennenzulernen.",es:"Ha sido un placer conocerle."},{de:"Ganz meinerseits. Hier ist meine Karte, schreiben Sie mir einfach.",es:"Igualmente. Aquí tiene mi tarjeta, escríbame sin problema."},{de:"Wir sehen uns nächste Woche!",es:"¡Nos vemos la semana que viene!"},{de:"Bestimmt. Schreib mir, falls sich etwas ändert.",es:"Seguro. Escríbeme si cambia algo."},{de:"Wir sehen uns am Donnerstag, ja?",es:"Nos vemos el jueves, ¿vale?"},{de:"Ja, gleiche Zeit, gleicher Ort, ich schreibe dir vorher kurz.",es:"Sí, misma hora y mismo sitio; te escribo antes."}]},"Darf ich fragen, wie alt Sie sind?":{de:"Natürlich, ich bin 48.",es:"Por supuesto, tengo 48.",mas:[{de:"In welchem Jahr sind Sie geboren?",es:"¿En qué año nació?"},{de:"1977, im November.",es:"En 1977, en noviembre."},{de:"Wie alt ist Ihre Tochter?",es:"¿Cuántos años tiene su hija?"},{de:"Sie wird im Mai zwölf. Sie geht schon ins Gymnasium.",es:"En mayo cumple doce. Ya va al instituto."},{de:"Wie alt ist Ihr jüngstes Kind?",es:"¿Cuántos años tiene su hijo menor?"},{de:"Der Kleine ist drei. Mit ihm ist es gerade am anstrengendsten.",es:"El pequeño tiene tres. Con él es ahora lo más agotador."}]},"Sind Sie ledig oder verheiratet?":{de:"Ledig. Ich wohne allein, das passt mir gut.",es:"Soltero. Vivo solo y me va bien así.",mas:[{de:"Haben Sie Kinder?",es:"¿Tiene hijos?"},{de:"Nein, keine. Dafür sehr viele Patenkinder.",es:"No, ninguno. En cambio, muchos ahijados."},{de:"Haben Sie Geschwister?",es:"¿Tiene hermanos?"},{de:"Zwei Schwestern, beide in Linz. Wir telefonieren jeden Sonntag.",es:"Dos hermanas, las dos en Linz. Hablamos por teléfono todos los domingos."},{de:"Mein Familienstand ist ledig.",es:"Mi estado civil es soltero."},{de:"Gut, dann kreuzen wir hier einfach „ledig“ an.",es:"Bien, entonces marcamos aquí «soltero»."}]},"Woher kommen Sie?":{de:"Aus Bosnien, aus Tuzla.",es:"De Bosnia, de Tuzla.",mas:[{de:"Wo sind Sie geboren?",es:"¿Dónde nació?"},{de:"In Tuzla, im Krankenhaus gleich neben unserem Haus.",es:"En Tuzla, en el hospital justo al lado de nuestra casa."},{de:"Wie lange leben Sie schon in Österreich?",es:"¿Cuánto tiempo lleva viviendo en Austria?"},{de:"Seit 2014, also über zehn Jahre.",es:"Desde 2014, o sea más de diez años."},{de:"Seit wann wohnen Sie in dieser Wohnung?",es:"¿Desde cuándo vive en este piso?"},{de:"Seit drei Jahren. Vorher war ich im neunzehnten Bezirk.",es:"Desde hace tres años. Antes estaba en el distrito diecinueve."}]},"Wie ist Ihre Adresse?":{de:"Hauptstraße 12, in Wien.",es:"Hauptstraße 12, en Viena.",mas:[{de:"Wie ist Ihre Postleitzahl?",es:"¿Qué código postal tiene?"},{de:"1010, ich wohne mitten in der Stadt.",es:"1010, vivo en el centro."},{de:"Wie lautet Ihre Adresse bitte?",es:"¿Cuál es su dirección, por favor?"},{de:"Ich schreibe sie Ihnen auf, der Straßenname ist lang.",es:"Se la escribo, el nombre de la calle es largo."},{de:"Ist das noch Ihre aktuelle Adresse?",es:"¿Sigue siendo esta su dirección actual?"},{de:"Nein, die ist von der alten Wohnung. Ich gebe Ihnen die neue.",es:"No, esa es del piso viejo. Le doy la nueva."}]},"Ich spreche ein bisschen Deutsch.":{de:"Das hört man, Sie sprechen schon ganz ordentlich.",es:"Se nota, ya habla bastante bien.",mas:[{de:"Mein Deutsch ist noch nicht so gut.",es:"Mi alemán todavía no es tan bueno."},{de:"Für ein Jahr Kurs ist das sehr gut. Machen Sie einfach weiter.",es:"Para un año de clase está muy bien. Siga así."},{de:"Ich lerne Deutsch, aber ich mache noch viele Fehler.",es:"Estoy aprendiendo alemán, pero todavía cometo muchos errores."},{de:"Fehler machen alle. Wichtig ist, dass man Sie versteht.",es:"Errores comete todo el mundo. Lo importante es que se le entienda."},{de:"Sprechen Sie langsamer, bitte, ich lerne noch.",es:"Hable más despacio, por favor, todavía estoy aprendiendo."},{de:"Entschuldigung, ich rede immer zu schnell. Besser so?",es:"Perdone, siempre hablo muy rápido. ¿Mejor así?"}]},"Wie bitte?":{de:"Ich sagte, das Formular müssen Sie unten unterschreiben.",es:"He dicho que el formulario tiene que firmarlo abajo.",mas:[{de:"Können Sie das bitte wiederholen?",es:"¿Puede repetirlo, por favor?"},{de:"Gern: unten rechts, neben dem Datum.",es:"Con gusto: abajo a la derecha, junto a la fecha."},{de:"Entschuldigung, das habe ich nicht verstanden.",es:"Perdone, eso no lo he entendido."},{de:"Ich zeige es Ihnen einfach mit dem Finger.",es:"Se lo señalo con el dedo y listo."},{de:"Können Sie das bitte aufschreiben?",es:"¿Puede escribírmelo, por favor?"},{de:"Natürlich, ich schreibe es Ihnen auf den Zettel.",es:"Por supuesto, se lo escribo en el papel."}]},"Bitte füllen Sie dieses Formular aus.":{de:"Mache ich. Brauche ich dafür einen blauen Stift?",es:"Lo hago. ¿Necesito un bolígrafo azul?",mas:[{de:"Diese Angabe verstehe ich nicht.",es:"Este dato no lo entiendo."},{de:"Da kommt der Name Ihres Arbeitgebers hin.",es:"Ahí va el nombre de su empleador."},{de:"Was soll ich bei Geschlecht ankreuzen?",es:"¿Qué marco en la casilla de sexo?"},{de:"Männlich, weiblich oder divers, wie Sie möchten.",es:"Masculino, femenino u otro, como quiera."},{de:"Wo trage ich die Telefonnummer ein?",es:"¿Dónde pongo el número de teléfono?"},{de:"In das letzte Feld, unter der E-Mail-Adresse.",es:"En el último campo, debajo del correo."}]},"Haben Sie einen Ausweis dabei?":{de:"Ja, meinen Pass. Der Meldezettel fehlt mir noch.",es:"Sí, el pasaporte. Me falta el certificado de empadronamiento.",mas:[{de:"Darf ich nach Ihrem Geburtsdatum fragen?",es:"¿Puedo preguntarle su fecha de nacimiento?"},{de:"Der 14. März 1993.",es:"El 14 de marzo de 1993."},{de:"Was ist Ihre Staatsangehörigkeit?",es:"¿Cuál es su nacionalidad?"},{de:"Spanisch. Ich bin EU-Bürger, das macht es einfacher.",es:"Española. Soy ciudadano de la UE, eso lo facilita."},{de:"Wie ist Ihr Familienname?",es:"¿Cuál es su nombre de familia?"},{de:"Romero, R-O-M-E-R-O. Den verschreiben fast alle.",es:"Romero, R-O-M-E-R-O. Casi todos lo escriben mal."}]},"Wo ist der Kuli? – Hier. / Da drüben.":{de:"Nimm den, ich habe noch drei in der Schublade.",es:"Coge ese, tengo tres más en el cajón.",mas:[{de:"Gibt es hier irgendwo einen Kugelschreiber?",es:"¿Hay por aquí un bolígrafo?"},{de:"Im Becher neben dem Drucker liegen immer welche.",es:"En el vaso al lado de la impresora siempre hay."},{de:"Weißt du, wo die Schere geblieben ist?",es:"¿Sabes dónde ha ido a parar la tijera?"},{de:"Die hat Tom mitgenommen, glaube ich. Frag ihn mal.",es:"Se la llevó Tom, creo. Pregúntale."},{de:"Weißt du, wo mein Ladekabel ist?",es:"¿Sabes dónde está mi cable de carga?"},{de:"Das steckt noch in der Dose unter dem Tisch.",es:"Sigue enchufado debajo de la mesa."}]},"Entschuldigung, wo finde ich Zimmer zwölf?":{de:"Zweiter Stock, dann links bis zum Ende vom Gang.",es:"Segunda planta, luego a la izquierda hasta el final del pasillo.",mas:[{de:"Wo finde ich das Büro?",es:"¿Dónde está la oficina?"},{de:"Gleich hier vorne, die erste Tür nach dem Aufzug.",es:"Aquí delante, la primera puerta después del ascensor."},{de:"Ist die Kantine im Erdgeschoss?",es:"¿El comedor está en la planta baja?"},{de:"Ja, hinter dem Empfang. Ab halb zwölf ist offen.",es:"Sí, detrás de recepción. Abre a las once y media."},{de:"Wo finde ich hier den Eingang zum Lager?",es:"¿Dónde está aquí la entrada al almacén?"},{de:"Außen herum, beim grauen Tor. Von innen geht es nicht.",es:"Por fuera, en el portón gris. Por dentro no se puede."}]},"Was sind Sie von Beruf? – Ich bin Ärztin.":{de:"Interessant. In welchem Bereich genau?",es:"Interesante. ¿En qué especialidad exactamente?",mas:[{de:"Wo arbeiten Sie?",es:"¿Dónde trabaja?"},{de:"Im Krankenhaus Nord, in der Notaufnahme.",es:"En el hospital Nord, en urgencias."},{de:"Bei welcher Firma arbeiten Sie?",es:"¿En qué empresa trabaja?"},{de:"Bei einer kleinen Baufirma, wir sind nur zwölf Leute.",es:"En una constructora pequeña, solo somos doce."},{de:"Welchen Beruf hast du gelernt?",es:"¿Qué profesión estudiaste?"},{de:"Elektriker. Gearbeitet habe ich dann aber im Lager.",es:"Electricista. Pero después trabajé en el almacén."}]},"Ich suche gerade Arbeit.":{de:"In welchem Bereich? Vielleicht kenne ich jemanden.",es:"¿En qué sector? A lo mejor conozco a alguien.",mas:[{de:"Ich bin zurzeit arbeitslos.",es:"Ahora mismo estoy en paro."},{de:"Das ist hart, aber es dauert selten lange. Hast du schon Bewerbungen draußen?",es:"Es duro, pero suele durar poco. ¿Has enviado ya solicitudes?"},{de:"Ich mache eine Ausbildung.",es:"Estoy haciendo una formación."},{de:"Gut, damit hast du danach viel mehr Möglichkeiten.",es:"Bien, con eso después tendrás muchas más opciones."},{de:"Machst du gerade ein Praktikum?",es:"¿Estás haciendo prácticas ahora?"},{de:"Ja, drei Monate im Büro. Bezahlt wird es leider kaum.",es:"Sí, tres meses en la oficina. Por desgracia casi no pagan."}]},"Wie viele Stunden arbeitest du pro Woche?":{de:"Achtunddreißig und ein halbes, plus die Überstunden.",es:"Treinta y ocho y media, más las horas extra.",mas:[{de:"Arbeitest du in Vollzeit oder Teilzeit?",es:"¿Trabajas a jornada completa o parcial?"},{de:"Vollzeit, aber ab Herbst gehe ich auf dreißig Stunden.",es:"Jornada completa, pero en otoño paso a treinta horas."},{de:"Wie lange brauchst du in die Arbeit?",es:"¿Cuánto tardas en llegar al trabajo?"},{de:"Vierzig Minuten mit der U-Bahn, mit dem Rad zwanzig.",es:"Cuarenta minutos en metro, veinte en bici."},{de:"Wie viele Mitarbeiter hat der Betrieb?",es:"¿Cuántos empleados tiene la empresa?"},{de:"Etwa sechzig, aber in meiner Abteilung sind wir vier.",es:"Unos sesenta, pero en mi departamento somos cuatro."}]},"Wann fängst du morgens an?":{de:"Um sieben. Dafür bin ich um vier wieder draußen.",es:"A las siete. En cambio a las cuatro ya estoy fuera.",mas:[{de:"Ich arbeite von Montag bis Donnerstag.",es:"Trabajo de lunes a jueves."},{de:"Vier Tage? Das würde ich auch nehmen.",es:"¿Cuatro días? Yo también lo cogería."},{de:"Wie lange dauert deine Mittagspause?",es:"¿Cuánto dura tu pausa para comer?"},{de:"Eine halbe Stunde. Meistens esse ich am Schreibtisch.",es:"Media hora. Casi siempre como en la mesa."},{de:"Machst du oft Überstunden?",es:"¿Haces horas extra a menudo?"},{de:"Am Monatsende schon. Sonst geht es.",es:"A fin de mes sí. El resto se lleva bien."}]},"Kannst du mir kurz helfen?":{de:"Klar, was brauchst du?",es:"Claro, ¿qué necesitas?",mas:[{de:"Der Drucker funktioniert nicht.",es:"La impresora no funciona."},{de:"Der hat wieder keinen Toner. Ich hole einen neuen.",es:"Otra vez sin tóner. Voy a por uno nuevo."},{de:"Der Computer ist schon wieder langsam.",es:"El ordenador va otra vez lento."},{de:"Einmal ausschalten und wieder an, das hilft meistens.",es:"Apágalo y vuelve a encenderlo, eso suele funcionar."},{de:"Kannst du mir die Datei schicken?",es:"¿Me puedes mandar el archivo?"},{de:"Ist unterwegs. Schau in den Spam, falls sie nicht kommt.",es:"Va de camino. Mira en spam si no llega."}]},"Ja, stimmt. · Genau.":{de:"Gut, dann sind wir uns einig.",es:"Bien, entonces estamos de acuerdo.",mas:[{de:"Das stimmt allerdings.",es:"En eso sí que tienes razón."},{de:"Siehst du? Manchmal habe ich auch recht.",es:"¿Ves? A veces yo también tengo razón."},{de:"Stimmt, so habe ich das noch nicht gesehen.",es:"Es verdad, así no lo había visto."},{de:"Deshalb reden wir darüber. Zwei sehen mehr als einer.",es:"Por eso lo hablamos. Dos ven más que uno."},{de:"Genau so ist es, du hast es erfasst.",es:"Exactamente así es, lo has captado."},{de:"Dann machen wir es so und schließen das Thema ab.",es:"Entonces lo hacemos así y cerramos el tema."}]},"Hast du Geschwister? – Ja, zwei Brüder.":{de:"Zwei Brüder, schön. Ältere oder jüngere?",es:"Dos hermanos, qué bien. ¿Mayores o menores?",mas:[{de:"Wie viele Geschwister hast du?",es:"¿Cuántos hermanos tienes?"},{de:"Vier, ich bin die Mittlere. Es war immer laut bei uns.",es:"Cuatro, yo soy la del medio. En casa siempre había ruido."},{de:"Wie alt ist dein Bruder?",es:"¿Cuántos años tiene tu hermano?"},{de:"Der Ältere ist 34, der Jüngere gerade 19 geworden.",es:"El mayor tiene 34, el pequeño acaba de cumplir 19."},{de:"Wie viele Personen seid ihr zu Hause?",es:"¿Cuántos sois en casa?"},{de:"Sechs, mit der Oma sieben. Der Tisch ist immer voll.",es:"Seis, con la abuela siete. La mesa siempre está llena."}]},"Meine Eltern wohnen in Polen.":{de:"Und vermisst du sie sehr?",es:"¿Y los echas mucho de menos?",mas:[{de:"Wie oft telefonierst du mit deinen Eltern?",es:"¿Cada cuánto hablas por teléfono con tus padres?"},{de:"Jeden Sonntag um sechs. Das ist heilig bei uns.",es:"Todos los domingos a las seis. Eso es sagrado en casa."},{de:"Wo bist du aufgewachsen?",es:"¿Dónde te criaste?"},{de:"In einem Dorf bei Krakau, mit sehr viel Platz zum Spielen.",es:"En un pueblo cerca de Cracovia, con mucho sitio para jugar."},{de:"Meine Eltern sind seit letztem Jahr geschieden.",es:"Mis padres están divorciados desde el año pasado."},{de:"Das war sicher nicht leicht. Wie geht es dir damit?",es:"Seguro que no fue fácil. ¿Cómo lo llevas?"}]},"Darf ich vorstellen? Mein Mann.":{de:"Sehr angenehm. Ich habe schon viel von Ihnen gehört.",es:"Mucho gusto. Ya he oído hablar mucho de usted.",mas:[{de:"Darf ich Ihnen meine Frau vorstellen?",es:"¿Le presento a mi mujer?"},{de:"Gern. Guten Abend, freut mich sehr.",es:"Con gusto. Buenas noches, encantado."},{de:"Ich möchte Ihnen meinen Sohn vorstellen.",es:"Me gustaría presentarle a mi hijo."},{de:"Guten Tag, junger Mann. Gehst du schon zur Schule?",es:"Buenas tardes, jovencito. ¿Ya vas al colegio?"},{de:"Das sind meine Schwiegereltern aus Ungarn.",es:"Estos son mis suegros, de Hungría."},{de:"Willkommen in Wien! Bleiben Sie länger?",es:"¡Bienvenidos a Viena! ¿Se quedan mucho?"}]},"Ist das deine Schwester?":{de:"Ja, die Große. Sie ist zwei Jahre älter.",es:"Sí, la mayor. Es dos años más grande.",mas:[{de:"Das ist bestimmt deine Mutter auf dem Foto.",es:"Esa seguro que es tu madre en la foto."},{de:"Genau, mit 25. Alle sagen, ich sehe ihr ähnlich.",es:"Exacto, con 25 años. Todos dicen que me parezco a ella."},{de:"Das ist sicher dein Opa.",es:"Ese seguro que es tu abuelo."},{de:"Ja, mit seinem alten Fahrrad. Das hat er noch.",es:"Sí, con su bici vieja. Todavía la tiene."},{de:"Das ist sicher deine Urgroßmutter auf dem Bild.",es:"Esa seguro que es tu bisabuela en la foto."},{de:"Richtig. Das Foto ist von 1938, aus Ungarn.",es:"Correcto. La foto es de 1938, de Hungría."}]},"Was ist das? – Das ist ein Foto.":{de:"Darf ich es mir kurz ansehen?",es:"¿Puedo verla un momento?",mas:[{de:"Wer ist das?",es:"¿Quién es ese/a?"},{de:"Meine Tante Julia, die Schwester von meiner Mutter.",es:"Mi tía Julia, la hermana de mi madre."},{de:"Wer ist die Frau auf dem Bild?",es:"¿Quién es la mujer del cuadro?"},{de:"Meine Großmutter, an ihrem Hochzeitstag.",es:"Mi abuela, el día de su boda."},{de:"Wem gehört dieses Foto?",es:"¿De quién es esta foto?"},{de:"Meiner Mutter. Sie will es unbedingt zurück.",es:"De mi madre. Lo quiere de vuelta a toda costa."}]},"Möchtest du ein paar Fotos sehen?":{de:"Gern! Sind die von der Familienfeier?",es:"¡Con gusto! ¿Son de la fiesta familiar?",mas:[{de:"Auf diesem Bild ist die ganze Familie.",es:"En esta foto está toda la familia."},{de:"Wie viele seid ihr? Ich zähle fünfzehn Leute.",es:"¿Cuántos sois? Cuento quince personas."},{de:"Sind das drei Generationen auf einem Bild?",es:"¿Son tres generaciones en una foto?"},{de:"Sogar vier, mit meiner Oma ganz hinten.",es:"Incluso cuatro, con mi abuela al fondo."},{de:"Wer steht ganz links auf dem Bild?",es:"¿Quién está a la izquierda del todo en la foto?"},{de:"Mein Cousin Marco. Er kommt immer zu spät und steht am Rand.",es:"Mi primo Marco. Siempre llega tarde y se queda al borde."}]},"Wer macht bei euch den Haushalt?":{de:"Wir teilen es auf, aber ich putze mehr. Das ist die Wahrheit.",es:"Lo repartimos, pero yo limpio más. Esa es la verdad.",mas:[{de:"Meine Kinder helfen kaum im Haushalt.",es:"Mis hijos casi no ayudan en casa."},{de:"Wie alt sind sie? Mit zwölf kann man schon abwaschen.",es:"¿Qué edad tienen? Con doce ya se puede lavar los platos."},{de:"Wir essen abends immer zusammen.",es:"Por la noche siempre cenamos juntos."},{de:"Das finde ich gut. Bei uns isst jeder, wann er kann.",es:"Eso me parece bueno. En casa cada uno come cuando puede."},{de:"Ich kümmere mich um meine Oma.",es:"Me ocupo de mi abuela."},{de:"Das ist viel Arbeit. Hilft dir jemand dabei?",es:"Eso es mucho trabajo. ¿Te ayuda alguien?"}]},"Wer putzt bei euch die Küche?":{de:"Wir wechseln jede Woche. Auf dem Kühlschrank hängt ein Plan.",es:"Nos turnamos cada semana. En la nevera hay un plan.",mas:[{de:"Kocht bei euch jeder für sich?",es:"¿En vuestra casa cocina cada uno para sí?"},{de:"Unter der Woche ja, am Sonntag kocht einer für alle.",es:"Entre semana sí; el domingo uno cocina para todos."},{de:"Gibt es bei euch feste Regeln zu Hause?",es:"¿En vuestra casa hay normas fijas?"},{de:"Nur eine: wer kocht, wäscht nicht ab.",es:"Solo una: quien cocina no lava los platos."},{de:"Wie ist das Zusammenwohnen mit deinem Bruder?",es:"¿Qué tal convivir con tu hermano?"},{de:"Besser als erwartet. Er ist ordentlicher als ich.",es:"Mejor de lo esperado. Es más ordenado que yo."}]},"Wie spät ist es eigentlich?":{de:"Gleich halb neun. Wir müssen los.",es:"Casi las ocho y media. Tenemos que irnos.",mas:[{de:"Um wie viel Uhr fängt der Film an?",es:"¿A qué hora empieza la película?"},{de:"Um neun, aber die Werbung läuft zwanzig Minuten.",es:"A las nueve, pero los anuncios duran veinte minutos."},{de:"Um wie viel Uhr treffen wir uns?",es:"¿A qué hora quedamos?"},{de:"Sagen wir Viertel vor neun vor dem Kino.",es:"Digamos a las nueve menos cuarto delante del cine."},{de:"Bist du immer so pünktlich?",es:"¿Siempre eres tan puntual?"},{de:"Immer. Zu spät kommen macht mich nervös.",es:"Siempre. Llegar tarde me pone nervioso."}]},"Ich schaffe das nicht bis Freitag.":{de:"Wie viel fehlt denn noch?",es:"¿Cuánto te falta?",mas:[{de:"Schaffst du das bis morgen Mittag?",es:"¿Te da tiempo para mañana al mediodía?"},{de:"Wenn mich niemand stört, ja.",es:"Si nadie me molesta, sí."},{de:"Das ist dringend, kannst du es heute machen?",es:"Es urgente, ¿lo puedes hacer hoy?"},{de:"Heute nur die Hälfte. Den Rest gleich morgen früh.",es:"Hoy solo la mitad. El resto mañana a primera hora."},{de:"Haben wir bis dahin noch genug Zeit?",es:"¿Nos queda tiempo suficiente hasta entonces?"},{de:"Knapp, aber es geht. Wir müssen nur heute anfangen.",es:"Justo, pero se puede. Solo hay que empezar hoy."}]},"Kannst du mir bitte helfen?":{de:"Natürlich, sag einfach, was ich tun soll.",es:"Claro, dime qué tengo que hacer.",mas:[{de:"Hilfst du mir kurz beim Tragen?",es:"¿Me ayudas un momento a llevar esto?"},{de:"Klar, nimm du die leichte Kiste.",es:"Claro, coge tú la caja ligera."},{de:"Einen Moment, bitte.",es:"Un momento, por favor."},{de:"Lass dir Zeit, ich warte hier.",es:"Tómate tu tiempo, yo espero aquí."},{de:"Darf ich dich um einen Gefallen bitten?",es:"¿Te puedo pedir un favor?"},{de:"Immer. Was brauchst du?",es:"Siempre. ¿Qué necesitas?"}]},"Darf ich dich um deinen Rat bitten?":{de:"Natürlich. Setz dich, erzähl mal.",es:"Por supuesto. Siéntate, cuéntame.",mas:[{de:"Würdest du das bitte für mich erledigen?",es:"¿Me lo harías tú, por favor?"},{de:"Mache ich, aber erst nach der Mittagspause.",es:"Lo hago, pero después de comer."},{de:"Kannst du mir nächste Woche noch einmal helfen?",es:"¿Me puedes ayudar otra vez la semana que viene?"},{de:"Gern, sag mir nur vorher, welcher Tag.",es:"Con gusto, solo dime antes qué día."},{de:"Darf ich mir kurz deinen Kuli ausleihen?",es:"¿Me dejas un momento el boli?"},{de:"Nimm ihn, aber gib ihn mir wieder zurück.",es:"Cógelo, pero devuélvemelo."}]},"Wann hat die Bank offen? – Von 9 bis 15 Uhr.":{de:"Dann muss ich in der Mittagspause hin.",es:"Entonces tengo que ir en la pausa de comer.",mas:[{de:"Haben Sie über Mittag geschlossen?",es:"¿Cierran al mediodía?"},{de:"Von zwölf bis eins, ja. Danach sind wir wieder da.",es:"De doce a una, sí. Después volvemos a estar."},{de:"Wann macht der Supermarkt zu?",es:"¿A qué hora cierra el supermercado?"},{de:"Um acht, am Samstag schon um sechs.",es:"A las ocho; el sábado ya a las seis."},{de:"Am Sonntag ist geschlossen.",es:"Los domingos está cerrado."},{de:"Deshalb kaufe ich am Samstag für zwei Tage ein.",es:"Por eso el sábado compro para dos días."}]},"Wie sind die Öffnungszeiten am Werktag?":{de:"Von sieben bis neunzehn Uhr, durchgehend.",es:"De siete a diecinueve, sin interrupción.",mas:[{de:"Ab wann kann ich morgen kommen?",es:"¿A partir de qué hora puedo venir mañana?"},{de:"Ab halb acht ist jemand da.",es:"A partir de las siete y media hay alguien."},{de:"Kann ich auch später noch kommen?",es:"¿Puedo venir también más tarde?"},{de:"Bis achtzehn Uhr problemlos, danach ist zu.",es:"Hasta las dieciocho sin problema; después está cerrado."},{de:"Wann macht das Amt am Montag auf?",es:"¿Cuándo abre la oficina el lunes?"},{de:"Um acht, aber kommen Sie früh, montags ist immer viel los.",es:"A las ocho, pero venga pronto; los lunes hay mucha gente."}]},"Hast du am Freitag Zeit?":{de:"Freitag ja, ab sechs bin ich frei.",es:"El viernes sí, a partir de las seis estoy libre.",mas:[{de:"Passt dir 18 Uhr? – Ja, das passt.",es:"¿Te va bien a las 18? – Sí, me va bien."},{de:"Gut, dann steht es. Ich freue mich.",es:"Bien, entonces queda fijado. Me alegro."},{de:"Wo treffen wir uns?",es:"¿Dónde quedamos?"},{de:"Am besten beim Brunnen, den findet jeder.",es:"Mejor en la fuente, esa la encuentra cualquiera."},{de:"Kommst du allein oder mit Ana?",es:"¿Vienes solo o con Ana?"},{de:"Mit Ana, sie will dich sowieso kennenlernen.",es:"Con Ana, quiere conocerte de todas formas."}]},"Ich muss leider absagen.":{de:"Schade. Ist etwas passiert?",es:"Qué pena. ¿Ha pasado algo?",mas:[{de:"Ich muss unseren Termin leider verschieben.",es:"Lamentablemente tengo que cambiar nuestra cita."},{de:"Kein Problem. Wann würde es dir passen?",es:"No pasa nada. ¿Cuándo te vendría bien?"},{de:"Können wir das auf nächste Woche legen?",es:"¿Podemos pasarlo a la semana que viene?"},{de:"Ja, Dienstag oder Mittwoch hätte ich Zeit.",es:"Sí, el martes o el miércoles tendría tiempo."},{de:"Bleibt es bei Freitag um sieben?",es:"¿Seguimos con el viernes a las siete?"},{de:"Es bleibt dabei. Ich habe es mir schon eingetragen.",es:"Seguimos. Ya lo tengo apuntado."}]},"Wir möchten gern bestellen.":{de:"Sehr gern. Was darf ich Ihnen bringen?",es:"Con mucho gusto. ¿Qué les traigo?",mas:[{de:"Ich hätte gern eine Suppe.",es:"Quisiera una sopa."},{de:"Die Rindsuppe oder die Gemüsesuppe?",es:"¿La sopa de carne o la de verduras?"},{de:"Ich hätte gern ein Schnitzel.",es:"Quería un escalope."},{de:"Mit Kartoffelsalat oder mit Pommes?",es:"¿Con ensalada de patata o con patatas fritas?"},{de:"Für mich bitte nur ein Wasser.",es:"Para mí solo un agua."},{de:"Mit Kohlensäure oder ohne?",es:"¿Con gas o sin gas?"}]},"Könnte ich bitte die Karte haben?":{de:"Hier bitte. Nehmen Sie sich Zeit.",es:"Aquí tiene. Tómese su tiempo.",mas:[{de:"Was ist die Spezialität des Hauses?",es:"¿Cuál es la especialidad de la casa?"},{de:"Der Tafelspitz. Den machen wir seit vierzig Jahren gleich.",es:"El tafelspitz. Lo hacemos igual desde hace cuarenta años."},{de:"Was ist heute im Angebot?",es:"¿Qué hay hoy de oferta?"},{de:"Das Mittagsmenü mit Suppe und Hauptgang, elf Euro.",es:"El menú del mediodía con sopa y plato principal, once euros."},{de:"Haben Sie auch vegetarische Gerichte?",es:"¿Tienen también platos vegetarianos?"},{de:"Drei, sie sind auf der Karte mit einem Blatt markiert.",es:"Tres, están marcados en la carta con una hoja."}]},"Was kostet das?":{de:"Drei Euro achtzig das Stück.",es:"Tres euros ochenta la unidad.",mas:[{de:"Ist das der Preis für ein Stück?",es:"¿Es ese el precio por unidad?"},{de:"Ja, pro Stück. Ab fünf wird es billiger.",es:"Sí, por unidad. A partir de cinco sale más barato."},{de:"Was kostet das Kilo?",es:"¿Cuánto cuesta el kilo?"},{de:"Sieben Euro fünfzig. Heute ist es besonders gut.",es:"Siete euros cincuenta. Hoy está especialmente bueno."},{de:"Haben Sie etwas Günstigeres?",es:"¿Tiene algo más barato?"},{de:"Die von gestern, die kosten nur die Hälfte.",es:"Las de ayer, esas cuestan solo la mitad."}]},"Die Rechnung, bitte.":{de:"Sofort. Zusammen oder getrennt?",es:"Enseguida. ¿Junto o separado?",mas:[{de:"Die Rechnung, bitte. Wir zahlen getrennt.",es:"La cuenta, por favor. Pagamos por separado."},{de:"Kein Problem. Was hatten Sie beide?",es:"No pasa nada. ¿Qué tomaron cada uno?"},{de:"Wie viel macht das? – Das macht 8,50 Euro.",es:"¿Cuánto es? – Son 8,50 euros."},{de:"Danke. Neun Euro, stimmt so?",es:"Gracias. Nueve euros, ¿está bien así?"},{de:"Kann ich mit Karte zahlen?",es:"¿Puedo pagar con tarjeta?"},{de:"Ab zehn Euro gern. Darunter nur bar.",es:"A partir de diez euros sí. Por debajo solo en efectivo."}]},"Isst du gern Fisch?":{de:"Sehr gern, am liebsten gegrillt.",es:"Mucho, sobre todo a la plancha.",mas:[{de:"Ich mag keinen Fisch.",es:"No me gusta el pescado."},{de:"Überhaupt keinen? Auch keinen Lachs?",es:"¿Ninguno? ¿Tampoco salmón?"},{de:"Ich esse gern Gemüse.",es:"Me gusta comer verdura."},{de:"Dann koche ich morgen etwas mit viel Gemüse.",es:"Entonces mañana cocino algo con mucha verdura."},{de:"Was isst du am liebsten?",es:"¿Qué es lo que más te gusta comer?"},{de:"Alles, was meine Mutter macht. Das schmeckt anders.",es:"Todo lo que hace mi madre. Eso sabe distinto."}]},"Schmeckt es dir?":{de:"Sehr gut. Was ist da alles drin?",es:"Muy bueno. ¿Qué lleva?",mas:[{de:"Schmeckt dir die Suppe?",es:"¿Te gusta la sopa?"},{de:"Ja, aber sie ist ein bisschen salzig für mich.",es:"Sí, pero está un poco salada para mí."},{de:"Wie schmeckt dir die österreichische Küche?",es:"¿Qué te parece la cocina austriaca?"},{de:"Gut, nur die Portionen sind riesig.",es:"Bien, solo que las raciones son enormes."},{de:"Wie findest du das österreichische Frühstück?",es:"¿Qué te parece el desayuno austriaco?"},{de:"Perfekt. Semmel, Butter, Marmelade und ein großer Kaffee.",es:"Perfecto. Panecillo, mantequilla, mermelada y un café grande."}]},"Heute gibt es Suppe und Salat.":{de:"Nur das? Ich habe einen Riesenhunger.",es:"¿Solo eso? Tengo un hambre enorme.",mas:[{de:"Im Ofen ist noch ein Kuchen.",es:"En el horno hay todavía un pastel."},{de:"Dann warte ich gern. Wie lange noch?",es:"Entonces espero con gusto. ¿Cuánto falta?"},{de:"Zum Nachtisch gibt es frisches Obst.",es:"De postre hay fruta fresca."},{de:"Perfekt, nach der Suppe ist mir das genug.",es:"Perfecto, después de la sopa me basta."},{de:"Als Nachspeise gibt es Eis.",es:"De postre hay helado."},{de:"Dann nehme ich doch beides, Obst und Eis.",es:"Entonces cojo las dos cosas, fruta y helado."}]},"Wo finde ich hier den Reis?":{de:"Gang vier, beim Mehl und den Nudeln.",es:"Pasillo cuatro, con la harina y la pasta.",mas:[{de:"Wo finde ich die Dosen mit Tomaten?",es:"¿Dónde encuentro las latas de tomate?"},{de:"Im selben Gang, unten im Regal.",es:"En el mismo pasillo, abajo en la estantería."},{de:"Haben Sie auch tiefgekühltes Gemüse?",es:"¿Tienen también verdura congelada?"},{de:"Ganz hinten links, bei den Truhen.",es:"Al fondo a la izquierda, en los congeladores."},{de:"Bekomme ich hier auch frisches Brot?",es:"¿Aquí también hay pan fresco?"},{de:"Ja, gleich beim Eingang. Um vier kommt die zweite Lieferung.",es:"Sí, junto a la entrada. A las cuatro llega el segundo reparto."}]},"Wie ist das Wetter? – Es regnet.":{de:"Schon wieder. Diese Woche war noch kein Tag trocken.",es:"Otra vez. Esta semana no ha habido un día seco.",mas:[{de:"Wie ist das Wetter heute?",es:"¿Qué tiempo hace hoy?"},{de:"Grau, aber mild. Mantel brauchst du keinen.",es:"Gris, pero suave. No necesitas abrigo."},{de:"Regnet es draußen noch?",es:"¿Sigue lloviendo fuera?"},{de:"Gerade hat es aufgehört. Geh schnell, solange es hält.",es:"Acaba de parar. Vete rápido mientras aguante."},{de:"Wie viel Grad hat es draußen?",es:"¿Cuántos grados hace fuera?"},{de:"Elf. Für September ist das ziemlich frisch.",es:"Once. Para septiembre es bastante fresco."}]},"Heute ist es schön / schlecht.":{de:"Finde ich auch. Genau richtig für draußen.",es:"A mí también me lo parece. Justo para estar fuera.",mas:[{de:"Es sind 20 Grad.",es:"Hay 20 grados."},{de:"Angenehm. Nicht zu warm und nicht zu kalt.",es:"Agradable. Ni mucho calor ni mucho frío."},{de:"Heute ist es richtig warm.",es:"Hoy hace bastante calor."},{de:"Endlich. Ich hole die kurzen Hosen aus dem Schrank.",es:"Por fin. Saco los pantalones cortos del armario."},{de:"Es ist heute richtig schwül.",es:"Hoy hace mucho bochorno."},{de:"Da kommt sicher noch ein Gewitter.",es:"Seguro que viene tormenta."}]},"Hier ist es im Winter sehr kalt.":{de:"Bis minus fünfzehn manchmal. Daran gewöhnst du dich.",es:"Hasta menos quince a veces. Te acostumbras.",mas:[{de:"Hat es bei euch auch Frost gegeben?",es:"¿En vuestra zona también ha helado?"},{de:"Jede Nacht diese Woche. Die Blumen sind hin.",es:"Todas las noches esta semana. Las flores se han perdido."},{de:"Die Temperaturen sinken heute Nacht stark.",es:"Esta noche las temperaturas bajan mucho."},{de:"Dann hole ich die Pflanzen lieber rein.",es:"Entonces mejor meto las plantas."},{de:"Hat es bei euch auch geschneit?",es:"¿En vuestra zona también ha nevado?"},{de:"Zwanzig Zentimeter. Die Kinder haben frei bekommen.",es:"Veinte centímetros. Los niños han tenido fiesta."}]},"Nimm einen Regenschirm mit!":{de:"Muss das sein? Der Himmel ist doch blau.",es:"¿Hace falta? Si el cielo está azul.",mas:[{de:"Nimmst du den Regenschirm mit?",es:"¿Te llevas el paraguas?"},{de:"Ja, du hast ja doch immer recht damit.",es:"Sí, al final siempre tienes razón con eso."},{de:"Zieh dich warm an, es ist kühl.",es:"Abrígate, que hace fresco."},{de:"Ich nehme den dicken Pullover, versprochen.",es:"Cojo el jersey gordo, prometido."},{de:"Soll ich eine Jacke mitnehmen?",es:"¿Me llevo una chaqueta?"},{de:"Unbedingt, am Abend wird es deutlich kälter.",es:"Sin falta, por la noche refresca bastante."}]},"Mir ist kalt.":{de:"Soll ich dir eine Decke holen?",es:"¿Te traigo una manta?",mas:[{de:"Mir ist eiskalt.",es:"Tengo un frío helador."},{de:"Komm näher zur Heizung, hier ist es wärmer.",es:"Acércate al radiador, aquí está más caliente."},{de:"Mach bitte die Heizung an.",es:"Enciende la calefacción, por favor."},{de:"Steht schon auf drei. Wärmer wird sie nicht.",es:"Ya está en el tres. Más no calienta."},{de:"Wir sollten heute drinnen bleiben.",es:"Hoy deberíamos quedarnos dentro."},{de:"Einverstanden. Ich koche etwas Warmes.",es:"De acuerdo. Cocino algo caliente."}]},"Welche Jahreszeit magst du am liebsten?":{de:"Den Herbst. Die Farben und die Ruhe.",es:"El otoño. Los colores y la calma.",mas:[{de:"Der Herbst ist meine liebste Zeit zum Wandern.",es:"El otoño es mi época favorita para hacer senderismo."},{de:"Meine auch. Nicht zu heiß und kaum Leute.",es:"La mía también. Ni mucho calor ni mucha gente."},{de:"Im Winter wird es hier sehr früh dunkel.",es:"En invierno aquí oscurece muy pronto."},{de:"Um halb vier ist Schluss. Das finde ich hart.",es:"A las tres y media se acabó. Eso me cuesta."},{de:"Im Jänner ist es hier am kältesten.",es:"En enero es cuando más frío hace aquí."},{de:"Und der längste Monat, finde ich.",es:"Y el mes más largo, me parece."}]},"Ist der Winter hier sehr hart?":{de:"Härter als in Spanien, aber die Häuser sind warm.",es:"Más duro que en España, pero las casas son cálidas.",mas:[{de:"Welcher Monat ist im Durchschnitt am kältesten?",es:"¿Qué mes es de media el más frío?"},{de:"Der Jänner, knapp vor dem Februar.",es:"Enero, justo por delante de febrero."},{de:"Wann taut hier normalerweise der Schnee?",es:"¿Cuándo se derrite normalmente la nieve aquí?"},{de:"In der Stadt nach zwei Tagen, auf dem Berg erst im April.",es:"En la ciudad a los dos días; en la montaña, hasta abril."},{de:"Wann beginnt hier der Frühling?",es:"¿Cuándo empieza aquí la primavera?"},{de:"Offiziell im März, gefühlt erst Ende April.",es:"Oficialmente en marzo; de sensación, a finales de abril."}]},"Was machen wir, wenn es regnet?":{de:"Dann gehen wir ins Museum, das ist auch schön.",es:"Entonces vamos al museo, también está bien.",mas:[{de:"Bei Regen fällt der Ausflug aus.",es:"Si llueve, se cancela la excursión."},{de:"Schade. Entscheiden wir das morgen früh?",es:"Qué pena. ¿Lo decidimos mañana por la mañana?"},{de:"Wir verschieben das Picknick auf Sonntag.",es:"Pasamos el picnic al domingo."},{de:"Gute Idee, Sonntag soll es trocken bleiben.",es:"Buena idea, el domingo dicen que no llueve."},{de:"Das Grillfest ist nur bei schönem Wetter.",es:"La barbacoa es solo si hace buen tiempo."},{de:"Dann drücken wir die Daumen bis Samstag.",es:"Entonces cruzamos los dedos hasta el sábado."}]},"Wie oft machst du Sport?":{de:"Drei- bis viermal die Woche, je nach Schicht.",es:"Tres o cuatro veces por semana, según el turno.",mas:[{de:"Ich gehe zweimal pro Woche ins Fitnessstudio.",es:"Voy al gimnasio dos veces por semana."},{de:"Immer an denselben Tagen oder wie es passt?",es:"¿Siempre los mismos días o según venga?"},{de:"Ich trainiere immer vor der Arbeit.",es:"Entreno siempre antes del trabajo."},{de:"Um sechs Uhr früh? Das könnte ich nie.",es:"¿A las seis de la mañana? Yo no podría."},{de:"immer – oft – manchmal – selten – nie",es:"siempre – a menudo – a veces – rara vez – nunca"},{de:"Bei mir ist es leider meistens „selten“.",es:"En mi caso por desgracia casi siempre es «rara vez»."}]},"Treibst du regelmäßig Sport?":{de:"Ich versuche es. Im Winter klappt es besser.",es:"Lo intento. En invierno funciona mejor.",mas:[{de:"Gehst du ins Fitnessstudio?",es:"¿Vas al gimnasio?"},{de:"Nein, ich laufe lieber draußen. Das kostet auch nichts.",es:"No, prefiero correr fuera. Además no cuesta nada."},{de:"Fährst du jeden Tag mit dem Rad?",es:"¿Vas en bici todos los días?"},{de:"Bei jedem Wetter außer Schnee.",es:"Con cualquier tiempo menos con nieve."},{de:"Wie oft kochst du selbst?",es:"¿Cada cuánto cocinas tú?"},{de:"Unter der Woche immer. Am Wochenende gehen wir aus.",es:"Entre semana siempre. El fin de semana salimos."}]},"Du spielst super Fußball!":{de:"Danke! Ich spiele seit ich sechs bin.",es:"¡Gracias! Juego desde los seis años.",mas:[{de:"Bist du Anfänger oder schon fortgeschritten?",es:"¿Eres principiante o ya avanzado?"},{de:"Dazwischen. Für die erste Mannschaft reicht es nicht.",es:"Entre medias. Para el primer equipo no llega."},{de:"Hast du genug Ehrgeiz für den Wettkampf?",es:"¿Tienes suficiente ambición para la competición?"},{de:"Ehrlich gesagt nein. Ich spiele nur zum Spaß.",es:"Sinceramente no. Juego solo por diversión."},{de:"Das kann ich überhaupt nicht.",es:"Eso no sé hacerlo para nada."},{de:"Sag das nicht. Mit etwas Übung schon.",es:"No digas eso. Con algo de práctica sí."}]},"Was machst du in deiner Freizeit?":{de:"Vor allem draußen sein, am liebsten in den Bergen.",es:"Sobre todo estar fuera, mejor en la montaña.",mas:[{de:"Mein größtes Hobby ist Klettern.",es:"Mi mayor afición es la escalada."},{de:"Drinnen in der Halle oder draußen am Fels?",es:"¿Dentro en el rocódromo o fuera en roca?"},{de:"Was machst du am liebsten in deiner Freizeit?",es:"¿Qué es lo que más te gusta hacer en tu tiempo libre?"},{de:"Lange Spaziergänge, ohne Handy, ohne Ziel.",es:"Paseos largos, sin móvil, sin rumbo."},{de:"Was ist deine größte Leidenschaft?",es:"¿Cuál es tu mayor pasión?"},{de:"Die Berge. Alles andere kommt danach.",es:"Las montañas. Todo lo demás viene después."}]},"Ich will einen Deutschkurs machen.":{de:"Gute Idee. Welches Niveau brauchst du?",es:"Buena idea. ¿Qué nivel necesitas?",mas:[{de:"Ich will nächstes Jahr einen Kurs machen.",es:"El año que viene quiero hacer un curso."},{de:"Warum erst nächstes Jahr? Im Herbst fängt einer an.",es:"¿Por qué el año que viene? En otoño empieza uno."},{de:"Ich habe vor, im Sommer Spanisch zu lernen.",es:"Tengo pensado aprender español en verano."},{de:"Dann kann ich dir helfen, das ist meine Muttersprache.",es:"Entonces te puedo ayudar, es mi lengua materna."},{de:"Ich möchte gern Gitarre lernen.",es:"Me gustaría aprender a tocar la guitarra."},{de:"Fang einfach an. Mit dreißig ist das noch gut möglich.",es:"Empieza sin más. A los treinta todavía se puede."}]},"Wer hat gestern gewonnen?":{de:"Die Gäste, zwei zu eins in der letzten Minute.",es:"Los visitantes, dos a uno en el último minuto.",mas:[{de:"Wie ist das Spiel am Sonntag ausgegangen?",es:"¿Cómo acabó el partido del domingo?"},{de:"Unentschieden, null zu null. Sehr langweilig.",es:"Empate, cero a cero. Muy aburrido."},{de:"Unsere Mannschaft hat leider verloren.",es:"Nuestro equipo ha perdido."},{de:"Nächstes Mal. Ihr habt trotzdem gut gespielt.",es:"La próxima vez. Aun así jugasteis bien."},{de:"Wann ist das nächste Spiel?",es:"¿Cuándo es el próximo partido?"},{de:"Samstag um halb vier, wieder zu Hause.",es:"El sábado a las tres y media, otra vez en casa."}]},"Hast du Lust, am Samstag mitzukommen?":{de:"Sehr gern! Wohin geht es denn?",es:"¡Con mucho gusto! ¿Adónde vais?",mas:[{de:"Wir grillen am Sonntag, kommst du?",es:"El domingo hacemos barbacoa, ¿vienes?"},{de:"Ja, gern. Soll ich einen Salat mitbringen?",es:"Sí, con gusto. ¿Llevo una ensalada?"},{de:"Bring ruhig jemanden mit!",es:"¡Trae a quien quieras!"},{de:"Dann komme ich mit meiner Schwester, sie ist zu Besuch.",es:"Entonces voy con mi hermana, está de visita."},{de:"Ich lade dich zum Essen ein.",es:"Te invito a comer."},{de:"Das ist lieb, aber dann zahle ich das nächste Mal.",es:"Qué amable, pero la próxima pago yo."}]},"Das stimmt nicht.":{de:"Doch, ich habe es selbst gelesen.",es:"Que sí, lo he leído yo mismo.",mas:[{de:"Das stimmt so nicht ganz.",es:"Eso no es del todo así."},{de:"Gut, dann erklär mir, wie es wirklich war.",es:"Bien, entonces explícame cómo fue de verdad."},{de:"Überhaupt nicht, das war ganz anders.",es:"En absoluto, eso fue muy distinto."},{de:"Dann habe ich das wohl falsch verstanden.",es:"Entonces lo habré entendido mal."},{de:"Das kann eigentlich nicht stimmen.",es:"Eso no puede ser."},{de:"Schauen wir kurz nach, dann wissen wir es.",es:"Vamos a mirarlo y así lo sabemos."}]},"Guten Morgen! / Guten Tag! / Guten Abend!":{de:"Guten Morgen! Sie sind heute aber früh dran.",es:"¡Buenos días! Hoy viene usted pronto.",mas:[{de:"Guten Morgen, schön, dass Sie da sind!",es:"¡Buenos días, qué bien que esté aquí!"},{de:"Danke, ich freue mich auch. Wo soll ich mich hinsetzen?",es:"Gracias, yo también me alegro. ¿Dónde me siento?"},{de:"Guten Tag, Herr Müller!",es:"¡Buenas tardes, señor Müller!"},{de:"Guten Tag! Schön, dass wir uns hier treffen.",es:"¡Buenas tardes! Qué bien encontrarnos aquí."},{de:"Guten Abend allerseits!",es:"¡Buenas tardes/noches a todos!"},{de:"Guten Abend! Kommen Sie, es ist noch ein Platz frei.",es:"¡Buenas noches! Venga, queda un sitio libre."}]},"Auf Wiedersehen! · Tschüss! · Bis bald!":{de:"Auf Wiedersehen! Kommen Sie gut nach Hause.",es:"¡Adiós! Que llegue bien a casa.",mas:[{de:"Schönen Abend noch!",es:"¡Que pase buena tarde!"},{de:"Danke, Ihnen auch. Bis zum nächsten Mal.",es:"Gracias, igualmente. Hasta la próxima."},{de:"Bis nächste Woche im Kurs!",es:"¡Hasta la semana que viene en clase!"},{de:"Bis nächste Woche! Vergiss die Hausaufgabe nicht.",es:"¡Hasta la semana que viene! No olvides los deberes."},{de:"Schönen Sonntag noch!",es:"¡Que tengas un buen domingo!"},{de:"Danke, dir auch. Wir telefonieren am Montag.",es:"Gracias, igualmente. Hablamos el lunes."}]},"Wie heißen Sie? – Mein Name ist Gruber.":{de:"Freut mich, Frau Gruber. Ich bin die Kursleiterin.",es:"Encantada, señora Gruber. Soy la profesora del curso.",mas:[{de:"Wie heißen Sie mit Vornamen?",es:"¿Cuál es su nombre de pila?"},{de:"Eva. Aber alle sagen Evi zu mir.",es:"Eva. Pero todos me llaman Evi."},{de:"Und wie ist Ihr Nachname, bitte?",es:"¿Y su apellido, por favor?"},{de:"Gruber, mit einem B wie Berta.",es:"Gruber, con be de Berta."},{de:"Wie war Ihr Name noch einmal?",es:"¿Cómo era su nombre?"},{de:"Gruber. Kein Problem, das vergessen alle am ersten Tag.",es:"Gruber. No pasa nada, el primer día se le olvida a todos."}]},"Ich bin neu im Kurs, ich heiße Nuria.":{de:"Willkommen, Nuria! Setz dich einfach zu uns.",es:"¡Bienvenida, Nuria! Siéntate con nosotros.",mas:[{de:"Wir kennen uns noch nicht, oder?",es:"Todavía no nos conocemos, ¿no?"},{de:"Nein, noch nicht. Ich bin Clara.",es:"No, todavía no. Yo soy Clara."},{de:"Freut mich, ich bin David.",es:"Mucho gusto, soy David."},{de:"Freut mich auch, David. Bist du auch neu hier?",es:"Igualmente, David. ¿Tú también eres nuevo?"},{de:"Ich bin neu hier im Kurs.",es:"Soy nuevo en el curso."},{de:"Dann zeige ich dir gleich alles. Es ist ganz einfach.",es:"Entonces te enseño todo ahora. Es muy fácil."}]},"Wie geht's? – Danke, gut. Und dir?":{de:"Auch gut. Das Wochenende war schön lang.",es:"Bien también. El fin de semana fue bien largo.",mas:[{de:"Wie war dein Wochenende?",es:"¿Qué tal el fin de semana?"},{de:"Ruhig, viel geschlafen. Genau das brauchte ich.",es:"Tranquilo, dormí mucho. Justo lo que necesitaba."},{de:"Du wirkst heute so fröhlich.",es:"Hoy se te ve muy contento."},{de:"Bin ich auch. Ich habe die Prüfung bestanden!",es:"Lo estoy. ¡He aprobado el examen!"},{de:"Du wirkst heute so gut gelaunt.",es:"Hoy se te ve de muy buen humor."},{de:"Die Sonne scheint, und morgen habe ich frei.",es:"Hace sol y mañana libro."}]},"Woher kommst du? – Ich komme aus Spanien.":{de:"Aus Spanien! Und wo hast du so gut Deutsch gelernt?",es:"¡De España! ¿Y dónde has aprendido tan bien alemán?",mas:[{de:"Aus welcher Stadt kommst du genau?",es:"¿De qué ciudad eres exactamente?"},{de:"Aus Valencia, direkt am Meer.",es:"De Valencia, justo al lado del mar."},{de:"Und wo genau in Spanien liegt das?",es:"¿Y dónde está eso exactamente en España?"},{de:"An der Ostküste, etwa vier Stunden von Madrid.",es:"En la costa este, a unas cuatro horas de Madrid."},{de:"Wie lange lebst du schon in Österreich?",es:"¿Cuánto llevas viviendo en Austria?"},{de:"Seit drei Jahren. Die ersten Monate waren hart.",es:"Desde hace tres años. Los primeros meses fueron duros."}]},"Wie ist deine Telefonnummer? – 0664 123 45 67.":{de:"Moment, ich tippe mit. Null sechs sechs vier …",es:"Un momento, lo voy escribiendo. Cero seis seis cuatro…",mas:[{de:"Hast du eine neue Nummer?",es:"¿Tienes un número nuevo?"},{de:"Ja, seit letztem Monat. Die alte geht nicht mehr.",es:"Sí, desde el mes pasado. La antigua ya no funciona."},{de:"Unter welcher Nummer erreiche ich dich am besten?",es:"¿En qué número te localizo mejor?"},{de:"Am Handy, aber schreib lieber, ich telefoniere ungern.",es:"Al móvil, pero mejor escribe, no me gusta hablar por teléfono."},{de:"Wo wohnst du? – In Wien, Hauptstraße 12.",es:"¿Dónde vives? – En Viena, Hauptstraße 12."},{de:"Das ist ja ganz in meiner Nähe.",es:"Eso está muy cerca de mí."}]},"Wie schreibt man das?":{de:"Ich buchstabiere es Ihnen langsam.",es:"Se lo deletreo despacio.",mas:[{de:"Können Sie das bitte buchstabieren?",es:"¿Puede deletrearlo, por favor?"},{de:"Gern: G-R-U-B-E-R.",es:"Con gusto: G-R-U-B-E-R."},{de:"M wie Martha, A wie Anton.",es:"M de Martha, A de Anton."},{de:"Danke, so ist es viel klarer.",es:"Gracias, así está mucho más claro."},{de:"Können Sie den Namen langsam buchstabieren?",es:"¿Puede deletrear el nombre despacio?"},{de:"Natürlich, Buchstabe für Buchstabe.",es:"Por supuesto, letra por letra."}]},"Wie bitte? Können Sie das wiederholen?":{de:"Natürlich. Ich sagte: Übung vier auf Seite zwölf.",es:"Por supuesto. He dicho: ejercicio cuatro en la página doce.",mas:[{de:"Ich verstehe das nicht.",es:"No lo entiendo."},{de:"Kein Problem, ich erkläre es noch einmal anders.",es:"No pasa nada, lo explico otra vez de otra manera."},{de:"Langsamer, bitte!",es:"¡Más despacio, por favor!"},{de:"Entschuldigung, ich spreche viel zu schnell.",es:"Perdón, hablo demasiado rápido."},{de:"Können wir das noch einmal zusammen üben?",es:"¿Podemos practicarlo otra vez juntos?"},{de:"Gern, wir machen es in Ruhe zu zweit.",es:"Con gusto, lo hacemos con calma entre los dos."}]},"Entschuldigung, ich habe eine Frage.":{de:"Bitte, immer gern. Worum geht es?",es:"Adelante, con gusto. ¿De qué se trata?",mas:[{de:"Auf welcher Seite sind wir?",es:"¿En qué página estamos?"},{de:"Seite dreiundzwanzig, oben links.",es:"Página veintitrés, arriba a la izquierda."},{de:"Wo sind wir gerade?",es:"¿Por dónde vamos?"},{de:"Bei Aufgabe zwei b, der zweiten Zeile.",es:"En el ejercicio dos b, la segunda línea."},{de:"Können Sie das bitte an die Tafel schreiben?",es:"¿Puede escribirlo en la pizarra, por favor?"},{de:"Mache ich, dann können es alle abschreiben.",es:"Lo hago, así lo pueden copiar todos."}]},"Darf ich auf die Toilette gehen?":{de:"Natürlich, sie ist den Gang runter rechts.",es:"Por supuesto, está por el pasillo a la derecha.",mas:[{de:"Darf ich kurz auf die Toilette gehen?",es:"¿Puedo ir un momento al baño?"},{de:"Gehen Sie ruhig, wir warten mit der Übung.",es:"Vaya tranquilo, esperamos con el ejercicio."},{de:"Können wir eine kurze Pause machen?",es:"¿Podemos hacer una pausa corta?"},{de:"Gute Idee, zehn Minuten. Danach machen wir weiter.",es:"Buena idea, diez minutos. Después seguimos."},{de:"Darf ich heute früher gehen?",es:"¿Puedo irme hoy antes?"},{de:"Ja, aber sagen Sie mir kurz, warum.",es:"Sí, pero dígame brevemente por qué."}]},"Danke schön! – Bitte schön!":{de:"Gern geschehen, dafür bin ich ja da.",es:"De nada, para eso estoy.",mas:[{de:"Vielen Dank für die Hilfe.",es:"Muchas gracias por la ayuda."},{de:"Keine Ursache. Melden Sie sich einfach wieder.",es:"No hay de qué. Vuelva a avisarme cuando quiera."},{de:"Vielen Dank, das war sehr nett von Ihnen.",es:"Muchas gracias, ha sido muy amable."},{de:"Das mache ich doch gern für Sie.",es:"Lo hago con gusto por usted."},{de:"Kein Problem, schon gut!",es:"¡No hay problema, no pasa nada!"},{de:"Trotzdem danke, dass du so ruhig geblieben bist.",es:"Aun así, gracias por mantener la calma."}]},"Wie war dein Tag? – Ganz gut, danke.":{de:"Nur ganz gut? Erzähl, was war denn?",es:"¿Solo bastante bien? Cuenta, ¿qué ha pasado?",mas:[{de:"Ich habe den ganzen Tag gearbeitet.",es:"He trabajado todo el día."},{de:"Ohne Pause? Das ist zu viel.",es:"¿Sin pausa? Eso es demasiado."},{de:"Der Tag war anstrengend, aber schön.",es:"El día fue agotador, pero bonito."},{de:"So ist es am besten. Müde und zufrieden.",es:"Así es lo mejor. Cansado y contento."},{de:"Ich bin heute viel zu spät aufgestanden.",es:"Hoy me he levantado demasiado tarde."},{de:"Deshalb warst du im Kurs nicht da. Alles klar.",es:"Por eso no estabas en clase. Entendido."}]},"Ich habe den Zug verpasst.":{de:"Um wie viel? Der nächste fährt in einer halben Stunde.",es:"¿Por cuánto? El siguiente sale en media hora.",mas:[{de:"Wir hatten gestern eine Panne auf der Autobahn.",es:"Ayer tuvimos una avería en la autopista."},{de:"Oje! Habt ihr lange auf den Abschleppdienst gewartet?",es:"¡Vaya! ¿Esperasteis mucho a la grúa?"},{de:"Plötzlich ist der Strom ausgefallen.",es:"De repente se fue la luz."},{de:"Im ganzen Haus? Bei uns auch, so gegen acht.",es:"¿En toda la casa? A nosotros también, hacia las ocho."},{de:"Gestern war ich zum ersten Mal beim Zahnarzt hier.",es:"Ayer fui por primera vez al dentista aquí."},{de:"Und? War es anders als in Spanien?",es:"¿Y? ¿Fue distinto que en España?"}]},"Echt? · Wirklich? · Ach so!":{de:"Ja, ganz im Ernst. Ich war selbst überrascht.",es:"Sí, totalmente en serio. Yo también me sorprendí.",mas:[{de:"Ach wirklich?",es:"¿De verdad?"},{de:"Doch, so war es. Frag Anna, sie war dabei.",es:"Que sí, así fue. Pregunta a Anna, estaba allí."},{de:"Das ist ja interessant!",es:"¡Qué interesante!"},{de:"Nicht wahr? Davon hatte ich noch nie gehört.",es:"¿Verdad que sí? Nunca había oído hablar de eso."},{de:"Erzähl weiter, das klingt spannend!",es:"¡Sigue contando, suena interesante!"},{de:"Dann hör zu, der beste Teil kommt jetzt.",es:"Pues escucha, ahora viene la mejor parte."}]},"Im Ernst? Das wusste ich gar nicht.":{de:"Wir haben es auch erst letzte Woche erfahren.",es:"Nosotros también lo supimos la semana pasada.",mas:[{de:"Das hätte ich nicht gedacht.",es:"No me lo habría imaginado."},{de:"Ich auch nicht. Man weiß nie, wie es kommt.",es:"Yo tampoco. Nunca se sabe cómo va a salir."},{de:"Da bin ich jetzt wirklich überrascht.",es:"Ahora sí que estoy sorprendido."},{de:"Setz dich lieber, es kommt noch mehr.",es:"Mejor siéntate, todavía hay más."},{de:"Erzähl mir mehr davon!",es:"¡Cuéntame más!"},{de:"Gern, aber dafür brauchen wir einen Kaffee.",es:"Con gusto, pero para eso necesitamos un café."}]},"Schönes Wetter heute, oder?":{de:"Endlich. Nach der Woche haben wir es verdient.",es:"Por fin. Después de esta semana nos lo merecemos.",mas:[{de:"Die Tage werden schon wieder kürzer.",es:"Los días ya se están acortando otra vez."},{de:"Stimmt, um acht ist es fast dunkel.",es:"Es verdad, a las ocho ya está casi oscuro."},{de:"Viel los heute, oder?",es:"Hay mucho movimiento hoy, ¿no?"},{de:"Immer am Monatsanfang. Da kommen alle gleichzeitig.",es:"Siempre a principios de mes. Vienen todos a la vez."},{de:"Der Kaffee hier ist gar nicht schlecht.",es:"El café de aquí no está nada mal."},{de:"Für einen Automaten sogar ziemlich gut.",es:"Para ser de máquina, incluso bastante bueno."}]},"Warten Sie schon lange?":{de:"Zwanzig Minuten. Angeblich kommt bald einer.",es:"Veinte minutos. Dicen que viene uno pronto.",mas:[{de:"Der Verkehr war heute besonders schlimm.",es:"Hoy el tráfico estaba especialmente mal."},{de:"Auf dem Gürtel stand alles. Eine Stunde für acht Kilometer.",es:"En el Gürtel estaba todo parado. Una hora para ocho kilómetros."},{de:"Haben Sie es weit nach Hause?",es:"¿Le queda lejos su casa?"},{de:"Vierzig Minuten, mit einmal Umsteigen.",es:"Cuarenta minutos, con un transbordo."},{de:"Kommen Sie oft hierher?",es:"¿Viene usted aquí a menudo?"},{de:"Jeden Dienstag. Man gewöhnt sich an den Warteraum.",es:"Todos los martes. Uno se acostumbra a la sala de espera."}]},"2015 bin ich nach Österreich gekommen.":{de:"Und wie war der Anfang?",es:"¿Y cómo fueron los principios?",mas:[{de:"Am Anfang war alles neu für mich.",es:"Al principio todo era nuevo para mí."},{de:"Das kann ich mir vorstellen. Mir ging es genauso.",es:"Me lo imagino. A mí me pasó lo mismo."},{de:"Die ersten Monate waren wirklich hart.",es:"Los primeros meses fueron muy duros."},{de:"Und wann ist es leichter geworden?",es:"¿Y cuándo se hizo más fácil?"},{de:"Mit der Zeit wurde alles leichter.",es:"Con el tiempo todo se fue haciendo más fácil."},{de:"So ist es bei fast allen. Man merkt es nur später.",es:"Así es en casi todos los casos. Solo se nota después."}]},"Ich möchte lieber nicht darüber sprechen.":{de:"In Ordnung, ich frage nicht weiter.",es:"De acuerdo, no pregunto más.",mas:[{de:"Darüber möchte ich jetzt nicht reden.",es:"De eso no quiero hablar ahora."},{de:"Kein Problem. Sag einfach, wenn es dir passt.",es:"No pasa nada. Dime cuando te venga bien."},{de:"Das ist mir zu privat, entschuldige.",es:"Eso es demasiado privado, perdona."},{de:"Entschuldige du, das war unpassend von mir.",es:"Perdona tú, ha sido poco apropiado por mi parte."},{de:"Lass uns bitte das Thema wechseln.",es:"Cambiemos de tema, por favor."},{de:"Gern. Hast du den Film am Sonntag gesehen?",es:"Con gusto. ¿Viste la película del domingo?"}]},"Entschuldigung, wie komme ich zum Rathaus?":{de:"Immer geradeaus, dann sehen Sie schon den Turm.",es:"Todo recto y ya verá la torre.",mas:[{de:"Ist das weit von hier?",es:"¿Está lejos de aquí?"},{de:"Zehn Minuten, höchstens zwölf.",es:"Diez minutos, doce como mucho."},{de:"Kann ich zu Fuß gehen?",es:"¿Puedo ir andando?"},{de:"Auf jeden Fall, mit dem Auto finden Sie keinen Parkplatz.",es:"Desde luego, en coche no encuentra aparcamiento."},{de:"Wie weit ist es bis ins Zentrum?",es:"¿Qué distancia hay hasta el centro?"},{de:"Etwa zwei Kilometer. Mit der Straßenbahn drei Stationen.",es:"Unos dos kilómetros. En tranvía, tres paradas."}]},"Ist es weit von hier? – Nein, fünf Minuten zu Fuß.":{de:"Gut, dann gehe ich. Immer geradeaus?",es:"Bien, entonces voy andando. ¿Todo recto?",mas:[{de:"Gehen Sie geradeaus und dann die zweite Straße rechts.",es:"Vaya todo recto y luego la segunda a la derecha."},{de:"Die zweite, nicht die erste. Verstanden.",es:"La segunda, no la primera. Entendido."},{de:"Muss ich über die Brücke?",es:"¿Tengo que cruzar el puente?"},{de:"Ja, und danach gleich wieder links am Wasser entlang.",es:"Sí, y después enseguida a la izquierda junto al agua."},{de:"Wie lange brauche ich ungefähr?",es:"¿Cuánto tardo más o menos?"},{de:"Eine knappe Viertelstunde, wenn Sie zügig gehen.",es:"Un cuarto de hora escaso si va rápido."}]},"Welche Linie muss ich nehmen?":{de:"Die U1, Richtung Leopoldau.",es:"La U1, dirección Leopoldau.",mas:[{de:"Wo muss ich umsteigen?",es:"¿Dónde tengo que hacer transbordo?"},{de:"Bei Praterstern, dort in die U2.",es:"En Praterstern, allí a la U2."},{de:"Wie viele Stationen sind das?",es:"¿Cuántas paradas son?"},{de:"Vier bis zum Umsteigen, dann noch zwei.",es:"Cuatro hasta el transbordo y luego dos más."},{de:"Muss ich irgendwo umsteigen?",es:"¿Tengo que hacer transbordo en algún sitio?"},{de:"Diesmal nicht, der Bus fährt direkt durch.",es:"Esta vez no, el autobús va directo."}]},"Nehmen Sie die U3 und steigen Sie bei Stephansplatz um.":{de:"Und dann? In welche Linie?",es:"¿Y luego? ¿A qué línea?",mas:[{de:"Sie müssen drei Stationen fahren.",es:"Tiene que ir tres paradas."},{de:"Drei Stationen, dann bin ich da. Danke!",es:"Tres paradas y ya estoy. ¡Gracias!"},{de:"Ist das die richtige Richtung?",es:"¿Es esta la dirección correcta?"},{de:"Nein, Sie müssen auf die andere Seite wechseln.",es:"No, tiene que cambiar al otro lado."},{de:"Wie lange dauert es bis zum Flughafen?",es:"¿Cuánto se tarda al aeropuerto?"},{de:"Mit der S-Bahn fünfundzwanzig Minuten.",es:"Con el cercanías, veinticinco minutos."}]},"Die Fahrkarten, bitte.":{de:"Einen Moment, ich habe sie in der Jacke.",es:"Un momento, las tengo en la chaqueta.",mas:[{de:"Gilt das Ticket auch für die Straßenbahn?",es:"¿El billete vale también para el tranvía?"},{de:"Ja, für alle Öffis in der Kernzone.",es:"Sí, para todo el transporte público de la zona central."},{de:"Ist das Ticket auch im Vorort gültig?",es:"¿El billete vale también en las afueras?"},{de:"Nein, dafür brauchen Sie eine Zusatzkarte.",es:"No, para eso necesita un suplemento."},{de:"Brauche ich ein extra Ticket?",es:"¿Necesito un billete aparte?"},{de:"Für das Rad ja, für den Hund nicht.",es:"Para la bici sí, para el perro no."}]},"Ist dieser Platz noch frei?":{de:"Ja, bitte. Die Tasche nehme ich weg.",es:"Sí, por favor. Quito la bolsa.",mas:[{de:"Entschuldigung, das ist mein reservierter Platz.",es:"Perdone, ese es mi asiento reservado."},{de:"Oh, Entschuldigung! Ich setze mich woanders hin.",es:"¡Ay, perdone! Me siento en otro sitio."},{de:"Können Sie mir mit dem Koffer helfen?",es:"¿Me puede ayudar con la maleta?"},{de:"Natürlich, ich hebe ihn Ihnen hoch.",es:"Por supuesto, se la subo."},{de:"Hält dieser Zug in Wels?",es:"¿Este tren para en Wels?"},{de:"Nein, der fährt durch. Sie müssen in Linz umsteigen.",es:"No, pasa de largo. Tiene que cambiar en Linz."}]},"Ich habe mich verlaufen.":{de:"Kein Problem, wo wollen Sie denn hin?",es:"No pasa nada, ¿adónde quiere ir?",mas:[{de:"Ich glaube, ich habe mich verlaufen.",es:"Creo que me he perdido."},{de:"Zeig mal das Handy, ich schaue kurz nach.",es:"Enséñame el móvil, lo miro un momento."},{de:"Ich habe mich total verlaufen.",es:"Me he perdido del todo."},{de:"Bleib, wo du bist. Ich hole dich ab.",es:"Quédate donde estás. Te recojo."},{de:"Weißt du, wo wir gerade sind?",es:"¿Sabes dónde estamos ahora mismo?"},{de:"Ungefähr. Das da hinten ist der Donaukanal.",es:"Más o menos. Eso de allá atrás es el canal del Danubio."}]},"Wir stehen seit einer Stunde im Stau.":{de:"Gibt es eine Ausweichstrecke?",es:"¿Hay una ruta alternativa?",mas:[{de:"Ich komme bestimmt zu spät zum Termin.",es:"Seguro que llego tarde a la cita."},{de:"Ruf an und sag Bescheid, das verstehen alle.",es:"Llama y avisa, lo entiende todo el mundo."},{de:"Mein Handyakku ist leer.",es:"Se me ha acabado la batería del móvil."},{de:"Nimm meins, ich habe noch achtzig Prozent.",es:"Coge el mío, tengo el ochenta por ciento."},{de:"Sollen wir ein Taxi nehmen?",es:"¿Cogemos un taxi?"},{de:"Im Stau bringt das auch nichts. Wir warten.",es:"En el atasco tampoco sirve. Esperamos."}]},"Die Wohnung hat 60 m² und zwei Zimmer.":{de:"Für zwei Personen reicht das gut.",es:"Para dos personas está bien.",mas:[{de:"Unsere Wohnung hat fünfzig Quadratmeter.",es:"Nuestro piso tiene cincuenta metros cuadrados."},{de:"Und wie viele Zimmer sind das?",es:"¿Y cuántas habitaciones son?"},{de:"Die Wohnfläche ist kleiner als im Inserat.",es:"La superficie es menor que en el anuncio."},{de:"Das ist leider oft so. Hast du nachgemessen?",es:"Por desgracia pasa a menudo. ¿Lo has medido?"},{de:"Die Wohnung ist leider nicht möbliert.",es:"El piso no está amueblado."},{de:"Dann brauchst du erst mal ein Bett und einen Tisch.",es:"Entonces necesitas primero una cama y una mesa."}]},"Wie hoch ist die Miete?":{de:"Siebenhundertzwanzig Euro kalt.",es:"Setecientos veinte euros sin gastos.",mas:[{de:"Sind die Betriebskosten schon dabei?",es:"¿Están incluidos los gastos de comunidad?"},{de:"Nein, die kommen dazu, etwa hundertdreißig.",es:"No, van aparte, unos ciento treinta."},{de:"Wie hoch sind die Betriebskosten?",es:"¿Cuánto son los gastos de comunidad?"},{de:"Im Jahr etwa tausendsechshundert, monatlich verteilt.",es:"Al año unos mil seiscientos, repartidos por meses."},{de:"Was kostet die Wohnung im Monat?",es:"¿Cuánto cuesta el piso al mes?"},{de:"Alles zusammen knapp neunhundert Euro.",es:"Todo junto, casi novecientos euros."}]},"Wie groß ist die Wohnung?":{de:"Fünfundsechzig Quadratmeter, plus Balkon.",es:"Sesenta y cinco metros cuadrados, más balcón.",mas:[{de:"Gibt es einen Balkon?",es:"¿Hay balcón?"},{de:"Ja, nach Süden, mit Platz für einen kleinen Tisch.",es:"Sí, al sur, con sitio para una mesita."},{de:"Sie liegt im dritten Stock.",es:"Está en la tercera planta."},{de:"Und gibt es dafür einen Aufzug?",es:"¿Y hay ascensor para eso?"},{de:"Gibt es einen Aufzug?",es:"¿Hay ascensor?"},{de:"Leider nein. Dafür ist die Miete etwas niedriger.",es:"Por desgracia no. A cambio el alquiler es algo menor."}]},"Wir suchen seit drei Monaten eine Wohnung.":{de:"Der Markt ist hart. Was ist euer Budget?",es:"El mercado está duro. ¿Cuál es vuestro presupuesto?",mas:[{de:"Wie viele Zimmer hat die Wohnung?",es:"¿Cuántas habitaciones tiene el piso?"},{de:"Drei, plus Küche und Bad.",es:"Tres, más cocina y baño."},{de:"Wann kann ich die Wohnung besichtigen?",es:"¿Cuándo puedo ver el piso?"},{de:"Donnerstag um siebzehn Uhr, zusammen mit anderen.",es:"El jueves a las diecisiete, junto con otros."},{de:"Wann kann ich sie besichtigen?",es:"¿Cuándo puedo verlo?"},{de:"Wenn Donnerstag nicht passt, ginge auch Samstag früh.",es:"Si el jueves no va bien, también podría el sábado temprano."}]},"Das gefällt mir (nicht).":{de:"Sag ruhig ehrlich, was dich stört.",es:"Di con sinceridad qué te molesta.",mas:[{de:"Das Wohnzimmer gefällt mir sehr gut.",es:"El salón me gusta mucho."},{de:"Vor allem das große Fenster, oder?",es:"Sobre todo la ventana grande, ¿no?"},{de:"Ich finde das Zimmer sehr gemütlich.",es:"La habitación me parece muy acogedora."},{de:"Mit einem Teppich wird es noch wärmer.",es:"Con una alfombra será aún más cálida."},{de:"Das Zimmer ist wirklich gemütlich.",es:"La habitación es de verdad acogedora."},{de:"Dann nehmen wir es, oder? Ich bin überzeugt.",es:"Entonces lo cogemos, ¿no? Yo estoy convencido."}]},"Wie findest du die neue Küche?":{de:"Praktisch, aber sehr weiß. Fast wie im Labor.",es:"Práctica, pero muy blanca. Casi como un laboratorio.",mas:[{de:"Das ist mir zu modern.",es:"Eso es demasiado moderno para mí."},{de:"Was gefällt dir denn besser? Etwas aus Holz?",es:"¿Qué te gusta más? ¿Algo de madera?"},{de:"Das Sofa ist nicht mein Geschmack.",es:"El sofá no es de mi gusto."},{de:"Meins auch nicht, aber es ist sehr bequem.",es:"El mío tampoco, pero es muy cómodo."},{de:"Diese Jalousien sehen sehr altmodisch aus.",es:"Estas persianas parecen muy anticuadas."},{de:"Die sind aus den Achtzigern, das sieht man.",es:"Son de los ochenta, se nota."}]},"Haben Sie auch Regale?":{de:"Gleich hier hinten, eine ganze Abteilung.",es:"Aquí detrás, toda una sección.",mas:[{de:"Was kostet dieser Schrank?",es:"¿Cuánto cuesta este armario?"},{de:"Zweihundertneunzig, im Moment mit Rabatt.",es:"Doscientos noventa, ahora con descuento."},{de:"Was kostet dieser Tisch?",es:"¿Cuánto cuesta esta mesa?"},{de:"Hundertzwanzig. Die Stühle kosten extra.",es:"Ciento veinte. Las sillas van aparte."},{de:"Gibt es das auch in einer anderen Farbe?",es:"¿Lo tienen también en otro color?"},{de:"In Schwarz und in Naturholz, beides im Katalog.",es:"En negro y en madera natural, los dos en el catálogo."}]},"Guten Tag, wir sind neu eingezogen.":{de:"Herzlich willkommen! In welche Wohnung denn?",es:"¡Bienvenidos! ¿A qué piso?",mas:[{de:"Wir sind Ihre neuen Nachbarn von oben.",es:"Somos sus vecinos nuevos de arriba."},{de:"Sehr angenehm. Klopfen Sie, wenn Sie etwas brauchen.",es:"Mucho gusto. Llamen si necesitan algo."},{de:"Wir machen am Samstag eine kleine Feier.",es:"El sábado hacemos una fiestecita."},{de:"Danke fürs Bescheidsagen. Bis zehn ist alles erlaubt.",es:"Gracias por avisar. Hasta las diez todo vale."},{de:"Entschuldigung, war es gestern zu laut?",es:"Perdone, ¿ayer hubo demasiado ruido?"},{de:"Überhaupt nicht, wir haben nichts gehört.",es:"En absoluto, no hemos oído nada."}]},"Entschuldigung, bin ich hier richtig?":{de:"Das kommt darauf an. Worum geht es denn?",es:"Depende. ¿De qué se trata?",mas:[{de:"Ich möchte einen Ausweis beantragen.",es:"Quisiera solicitar un documento de identidad."},{de:"Dann sind Sie hier richtig. Nehmen Sie eine Nummer.",es:"Entonces está en el sitio correcto. Coja un número."},{de:"Welche Unterlagen brauche ich?",es:"¿Qué documentación necesito?"},{de:"Pass, Meldezettel und ein aktuelles Foto.",es:"Pasaporte, empadronamiento y una foto actual."},{de:"Zu welchem Schalter muss ich?",es:"¿A qué ventanilla tengo que ir?"},{de:"Schalter vier, aber warten Sie auf Ihre Nummer.",es:"Ventanilla cuatro, pero espere a su número."}]},"Wer ist für diesen Fall zuständig?":{de:"Frau Berger, Zimmer 204, im zweiten Stock.",es:"La señora Berger, sala 204, en la segunda planta.",mas:[{de:"Wie lange dauert die Bearbeitung?",es:"¿Cuánto tarda la tramitación?"},{de:"Vier bis sechs Wochen, im Sommer eher länger.",es:"De cuatro a seis semanas; en verano más bien más."},{de:"Wann bekomme ich den Bescheid?",es:"¿Cuándo recibiré la resolución?"},{de:"Sobald die Prüfung fertig ist, meist im Mai.",es:"En cuanto acabe la revisión, normalmente en mayo."},{de:"Wird mir der Bescheid zugeschickt?",es:"¿Me envían la resolución?"},{de:"Ja, per Post an die gemeldete Adresse.",es:"Sí, por correo a la dirección registrada."}]},"Vielen Dank für Ihre Hilfe.":{de:"Sehr gern geschehen. Melden Sie sich jederzeit.",es:"Con mucho gusto. Llámeme cuando quiera.",mas:[{de:"Vielen Dank für Ihre Auskunft.",es:"Muchas gracias por la información."},{de:"Kein Problem. Ich hoffe, es hat weitergeholfen.",es:"No hay problema. Espero que le haya servido."},{de:"Ich melde mich nächste Woche wieder.",es:"Vuelvo a ponerme en contacto la semana que viene."},{de:"Sehr gut, dann haben wir bis dahin die Antwort.",es:"Muy bien, para entonces tendremos la respuesta."},{de:"Auf Wiederhören!",es:"¡Hasta luego! (por teléfono)"},{de:"Auf Wiederhören, einen schönen Tag noch.",es:"Hasta luego, que tenga buen día."}]},"Darf ich hier parken?":{de:"Nur mit Parkschein, und höchstens zwei Stunden.",es:"Solo con tique, y dos horas como máximo.",mas:[{de:"Darf ich hier kurz stehen bleiben?",es:"¿Puedo pararme aquí un momento?"},{de:"Zum Ausladen ja, aber bleiben Sie beim Auto.",es:"Para descargar sí, pero quédese junto al coche."},{de:"Darf ich mich hier kurz hinsetzen?",es:"¿Me puedo sentar aquí un momento?"},{de:"Bitte, der Platz ist frei.",es:"Por favor, el sitio está libre."},{de:"Darf ich hier während der Wartezeit telefonieren?",es:"¿Puedo hablar por teléfono aquí mientras espero?"},{de:"Besser draußen im Gang, hier stört es die anderen.",es:"Mejor fuera en el pasillo, aquí molesta a los demás."}]},"Ja, das dürfen Sie. / Nein, das ist verboten.":{de:"Gut, dann weiß ich Bescheid. Danke.",es:"Bien, entonces ya lo sé. Gracias.",mas:[{de:"Darf man hier fotografieren?",es:"¿Se puede hacer fotos aquí?"},{de:"Im Hof ja, in den Büros nicht.",es:"En el patio sí, en las oficinas no."},{de:"Rauchen ist hier leider verboten.",es:"Aquí está prohibido fumar."},{de:"Verstehe. Gibt es draußen einen Platz dafür?",es:"Entiendo. ¿Hay un sitio fuera para eso?"},{de:"Ist es erlaubt, das mitzunehmen?",es:"¿Está permitido llevarse esto?"},{de:"Das Formular ja, den Stift bitte nicht.",es:"El formulario sí, el bolígrafo no, por favor."}]},"Normalerweise arbeite ich bis 17 Uhr.":{de:"Dann schaffen Sie es noch zum Amt, das schließt um sechs.",es:"Entonces llega a la oficina, cierra a las seis.",mas:[{de:"Normalerweise fange ich um acht an.",es:"Normalmente empiezo a las ocho."},{de:"Und wie lange dauert Ihr Weg in die Arbeit?",es:"¿Y cuánto tarda en llegar al trabajo?"},{de:"Meistens esse ich mittags in der Kantine.",es:"Casi siempre como al mediodía en el comedor."},{de:"Ist das Essen dort gut? Bei uns leider nicht.",es:"¿Se come bien allí? En el nuestro no."},{de:"Normalerweise mache ich das am Freitag.",es:"Normalmente eso lo hago el viernes."},{de:"Dann passt es ja, der Termin ist auch am Freitag.",es:"Entonces encaja, la cita también es el viernes."}]},"Sollen wir das zusammen machen?":{de:"Sehr gern, zu zweit geht es viel schneller.",es:"Con mucho gusto, entre dos va mucho más rápido.",mas:[{de:"Ja, gern. / Lieber nicht.",es:"Sí, con gusto. / Mejor no."},{de:"Dann sag mir einfach, was dir lieber ist.",es:"Entonces dime qué prefieres."},{de:"Sollen wir gleich anfangen?",es:"¿Empezamos ya?"},{de:"Ja, je früher wir anfangen, desto besser.",es:"Sí, cuanto antes empecemos, mejor."},{de:"Sollen wir den Bericht zusammen schreiben?",es:"¿Escribimos el informe juntos?"},{de:"Gute Idee. Du die Zahlen, ich den Text?",es:"Buena idea. ¿Tú los números y yo el texto?"}]},"Wie beginne ich so ein Schreiben?":{de:"Ganz formell, mit „Sehr geehrte Damen und Herren“.",es:"Muy formal, con «Sehr geehrte Damen und Herren».",mas:[{de:"Sehr geehrte Damen und Herren, ich wende mich an Sie wegen meines Antrags.",es:"Muy señores míos, me dirijo a ustedes por mi solicitud."},{de:"Perfekt. Danach kommt gleich, was Sie wollen.",es:"Perfecto. Después va directamente lo que quiere."},{de:"Hiermit beantrage ich …",es:"Por la presente solicito …"},{de:"Genau diese Formel erwarten die Ämter.",es:"Justo esa fórmula esperan en la administración."},{de:"Mit freundlichen Grüßen und vielen Dank im Voraus.",es:"Atentamente y gracias de antemano."},{de:"Und darunter die Unterschrift, dann ist es fertig.",es:"Y debajo la firma, y ya está."}]},"Vorsicht! · Pass auf!":{de:"Danke, das hätte ich fast übersehen.",es:"Gracias, casi no lo veo.",mas:[{de:"Vorsicht, der Boden ist nass!",es:"¡Cuidado, el suelo está mojado!"},{de:"Da sollte wirklich ein Schild stehen.",es:"Ahí debería haber un cartel."},{de:"Achtung, hier ist eine Stufe.",es:"Atención, aquí hay un escalón."},{de:"Gut, dass Sie es sagen, ich sehe schlecht.",es:"Menos mal que lo dice, veo mal."},{de:"Pass auf, das Wasser ist heiß.",es:"Ten cuidado, el agua está caliente."},{de:"Zu spät, ich habe mich schon verbrannt.",es:"Demasiado tarde, ya me he quemado."}]},"Wo genau tut es weh?":{de:"Hier unten rechts, direkt unter den Rippen.",es:"Aquí abajo a la derecha, justo bajo las costillas.",mas:[{de:"Seit wann haben Sie die Beschwerden?",es:"¿Desde cuándo tiene las molestias?"},{de:"Seit etwa einer Woche, aber es wird schlimmer.",es:"Desde hace una semana, pero va a peor."},{de:"Ist der Schmerz eher stechend oder dumpf?",es:"¿El dolor es más punzante o sordo?"},{de:"Dumpf, aber nachts wird er stechend.",es:"Sordo, pero por la noche se vuelve punzante."},{de:"Atmen Sie bitte ruhig weiter.",es:"Siga respirando con calma, por favor."},{de:"Das fällt mir gerade schwer, ehrlich gesagt.",es:"Ahora me cuesta, la verdad."}]},"Mein Kopf tut weh.":{de:"Seit wann? Und hast du genug getrunken?",es:"¿Desde cuándo? ¿Y has bebido suficiente?",mas:[{de:"Ich habe seit Tagen Kopfschmerzen.",es:"Llevo días con dolor de cabeza."},{de:"Dann geh lieber zum Arzt, das ist zu lang.",es:"Entonces mejor ve al médico, es demasiado tiempo."},{de:"Ich habe Fieber.",es:"Tengo fiebre."},{de:"Wie viel denn? Hast du schon gemessen?",es:"¿Cuánta? ¿Te la has tomado?"},{de:"Ich fühle mich nicht gut.",es:"No me encuentro bien."},{de:"Leg dich hin, ich bringe dir einen Tee.",es:"Túmbate, te traigo un té."}]},"Der Hals tut beim Schlucken weh.":{de:"Machen Sie bitte den Mund auf, ich schaue kurz.",es:"Abra la boca, por favor, miro un momento.",mas:[{de:"Ich habe Fieber, achtunddreißig fünf.",es:"Tengo fiebre, treinta y ocho y medio."},{de:"Seit wann genau? Und steigt es abends?",es:"¿Desde cuándo exactamente? ¿Y sube por la tarde?"},{de:"Ich kann kaum tief atmen.",es:"Casi no puedo respirar hondo."},{de:"Das schauen wir uns gleich genauer an.",es:"Eso lo miramos ahora con más detalle."},{de:"Die Schmerzen kommen und gehen.",es:"Los dolores van y vienen."},{de:"Gibt es einen Moment am Tag, an dem es schlimmer ist?",es:"¿Hay algún momento del día en que es peor?"}]},"Wie geht es dir? – Nicht so gut.":{de:"Was ist denn los? Erzähl.",es:"¿Qué pasa? Cuenta.",mas:[{de:"Mir geht es leider gar nicht gut.",es:"No me encuentro nada bien."},{de:"Soll ich dich zum Arzt begleiten?",es:"¿Te acompaño al médico?"},{de:"Ich schlafe seit Wochen schlecht.",es:"Llevo semanas durmiendo mal."},{de:"Das zieht alles andere mit runter. Sprich mit dem Arzt.",es:"Eso arrastra todo lo demás. Habla con el médico."},{de:"Heute fühle ich mich schon viel besser.",es:"Hoy ya me siento mucho mejor."},{de:"Sehr gut. Aber übertreib es noch nicht.",es:"Muy bien. Pero no te pases todavía."}]},"Gute Besserung! · Das tut mir leid.":{de:"Danke, das ist lieb von dir.",es:"Gracias, qué amable.",mas:[{de:"Gute Besserung, werde schnell gesund!",es:"¡Que te mejores, recupérate pronto!"},{de:"Ich gebe mir Mühe. Der Arzt sagt, eine Woche.",es:"Lo intento. El médico dice que una semana."},{de:"Gute Besserung, ruh dich gut aus!",es:"¡Que te mejores, descansa bien!"},{de:"Das mache ich. Sofa und Serien, den ganzen Tag.",es:"Eso haré. Sofá y series todo el día."},{de:"Melde dich, wenn du etwas brauchst.",es:"Avísame si necesitas algo."},{de:"Danke, ich weiß das wirklich zu schätzen.",es:"Gracias, te lo agradezco de verdad."}]},"Was würden Sie mir raten?":{de:"Zwei Tage Ruhe, viel trinken, und dann sehen wir.",es:"Dos días de reposo, beber mucho, y luego vemos.",mas:[{de:"Was hilft gegen Husten?",es:"¿Qué va bien para la tos?"},{de:"Warmer Tee mit Honig, und Dampf einatmen.",es:"Té caliente con miel y respirar vapor."},{de:"Was hilft am besten gegen Husten?",es:"¿Qué va mejor para la tos?"},{de:"Ehrlich gesagt: Zeit. Alles andere hilft nur ein bisschen.",es:"Sinceramente: el tiempo. Lo demás ayuda solo un poco."},{de:"Soll ich eine Tablette nehmen?",es:"¿Me tomo una pastilla?"},{de:"Bei Fieber über achtunddreißig fünf, ja.",es:"Con fiebre de más de treinta y ocho y medio, sí."}]},"Ich bin krank und kann heute nicht kommen.":{de:"Gute Besserung. Waren Sie schon beim Arzt?",es:"Que se mejore. ¿Ha ido ya al médico?",mas:[{de:"Ich war heute beim Hausarzt.",es:"Hoy he estado en el médico de cabecera."},{de:"Und was hat er gesagt?",es:"¿Y qué ha dicho?"},{de:"Ich bin voraussichtlich bis Freitag im Krankenstand.",es:"Previsiblemente estaré de baja hasta el viernes."},{de:"In Ordnung, ich sage dem Team Bescheid.",es:"De acuerdo, aviso al equipo."},{de:"Die Bestätigung schicke ich Ihnen morgen.",es:"Le envío el justificante mañana."},{de:"Das reicht völlig. Erholen Sie sich erst einmal.",es:"Con eso basta. Recupérese primero."}]},"Ich suche eine Hose in Größe 40.":{de:"In Vierzig haben wir die dunkelblauen und die grauen.",es:"En la cuarenta tenemos los azul oscuro y los grises.",mas:[{de:"Wo kann ich das anprobieren?",es:"¿Dónde me lo puedo probar?"},{de:"Die Umkleidekabinen sind ganz hinten links, neben den Schuhen.",es:"Los probadores están al fondo a la izquierda, junto a los zapatos."},{de:"Diese Hose ist mir zu weit.",es:"Este pantalón me queda ancho."},{de:"Dann bringe ich Ihnen die gleiche eine Nummer kleiner.",es:"Entonces le traigo el mismo una talla menos."},{de:"Haben Sie das auch in Blau?",es:"¿Lo tienen también en azul?"},{de:"In Blau leider nur noch in Größe achtunddreißig.",es:"En azul por desgracia solo queda la treinta y ocho."},{de:"Haben Sie das eine Nummer größer?",es:"¿Lo tienen una talla más grande?"},{de:"Im Lager schon. Ich hole es Ihnen, einen Moment.",es:"En el almacén sí. Se lo traigo, un momento."}]},"Ich brauche etwas Warmes für den Winter.":{de:"Dann schauen Sie sich diesen Mantel an, der ist aus Wolle.",es:"Entonces mire este abrigo, es de lana.",mas:[{de:"Hat die Jacke ein warmes Futter?",es:"¿La chaqueta tiene un forro cálido?"},{de:"Ja, ein dickes, und man kann es sogar herausnehmen.",es:"Sí, uno grueso, y además se puede quitar."},{de:"Der Stoff fühlt sich sehr angenehm an.",es:"La tela es muy agradable al tacto."},{de:"Nicht wahr? Und er kratzt überhaupt nicht am Hals.",es:"¿Verdad que sí? Y no pica nada en el cuello."},{de:"Der Ärmel ist mir viel zu lang.",es:"La manga me queda demasiado larga."},{de:"Das ändern wir Ihnen gern, das kostet nichts extra.",es:"Se lo arreglamos con gusto, no cuesta nada más."},{de:"Der Reißverschluss geht kaum zu.",es:"La cremallera casi no cierra."},{de:"Dann ist das Modell zu klein geschnitten. Nehmen Sie die nächste Größe.",es:"Entonces el modelo va justo de corte. Coja la talla siguiente."}]},"Das Kleid steht dir wirklich gut.":{de:"Findest du? Ich bin mir bei der Länge nicht sicher.",es:"¿Tú crees? No estoy segura del largo.",mas:[{de:"Das steht dir gut!",es:"¡Te queda bien!"},{de:"Danke! Dann nehme ich es, bevor ich es mir anders überlege.",es:"¡Gracias! Pues me lo llevo antes de cambiar de idea."},{de:"Das Muster ist mir zu auffällig.",es:"El estampado me parece demasiado llamativo."},{de:"Verstehe. Daneben hängt dasselbe Modell einfarbig.",es:"Entiendo. Al lado está el mismo modelo liso."},{de:"Mir gefällt die schlichte Variante besser.",es:"Me gusta más la versión sencilla."},{de:"Die kann man auch öfter anziehen, ohne dass es auffällt.",es:"Esa además se puede poner más veces sin que se note."},{de:"Das ist genau mein Stil.",es:"Ese es justo mi estilo."},{de:"Das sieht man. Es passt zu allem, was du sonst trägst.",es:"Se nota. Pega con todo lo que sueles llevar."}]},"Welches gefällt dir besser?":{de:"Ehrlich gesagt das linke, es wirkt hochwertiger.",es:"Sinceramente el de la izquierda, parece de más calidad.",mas:[{de:"Die blaue Jacke gefällt mir besser als die schwarze.",es:"La chaqueta azul me gusta más que la negra."},{de:"Die blaue ist aber auch dreißig Euro teurer.",es:"Pero la azul también cuesta treinta euros más."},{de:"Die ist billiger als die andere.",es:"Esa es más barata que la otra."},{de:"Billiger schon, aber der Stoff hält nicht so lange.",es:"Más barata sí, pero la tela no dura tanto."},{de:"Leder hält länger als Stoff.",es:"El cuero dura más que la tela."},{de:"Stimmt, dafür ist es am Anfang deutlich teurer.",es:"Es verdad, a cambio al principio es bastante más caro."},{de:"Am liebsten kaufe ich im Ausverkauf.",es:"Lo que más me gusta es comprar en rebajas."},{de:"Dann warte noch zwei Wochen, dann fängt er an.",es:"Pues espera dos semanas, entonces empiezan."}]},"Ich hätte gern einen Termin.":{de:"Gern, wann passt es Ihnen?",es:"Claro, ¿cuándo le va bien?",mas:[{de:"Am liebsten hätte ich es bis Freitag.",es:"Lo querría idealmente para el viernes."},{de:"Freitag wird knapp, aber Donnerstagnachmittag ginge sicher.",es:"El viernes va justo, pero el jueves por la tarde seguro que sí."},{de:"Ich würde gern noch etwas anderes sehen.",es:"Me gustaría ver algo más."},{de:"Natürlich, ich zeige Ihnen die neue Kollektion von hinten.",es:"Por supuesto, le enseño la colección nueva del fondo."},{de:"Könnte ich das bitte eingepackt bekommen?",es:"¿Me lo podría envolver, por favor?"},{de:"Sehr gern, als Geschenk? Dann nehme ich das schöne Papier.",es:"Con mucho gusto, ¿es para regalo? Uso el papel bonito."},{de:"Ich hätte gern einen Gutschein statt Geld.",es:"Quisiera un vale en vez del dinero."},{de:"Kein Problem, der ist drei Jahre lang gültig.",es:"No hay problema, vale para tres años."}]},"Ich möchte das umtauschen. Hier ist der Kassenbon.":{de:"Danke. Was stimmt denn nicht damit?",es:"Gracias. ¿Qué le pasa?",mas:[{de:"Der Reißverschluss ist kaputt.",es:"La cremallera está rota."},{de:"Das sehe ich. Das war schon beim Kauf so, oder?",es:"Ya lo veo. Eso ya venía así, ¿no?"},{de:"Auf dem Hemd ist ein Fleck.",es:"En la camisa hay una mancha."},{de:"Dann tauschen wir es selbstverständlich um, ohne Diskussion.",es:"Entonces se lo cambiamos, por supuesto, sin discusión."},{de:"Bekomme ich das Geld zurück?",es:"¿Me devuelven el dinero?"},{de:"Bei einem Mangel ja, sonst nur einen Gutschein.",es:"Con un defecto sí; si no, solo un vale."},{de:"Bis wann kann ich es abholen?",es:"¿Hasta cuándo puedo recogerlo?"},{de:"Ab Donnerstag liegt es hier, wir rufen Sie vorher an.",es:"Desde el jueves está aquí, le llamamos antes."}]},"Ich habe online bestellt, aber nichts bekommen.":{de:"Haben Sie die Bestellnummer? Dann schaue ich gleich nach.",es:"¿Tiene el número de pedido? Así lo miro ahora.",mas:[{de:"Wann kommt die Lieferung?",es:"¿Cuándo llega la entrega?"},{de:"Laut System morgen, zwischen acht und zwölf Uhr.",es:"Según el sistema mañana, entre las ocho y las doce."},{de:"Die Sohle hat sich nach zwei Wochen gelöst.",es:"La suela se ha despegado a las dos semanas."},{de:"Nach zwei Wochen ist das ganz klar ein Garantiefall.",es:"A las dos semanas eso es claramente garantía."},{de:"Ist auf das Teil noch Garantie?",es:"¿Esta prenda todavía tiene garantía?"},{de:"Zwei Jahre ab Kaufdatum, Sie sind also gut dabei.",es:"Dos años desde la compra, así que va bien de tiempo."},{de:"Können Sie die Schuhe reparieren?",es:"¿Puede reparar los zapatos?"},{de:"Die Sohle ja, das dauert etwa eine Woche.",es:"La suela sí, tarda una semana más o menos."}]},"Ich finde das zu teuer für die Qualität.":{de:"Da hast du recht, der Stoff ist wirklich dünn.",es:"En eso tienes razón, la tela es muy fina.",mas:[{de:"Für mich ist Qualität wichtiger als der Preis.",es:"Para mí la calidad importa más que el precio."},{de:"Auf lange Sicht ist das sogar billiger, finde ich.",es:"A la larga incluso sale más barato, creo yo."},{de:"Meiner Meinung nach ist das Angebot gut.",es:"En mi opinión la oferta es buena."},{de:"Nur gilt es leider nur bis Samstag.",es:"Solo que por desgracia vale solo hasta el sábado."},{de:"Das sehe ich anders, und zwar deshalb:",es:"Yo lo veo distinto, y por esto:"},{de:"Sag ruhig, vielleicht überzeugst du mich noch.",es:"Dilo, a lo mejor me convences."},{de:"Das schaffen wir!",es:"¡Esto lo conseguimos!"},{de:"Genau, zu zweit finden wir bestimmt etwas Passendes.",es:"Exacto, entre los dos seguro que encontramos algo."}]},"Hast du kurz Zeit für eine Frage?":{de:"Klar, setz dich. Worum geht es denn?",es:"Claro, siéntate. ¿De qué se trata?",mas:[{de:"Ich komme mit dem Formular nicht weiter.",es:"No avanzo con el formulario."},{de:"Zeig mal her. Ah, hier fehlt die Steuernummer.",es:"Déjame ver. Ah, aquí falta el número fiscal."},{de:"Ich verstehe die Anleitung nicht.",es:"No entiendo las instrucciones."},{de:"Die ist auch schlecht geschrieben. Ich erkläre es dir einfacher.",es:"Es que están mal escritas. Te lo explico más fácil."},{de:"Könntest du das noch einmal erklären?",es:"¿Podrías explicarlo otra vez?"},{de:"Gern, und diesmal Schritt für Schritt, mit dem Papier vor uns.",es:"Con gusto, y esta vez paso a paso, con el papel delante."},{de:"Kannst du kurz drüberschauen?",es:"¿Le puedes echar un vistazo?"},{de:"Sieht gut aus. Nur unten fehlt noch deine Unterschrift.",es:"Tiene buena pinta. Solo falta tu firma abajo."}]},"Hättest du kurz Zeit für mich?":{de:"Jetzt gerade schon, in einer Stunde nicht mehr.",es:"Ahora mismo sí, dentro de una hora ya no.",mas:[{de:"Kannst du mir zeigen, wie ich das hochlade?",es:"¿Me enseñas cómo subo esto?"},{de:"Ganz einfach: Datei auswählen, dann auf den blauen Knopf.",es:"Muy fácil: eliges el archivo y luego el botón azul."},{de:"Mein Speicher ist voll, was mache ich?",es:"Tengo la memoria llena, ¿qué hago?"},{de:"Lösch erst die alten Videos, die brauchen den meisten Platz.",es:"Borra primero los vídeos viejos, son los que más ocupan."},{de:"Könntest du mir beim Brief helfen?",es:"¿Me podrías ayudar con la carta?"},{de:"Sehr gern. Formelle Briefe sind hier wirklich eine eigene Kunst.",es:"Con mucho gusto. Las cartas formales aquí son todo un arte."},{de:"Kannst du mich morgen daran erinnern?",es:"¿Me lo puedes recordar mañana?"},{de:"Mache ich, ich schreibe es mir gleich in den Kalender.",es:"Lo hago, lo apunto ahora en el calendario."}]},"Ich hoffe, dass alles gut geht.":{de:"Das wird es. Du hast alles vorbereitet, was du konntest.",es:"Irá bien. Has preparado todo lo que podías.",mas:[{de:"Ich hoffe, das Visum kommt rechtzeitig.",es:"Espero que el visado llegue a tiempo."},{de:"Normalerweise dauert es vier Wochen, du bist gut dran.",es:"Normalmente tarda cuatro semanas, vas bien de tiempo."},{de:"Ich verspreche dir, ich melde mich morgen.",es:"Te prometo que mañana te aviso."},{de:"Darauf zähle ich. Ruf einfach an, wenn du etwas weißt.",es:"Cuento con ello. Llama en cuanto sepas algo."},{de:"Ich kümmere mich darum, versprochen.",es:"Me ocupo de ello, prometido."},{de:"Danke, dann kann ich beruhigt ins Wochenende gehen.",es:"Gracias, así me voy tranquilo al fin de semana."},{de:"Ich hoffe, wir sehen uns bald wieder.",es:"Espero que nos veamos pronto."},{de:"Ganz bestimmt. Im Sommer bin ich sowieso wieder hier.",es:"Seguro. En verano vuelvo a estar aquí de todas formas."}]},"Wohin fährst du im Urlaub?":{de:"Nach Kroatien, ans Meer, wie jedes Jahr.",es:"A Croacia, al mar, como cada año.",mas:[{de:"Warst du schon einmal in Kroatien?",es:"¿Has estado alguna vez en Croacia?"},{de:"Dreimal schon. Die Inseln im Süden sind die schönsten.",es:"Ya tres veces. Las islas del sur son las más bonitas."},{de:"Wie lange bleibt ihr dort?",es:"¿Cuánto os quedáis allí?"},{de:"Zwei Wochen, im August. Länger geht es leider nicht.",es:"Dos semanas, en agosto. Por desgracia más no puede ser."},{de:"Habt ihr schon eine Unterkunft?",es:"¿Ya tenéis alojamiento?"},{de:"Eine kleine Wohnung direkt am Hafen, schon gebucht.",es:"Un apartamento pequeño junto al puerto, ya reservado."},{de:"Was kann man dort machen?",es:"¿Qué se puede hacer allí?"},{de:"Schwimmen, wandern, und abends stundenlang draußen essen.",es:"Nadar, caminar y por la noche cenar fuera durante horas."}]},"Wann fahrt ihr los?":{de:"Samstag um vier Uhr früh, damit wir dem Stau entkommen.",es:"El sábado a las cuatro de la mañana, para escapar del atasco.",mas:[{de:"Nimmst du viel Gepäck mit?",es:"¿Llevas mucho equipaje?"},{de:"Einen Koffer und einen Rucksack, mehr passt nicht ins Auto.",es:"Una maleta y una mochila, más no cabe en el coche."},{de:"Braucht man für dieses Land ein Visum?",es:"¿Para este país hace falta visado?"},{de:"Innerhalb der EU nicht, der Ausweis reicht völlig.",es:"Dentro de la UE no, basta con el documento."},{de:"Ist die Reise teuer geworden?",es:"¿Ha salido caro el viaje?"},{de:"Teurer als letztes Jahr, vor allem die Unterkunft.",es:"Más caro que el año pasado, sobre todo el alojamiento."},{de:"Lohnt sich die Reise wirklich?",es:"¿Merece la pena el viaje?"},{de:"Jeden Cent. Nach zwei Wochen dort bin ich ein anderer Mensch.",es:"Cada céntimo. Después de dos semanas allí soy otra persona."}]},"Ich interessiere mich sehr für Geschichte.":{de:"Dann bist du in Wien genau richtig, hier ist alles alt.",es:"Entonces Viena es tu sitio, aquí todo es antiguo.",mas:[{de:"Technik finde ich wirklich spannend.",es:"La tecnología me parece muy interesante."},{de:"Warst du schon im Technischen Museum? Das würde dir gefallen.",es:"¿Has estado en el Museo Técnico? Te gustaría."},{de:"Am liebsten lese ich über andere Länder.",es:"Lo que más me gusta es leer sobre otros países."},{de:"Deshalb weißt du über jedes Land etwas zu erzählen.",es:"Por eso tienes algo que contar de cada país."},{de:"Kochen interessiert mich überhaupt nicht.",es:"La cocina no me interesa nada."},{de:"Und trotzdem kochst du besser als die meisten hier.",es:"Y aun así cocinas mejor que la mayoría de aquí."},{de:"Sport interessiert mich mehr als Musik.",es:"Me interesa más el deporte que la música."},{de:"Bei mir ist es genau umgekehrt, deshalb passen wir gut zusammen.",es:"A mí me pasa al revés, por eso encajamos bien."}]},"Warum lernst du Deutsch?":{de:"Wegen der Arbeit, aber inzwischen auch, weil es mir gefällt.",es:"Por el trabajo, pero ya también porque me gusta.",mas:[{de:"Was ist dein Ziel?",es:"¿Cuál es tu meta?"},{de:"Mein Ziel ist die B1-Prüfung.",es:"Mi meta es el examen B1."},{de:"Was fällt dir am schwersten?",es:"¿Qué es lo que más te cuesta?"},{de:"Die Artikel. Der, die, das sind mein täglicher Feind.",es:"Los artículos. Der, die, das son mi enemigo diario."},{de:"Wie oft übst du?",es:"¿Cada cuánto practicas?"},{de:"Jeden Tag zwanzig Minuten, lieber kurz als gar nicht.",es:"Veinte minutos al día; mejor poco que nada."},{de:"Merkst du selbst Fortschritte?",es:"¿Notas tú mismo que progresas?"},{de:"Ja, beim Telefonieren. Früher hatte ich richtig Angst davor.",es:"Sí, al hablar por teléfono. Antes me daba verdadero miedo."}]},"Wie lernst du am effektivsten?":{de:"Ich lerne am besten mit Musik und Serien.",es:"Aprendo mejor con música y series.",mas:[{de:"Was hilft dir beim Vokabelnlernen?",es:"¿Qué te ayuda a aprender vocabulario?"},{de:"Karten, und die Wörter immer in einem ganzen Satz.",es:"Fichas, y las palabras siempre en una frase entera."},{de:"Ohne Wiederholung vergesse ich alles wieder.",es:"Sin repaso se me vuelve a olvidar todo."},{de:"Deshalb wiederhole ich sonntags alles von der ganzen Woche.",es:"Por eso los domingos repaso todo lo de la semana."},{de:"Die Aussprache ist mein größtes Problem.",es:"La pronunciación es mi mayor problema."},{de:"Nimm dich einmal auf. Beim Zuhören hörst du es sofort.",es:"Grábate una vez. Al escucharte lo notas enseguida."},{de:"Woher nimmst du die Motivation?",es:"¿De dónde sacas la motivación?"},{de:"Aus den kleinen Erfolgen. Letzte Woche habe ich einen Witz verstanden.",es:"De los pequeños logros. La semana pasada entendí un chiste."}]},"Bei uns feiert man Weihnachten am 24.":{de:"Hier auch. Und wann gibt es bei euch die Geschenke?",es:"Aquí también. ¿Y cuándo son los regalos?",mas:[{de:"Bei uns isst man am 24. erst spät am Abend.",es:"Donde yo vivo el día 24 se cena tarde."},{de:"Wie spät denn? Hier sitzen alle schon um sechs am Tisch.",es:"¿Cómo de tarde? Aquí todos están a la mesa a las seis."},{de:"In Spanien feiert man bis in die Nacht.",es:"En España se celebra hasta la madrugada."},{de:"Das würde meiner Familie überhaupt nicht gefallen.",es:"Eso a mi familia no le gustaría nada."},{de:"Den Christbaum schmücken wir erst am Vierundzwanzigsten.",es:"El árbol lo decoramos el veinticuatro."},{de:"Wirklich erst dann? Bei uns steht er schon Anfang Dezember.",es:"¿De verdad hasta entonces? En mi casa está desde principios de diciembre."},{de:"Feiert ihr Geburtstage immer so groß?",es:"¿Siempre celebráis los cumpleaños a lo grande?"},{de:"Nur die runden. Sonst gibt es einfach Kuchen im Büro.",es:"Solo los redondos. Si no, simplemente hay tarta en la oficina."}]},"Ich lade dich zu meinem Geburtstag ein.":{de:"Wie schön! Wann feierst du denn?",es:"¡Qué bien! ¿Cuándo lo celebras?",mas:[{de:"Ich feiere am Samstag, kommst du?",es:"Lo celebro el sábado, ¿vienes?"},{de:"Sehr gern. Wo denn, bei dir zu Hause?",es:"Con mucho gusto. ¿Dónde, en tu casa?"},{de:"Passt dir Samstag um acht?",es:"¿Te va bien el sábado a las ocho?"},{de:"Acht ist perfekt, da bin ich mit der Arbeit fertig.",es:"Las ocho es perfecto, ya he acabado de trabajar."},{de:"Wir würden uns sehr freuen, wenn du kommst.",es:"Nos encantaría que vinieras."},{de:"Das ist lieb. Ich komme auf jeden Fall.",es:"Qué amable. Voy seguro."},{de:"Kommst du zur Hochzeit im Juni?",es:"¿Vienes a la boda de junio?"},{de:"Natürlich! Schick mir die Einladung mit der Adresse.",es:"¡Por supuesto! Mándame la invitación con la dirección."}]},"Vielen Dank für die Einladung!":{de:"Gern! Es wäre schön, wenn du dabei bist.",es:"¡De nada! Estaría bien que vinieras.",mas:[{de:"Sehr gern, ich komme!",es:"¡Con mucho gusto, voy!"},{de:"Super, dann sind wir vollzählig.",es:"Genial, entonces estamos todos."},{de:"Um wie viel Uhr soll ich da sein?",es:"¿A qué hora tengo que estar allí?"},{de:"Ab sieben, aber komm ruhig etwas später.",es:"A partir de las siete, pero puedes venir algo más tarde."},{de:"Soll ich etwas mitbringen?",es:"¿Llevo algo?"},{de:"Wenn du magst, einen Nachtisch. Sonst ist alles da.",es:"Si quieres, un postre. Por lo demás está todo."},{de:"Darf ich jemanden mitbringen?",es:"¿Puedo llevar a alguien?"},{de:"Klar, je mehr Leute, desto besser.",es:"Claro, cuanta más gente, mejor."}]},"Machen wir uns für den Jahreswechsel etwas aus?":{de:"Unbedingt. Letztes Jahr saß ich allein vor dem Fernseher.",es:"Sin falta. El año pasado estuve solo delante de la tele.",mas:[{de:"Wo machen wir uns aus?",es:"¿Dónde nos vemos?"},{de:"Bei mir, ich habe genug Platz für alle.",es:"En mi casa, tengo sitio de sobra."},{de:"Wir haben uns für halb acht ausgemacht.",es:"Hemos quedado a las siete y media."},{de:"Gut, dann bin ich um Viertel nach sieben da.",es:"Bien, entonces estoy a las siete y cuarto."},{de:"Bring bitte nichts mit, wir haben alles.",es:"No traigas nada, tenemos de todo."},{de:"Dann bringe ich nur mich und gute Laune mit.",es:"Entonces llevo solo a mí mismo y buen humor."},{de:"Bleibt es bei unserer Ausmachung?",es:"¿Sigue en pie lo que quedamos?"},{de:"Es bleibt dabei, ich freue mich schon.",es:"Sigue en pie, ya tengo ganas."}]},"Die Wohnung sieht wunderschön aus!":{de:"Danke! Wir haben den ganzen Tag aufgeräumt.",es:"¡Gracias! Hemos estado ordenando todo el día.",mas:[{de:"Die Tischdecke und die Kerzen sehen festlich aus.",es:"El mantel y las velas dan un aire de fiesta."},{de:"Das war die Idee von meiner Schwester.",es:"Eso fue idea de mi hermana."},{de:"Das Essen schmeckt fantastisch.",es:"La comida está buenísima."},{de:"Das freut mich! Das Rezept ist von meiner Großmutter.",es:"¡Me alegro! La receta es de mi abuela."},{de:"Der Kuchen ist der beste, den ich kenne.",es:"Es la mejor tarta que conozco."},{de:"Dann bekommst du das Rezept, aber sag es niemandem.",es:"Entonces te doy la receta, pero no se lo digas a nadie."},{de:"Du hast das toll organisiert.",es:"Lo has organizado estupendamente."},{de:"Danke, aber ohne die anderen wäre das nichts geworden.",es:"Gracias, pero sin los demás no habría salido."}]},"Was möchtest du trinken?":{de:"Ein Glas Wasser erst mal, später gern ein Glas Wein.",es:"Un vaso de agua de momento; luego una copa de vino.",mas:[{de:"Nimm dir doch! · Greif zu!",es:"¡Sírvete! · ¡Coge!"},{de:"Danke, das sieht alles so gut aus.",es:"Gracias, tiene todo muy buena pinta."},{de:"Greif bitte zu, es ist genug da!",es:"¡Sírvete, hay de sobra!"},{de:"Dann nehme ich noch einmal von dem Salat.",es:"Entonces repito de la ensalada."},{de:"Möchtest du noch ein Stück Torte?",es:"¿Quieres otro trozo de tarta?"},{de:"Ein kleines, ich bin eigentlich schon satt.",es:"Uno pequeño, la verdad es que ya estoy lleno."},{de:"Stoßen wir gemeinsam an?",es:"¿Brindamos juntos?"},{de:"Unbedingt. Auf die Gastgeber und auf das neue Jahr!",es:"Sin falta. ¡Por los anfitriones y por el año nuevo!"}]},"Entschuldige die Verspätung!":{de:"Kein Problem, wir haben gerade erst angefangen.",es:"No pasa nada, acabamos de empezar.",mas:[{de:"Tut mir leid, der Bus hatte Verspätung.",es:"Lo siento, el bus venía con retraso."},{de:"Das kennen wir alle. Komm rein, es gibt noch alles.",es:"Eso nos pasa a todos. Pasa, queda de todo."},{de:"Entschuldige, ich habe das Geschenk vergessen.",es:"Perdona, se me ha olvidado el regalo."},{de:"Das ist doch egal, wichtig ist, dass du da bist.",es:"Da igual, lo importante es que estés."},{de:"Es tut mir leid, dass ich nicht geantwortet habe.",es:"Siento no haber contestado."},{de:"Ich dachte schon, du bist mir böse.",es:"Ya pensaba que estabas enfadado conmigo."},{de:"Das war mein Fehler, ich mache es neu.",es:"Fue error mío, lo hago otra vez."},{de:"Danke, dass du das so offen sagst.",es:"Gracias por decirlo tan claro."}]},"Das ist Pekka, er arbeitet mit mir im Labor.":{de:"Freut mich, Pekka! Und woher kommst du?",es:"¡Encantado, Pekka! ¿Y de dónde eres?",mas:[{de:"Das ist Pekka. Er kommt aus Finnland.",es:"Este es Pekka. Es de Finlandia."},{de:"Aus Finnland! Dann ist dir der Winter hier zu mild.",es:"¡De Finlandia! Entonces el invierno aquí te parece suave."},{de:"Sie ist sehr hilfsbereit und immer gut gelaunt.",es:"Es muy servicial y siempre está de buen humor."},{de:"Das merkt man sofort, wenn man mit ihr spricht.",es:"Se nota enseguida al hablar con ella."},{de:"Sie hat das ganze Fest organisiert.",es:"Ella ha organizado toda la fiesta."},{de:"Dann muss ich mich unbedingt bei ihr bedanken.",es:"Entonces tengo que darle las gracias sin falta."},{de:"Wir kennen uns schon aus der Schule.",es:"Nos conocemos ya del colegio."},{de:"So lange schon? Dann habt ihr sicher gute Geschichten.",es:"¿Tanto tiempo? Entonces tendréis buenas historias."}]},"Mein größter Wunsch ist ein sicherer Job.":{de:"Das verstehe ich gut. Ohne das plant man nichts.",es:"Lo entiendo bien. Sin eso no se planea nada.",mas:[{de:"Ich hoffe auf eine feste Stelle im Herbst.",es:"Espero un puesto fijo en otoño."},{de:"Hat dein Chef schon etwas angedeutet?",es:"¿Tu jefe ha dado alguna señal?"},{de:"Ich hätte gern mehr Ruhe im Alltag.",es:"Me gustaría tener más calma en el día a día."},{de:"Das geht mir genauso. Alles ist immer gleichzeitig.",es:"A mí me pasa igual. Todo es siempre a la vez."},{de:"Ich wünschte, ich hätte früher angefangen.",es:"Ojalá hubiera empezado antes."},{de:"Das sagt jeder. Wichtig ist, dass du angefangen hast.",es:"Eso lo dice todo el mundo. Lo importante es que empezaste."},{de:"Diese Chance lasse ich nicht vorbeigehen.",es:"Esta oportunidad no la dejo pasar."},{de:"Genau richtig. So etwas kommt selten zweimal.",es:"Muy bien. Algo así rara vez se repite."}]},"Damals bin ich nach Österreich gekommen.":{de:"Und wie war der Anfang?",es:"¿Y cómo fueron los principios?",mas:[{de:"Am Anfang war alles fremd für mich.",es:"Al principio todo me resultaba extraño."},{de:"Das glaube ich dir. Mir ging es genauso.",es:"Te creo. A mí me pasó lo mismo."},{de:"Damals habe ich kein Wort Deutsch gesprochen.",es:"Entonces no hablaba ni una palabra de alemán."},{de:"Und heute unterhalten wir uns ganz normal. Respekt.",es:"Y hoy charlamos con normalidad. Respeto."},{de:"Meine erste Wohnung war winzig und kalt.",es:"Mi primer piso era diminuto y frío."},{de:"Solche Wohnungen kennt hier fast jeder vom Anfang.",es:"Esos pisos los conoce aquí casi todo el mundo del principio."},{de:"Ich habe die Entscheidung nie bereut.",es:"Nunca me arrepentí de la decisión."},{de:"Das ist das Schönste, was man dazu sagen kann.",es:"Eso es lo mejor que se puede decir al respecto."}]},"Was hast du vorher gemacht?":{de:"Ich habe zu Hause als Buchhalter gearbeitet, acht Jahre lang.",es:"En mi país trabajé de contable, ocho años.",mas:[{de:"Wann hast du dich entschieden?",es:"¿Cuándo lo decidiste?"},{de:"Nach der Krise, als die Firma zugemacht hat.",es:"Después de la crisis, cuando cerró la empresa."},{de:"Das Praktikum war für mich der Wendepunkt.",es:"Las prácticas fueron para mí el punto de inflexión."},{de:"Inwiefern? Hat sich danach alles geändert?",es:"¿En qué sentido? ¿Después cambió todo?"},{de:"Damals habe ich sehr an mir gezweifelt.",es:"Entonces dudaba mucho de mí mismo."},{de:"Das hätte ich dir nie angesehen, ehrlich gesagt.",es:"Nunca lo habría dicho al verte, la verdad."},{de:"Hat sich der Aufwand gelohnt?",es:"¿Mereció la pena el esfuerzo?"},{de:"Absolut. Heute würde ich es genauso wieder machen.",es:"Absolutamente. Hoy lo volvería a hacer igual."}]},"Und wie ging es dann weiter?":{de:"Dann habe ich eine Arbeit gefunden, erst halbtags.",es:"Después encontré un trabajo, primero a media jornada.",mas:[{de:"Und was hast du dann gemacht?",es:"¿Y qué hiciste después?"},{de:"Ich habe abends den Kurs gemacht und tagsüber gearbeitet.",es:"Hacía el curso por la tarde y trabajaba de día."},{de:"Wie hast du dich dabei gefühlt?",es:"¿Cómo te sentiste?"},{de:"Müde, aber zum ersten Mal wieder nützlich.",es:"Cansado, pero por primera vez otra vez útil."},{de:"Das kann ich gut nachvollziehen.",es:"Lo puedo entender perfectamente."},{de:"Danke. Es tut gut, wenn jemand das versteht.",es:"Gracias. Sienta bien que alguien lo entienda."},{de:"Erzähl weiter, das interessiert mich wirklich.",es:"Sigue contando, me interesa de verdad."},{de:"Gern, aber dafür brauchen wir noch einen Kaffee.",es:"Con gusto, pero para eso necesitamos otro café."}]},"Mir fehlt manchmal meine Familie.":{de:"Das muss schwer sein, so weit weg von allen.",es:"Debe de ser duro, tan lejos de todos.",mas:[{de:"Das Heimweh kommt meistens im Winter.",es:"La morriña llega casi siempre en invierno."},{de:"Kein Wunder, wenn es hier um vier dunkel wird.",es:"No me extraña, si aquí a las cuatro es de noche."},{de:"Ich hatte lange Angst, Fehler zu machen.",es:"Durante mucho tiempo tuve miedo de cometer errores."},{de:"Das muss viel Mut gekostet haben, trotzdem zu sprechen.",es:"Eso debió de costar mucho valor, hablar igualmente."},{de:"Ohne Zuversicht hätte ich aufgegeben.",es:"Sin confianza en el futuro habría abandonado."},{de:"Das tut mir leid für dich. Aber du hast es geschafft.",es:"Lo siento mucho por ti. Pero lo has conseguido."},{de:"Und wie war das für dich gefühlsmäßig?",es:"¿Y cómo te sentías con todo aquello?"},{de:"Lange sehr einsam. Heute bin ich froh, geblieben zu sein.",es:"Mucho tiempo muy solo. Hoy me alegro de haberme quedado."}]},"Der Termin ist am Montag. Entschuldigung, ich meine …":{de:"Kein Stress, nimm dir Zeit.",es:"Sin prisa, tómate tu tiempo.",mas:[{de:"Entschuldigung, ich meine natürlich Dienstag.",es:"Perdón, quiero decir el martes, claro."},{de:"Gut, dass du es sagst, ich hätte es notiert.",es:"Menos mal que lo dices, lo habría apuntado."},{de:"Entschuldige, ich habe mich versprochen.",es:"Perdona, me he equivocado al hablar."},{de:"Passiert jedem, vor allem in einer Fremdsprache.",es:"Le pasa a todo el mundo, sobre todo en otro idioma."},{de:"Das habe ich falsch ausgedrückt.",es:"Eso lo he expresado mal."},{de:"Sag es einfach noch einmal, ich höre zu.",es:"Dilo otra vez sin más, te escucho."},{de:"Ich fange lieber noch einmal von vorne an.",es:"Mejor empiezo otra vez desde el principio."},{de:"Mach das, so wird es für uns beide klarer.",es:"Hazlo, así queda más claro para los dos."}]},"Wie hast du dich in der ersten Woche gefühlt?":{de:"Völlig verloren. Am Anfang war alles fremd.",es:"Completamente perdido. Al principio todo me resultaba ajeno.",mas:[{de:"Hattest du Heimweh?",es:"¿Tenías morriña?"},{de:"Jeden Abend, die ersten Monate.",es:"Todas las noches, los primeros meses."},{de:"Der Zusammenhalt im Kurs hat mir geholfen.",es:"La unión en clase me ayudó."},{de:"Das glaube ich sofort. Ihr wart ja alle in derselben Lage.",es:"Me lo creo enseguida. Estabais todos en la misma situación."},{de:"Ich war stolz, als ich das erste Mal telefoniert habe.",es:"Estaba orgulloso la primera vez que hablé por teléfono."},{de:"Das ist ein echter Moment. Telefonieren ist am schwersten.",es:"Ese es un momento de verdad. Lo del teléfono es lo más difícil."},{de:"Ich fühle mich hier inzwischen zu Hause.",es:"Ya me siento aquí como en casa."},{de:"Schön zu hören. Genau das wünscht man jedem.",es:"Qué bien oírlo. Justo eso se le desea a cualquiera."}]},"Was sind deine Pläne für die nächsten Jahre?":{de:"Erst mal will ich mich einfach hier einleben.",es:"De momento solo quiero adaptarme aquí.",mas:[{de:"Wo siehst du dich in fünf Jahren?",es:"¿Dónde te ves dentro de cinco años?"},{de:"Hoffentlich hier, mit einer festen Stelle und eigener Wohnung.",es:"Ojalá aquí, con un puesto fijo y piso propio."},{de:"Vielleicht mache ich noch eine Ausbildung.",es:"Quizá haga todavía una formación."},{de:"In welchem Bereich denn? Etwas Technisches?",es:"¿En qué sector? ¿Algo técnico?"},{de:"Ich möchte irgendwann ein eigenes Geschäft haben.",es:"Algún día quiero tener mi propio negocio."},{de:"Das traue ich dir zu. Du hast den langen Atem dafür.",es:"Te veo capaz. Tienes la constancia para eso."},{de:"Was ist dein nächstes großes Ziel?",es:"¿Cuál es tu siguiente gran objetivo?"},{de:"Die B1-Prüfung im Juni, alles andere kommt danach.",es:"El examen B1 en junio; lo demás viene después."}]},"Hast du Lust, morgen vorbeizukommen?":{de:"Sehr gern. Um welche Zeit passt es dir?",es:"Con mucho gusto. ¿A qué hora te va bien?",mas:[{de:"Wollen wir am Sonntag zusammen kochen?",es:"¿Cocinamos juntos el domingo?"},{de:"Gute Idee! Ich bringe die Zutaten für die Paella mit.",es:"¡Buena idea! Yo llevo los ingredientes de la paella."},{de:"Wir grillen am Samstag, seid ihr dabei?",es:"El sábado hacemos barbacoa, ¿os apuntáis?"},{de:"Auf jeden Fall. Sollen wir etwas zu trinken mitbringen?",es:"Desde luego. ¿Llevamos algo de beber?"},{de:"Bring ruhig jemanden mit, es ist genug da.",es:"Trae a quien quieras, hay de sobra."},{de:"Dann komme ich mit meiner Schwester, sie ist zu Besuch.",es:"Entonces voy con mi hermana, está de visita."},{de:"Du bist jederzeit willkommen bei uns.",es:"Eres bienvenido en nuestra casa cuando quieras."},{de:"Das ist wirklich lieb. Das weiß ich sehr zu schätzen.",es:"Qué amable de verdad. Lo aprecio mucho."}]},"Ich möchte dich zum Essen einladen.":{de:"Sehr gern! Wann hattest du denn gedacht?",es:"¡Con mucho gusto! ¿Cuándo habías pensado?",mas:[{de:"Wir feiern nichts Großes, nur ein paar Freunde.",es:"No celebramos nada grande, solo unos amigos."},{de:"Genau so mag ich es am liebsten.",es:"Así es como más me gusta."},{de:"Was soll ich zum Essen beisteuern?",es:"¿Qué aporto para la comida?"},{de:"Einen Nachtisch, wenn du magst. Sonst ist alles da.",es:"Un postre, si quieres. Por lo demás está todo."},{de:"Da bin ich auf jeden Fall dabei!",es:"¡Ahí estoy seguro!"},{de:"Super, dann sage ich den anderen Bescheid.",es:"Genial, entonces aviso a los demás."},{de:"Leider schaffe ich es diesmal nicht.",es:"Esta vez no llego."},{de:"Schade! Aber wir holen das nächsten Monat nach.",es:"¡Qué pena! Pero lo recuperamos el mes que viene."}]},"Kommt ihr am Sonntag zum Essen?":{de:"Gern! Um wie viel Uhr sollen wir da sein?",es:"¡Con gusto! ¿A qué hora vamos?",mas:[{de:"Wir servieren um acht, kommt ihr vorher?",es:"Servimos a las ocho, ¿venís antes?"},{de:"Wir sind um halb acht da, dann können wir noch helfen.",es:"Estamos a las siete y media, así podemos ayudar."},{de:"Ich habe etwas Spanisches gekocht.",es:"He cocinado algo español."},{de:"Wie schön! Das kennen wir hier viel zu wenig.",es:"¡Qué bien! Aquí eso se conoce muy poco."},{de:"Zieht ihr drinnen die Schuhe aus?",es:"¿Os quitáis los zapatos dentro?"},{de:"Bei uns schon, aber macht es, wie es euch lieber ist.",es:"En nuestra casa sí, pero haced lo que prefiráis."},{de:"Wir haben leider nur wenig Platz.",es:"Lo siento, tenemos poco sitio."},{de:"Das macht nichts, eng sitzen ist auch gemütlich.",es:"No importa, estar apretados también es acogedor."}]},"Haben Sie noch einen Tisch für zwei frei?":{de:"Drinnen ja, draußen müssten Sie zwanzig Minuten warten.",es:"Dentro sí; fuera tendrían que esperar veinte minutos.",mas:[{de:"Wir hätten gern die Speisekarte.",es:"Quisiéramos la carta."},{de:"Hier bitte. Die Tagesempfehlung steht auf der Tafel.",es:"Aquí tienen. La sugerencia del día está en la pizarra."},{de:"Was können Sie heute empfehlen?",es:"¿Qué nos recomienda hoy?"},{de:"Den Tafelspitz, der ist heute besonders gut geworden.",es:"El tafelspitz, hoy ha salido especialmente bueno."},{de:"Ich nehme das Schnitzel mit Erdäpfelsalat.",es:"Yo tomo el escalope con ensalada de patata."},{de:"Sehr gern. Und für Sie, dasselbe oder etwas anderes?",es:"Con mucho gusto. ¿Y para usted, lo mismo u otra cosa?"},{de:"Zahlen, bitte! – Getrennt oder zusammen?",es:"¡La cuenta! – ¿Por separado o junto?"},{de:"Getrennt bitte, und stimmt so, der Rest ist für Sie.",es:"Por separado, por favor, y está bien así, el resto para usted."}]},"Können wir draußen im Gastgarten sitzen?":{de:"Natürlich, dort hinten ist gerade ein Tisch frei geworden.",es:"Por supuesto, allí atrás acaba de quedar una mesa libre.",mas:[{de:"Ist in dem Gericht Fleisch drin?",es:"¿Ese plato lleva carne?"},{de:"In der Soße ist Speck, aber wir machen es auch ohne.",es:"En la salsa hay panceta, pero también lo hacemos sin."},{de:"Können Sie das ohne Zwiebeln machen?",es:"¿Lo pueden hacer sin cebolla?"},{de:"Kein Problem, ich sage es gleich in der Küche.",es:"No hay problema, lo digo ahora en la cocina."},{de:"Entschuldigung, das habe ich nicht bestellt.",es:"Perdone, esto no lo he pedido."},{de:"Oh, das tut mir leid! Ich bringe Ihnen sofort das Richtige.",es:"¡Ay, lo siento! Le traigo enseguida lo correcto."},{de:"Das Essen hat wirklich gut geschmeckt.",es:"La comida estaba buenísima."},{de:"Das freut uns. Ich sage es dem Koch gern weiter.",es:"Nos alegra. Se lo digo al cocinero con gusto."}]},"Ich habe morgen die Prüfung und schlafe schon nicht mehr.":{de:"Keine Sorge, das schaffst du!",es:"No te preocupes, ¡lo consigues!",mas:[{de:"Und wenn ich beim Sprechen stecken bleibe?",es:"¿Y si me atasco al hablar?"},{de:"Das kann jedem passieren, ehrlich. Atme einfach kurz durch.",es:"Le puede pasar a cualquiera, de verdad. Respira un momento."},{de:"Ich habe Angst, dass ich zu langsam bin.",es:"Tengo miedo de ir demasiado lento."},{de:"Nimm dir einfach etwas mehr Zeit dafür.",es:"Tómate simplemente algo más de tiempo para eso."},{de:"Meinst du wirklich, ich soll es versuchen?",es:"¿De verdad crees que debería intentarlo?"},{de:"Probier es einfach, du kannst nichts verlieren.",es:"Pruébalo, no tienes nada que perder."},{de:"Danke, das beruhigt mich wirklich.",es:"Gracias, eso me tranquiliza de verdad."},{de:"Mach dir keinen Stress, wir haben genug Zeit zum Üben.",es:"No te agobies, tenemos tiempo de sobra para practicar."}]},"Bei uns isst man das ganz anders.":{de:"Wirklich? Erzähl, wie macht ihr das?",es:"¿De verdad? Cuenta, ¿cómo lo hacéis?",mas:[{de:"So etwas gibt es bei uns auch, nur mit Fisch.",es:"Algo así existe también en mi tierra, pero con pescado."},{de:"Mit Fisch? Das würde ich gern einmal probieren.",es:"¿Con pescado? Eso me gustaría probarlo."},{de:"Bei uns isst man viel später am Abend.",es:"En mi tierra se cena mucho más tarde."},{de:"Um wie viel Uhr denn? Hier essen wir um sieben.",es:"¿A qué hora? Aquí cenamos a las siete."},{de:"Bei uns kocht man mit viel mehr Olivenöl.",es:"En mi tierra se cocina con mucho más aceite de oliva."},{de:"Das schmeckt man sofort, und es ist auch gesünder.",es:"Se nota enseguida, y además es más sano."},{de:"Die Portionen sind hier viel größer.",es:"Aquí las raciones son mucho más grandes."},{de:"Stimmt. Am Anfang habe ich nie aufessen können.",es:"Es verdad. Al principio nunca podía terminármelo."}]},"Das ist alles hausgemacht? Wirklich?":{de:"Alles, sogar das Brot und die Nudeln.",es:"Todo, hasta el pan y la pasta.",mas:[{de:"Wirklich? Das wusste ich überhaupt nicht.",es:"¿En serio? No lo sabía en absoluto."},{de:"Die Familie macht das seit drei Generationen so.",es:"La familia lo hace así desde hace tres generaciones."},{de:"Das hätte ich nie gedacht!",es:"¡Nunca lo habría pensado!"},{de:"Deshalb dauert es hier auch etwas länger.",es:"Por eso aquí también tarda algo más."},{de:"Echt jetzt? Das kann nicht sein.",es:"¿En serio? No puede ser."},{de:"Doch, frag den Kellner, er erzählt es dir gern.",es:"Que sí, pregunta al camarero, te lo cuenta con gusto."},{de:"Damit hätte ich nie gerechnet.",es:"Con eso no habría contado nunca."},{de:"Genau deshalb komme ich immer wieder hierher.",es:"Justo por eso vuelvo siempre aquí."}]},"Wollen wir am Samstag joggen gehen?":{de:"Gern, aber bitte nicht vor acht Uhr früh.",es:"Con gusto, pero por favor no antes de las ocho.",mas:[{de:"Ich schlage vor, wir treffen uns im Park.",es:"Propongo que quedemos en el parque."},{de:"Beim großen Eingang? Da finde ich immer einen Platz.",es:"¿En la entrada grande? Ahí siempre encuentro sitio."},{de:"Sollen wir uns vorher kurz aufwärmen?",es:"¿Calentamos un poco antes?"},{de:"Unbedingt, sonst tut mir nachher wieder das Knie weh.",es:"Sin falta, si no luego me duele la rodilla otra vez."},{de:"Sollen wir uns für den Lauf anmelden?",es:"¿Nos apuntamos a la carrera?"},{de:"Machen wir. Fünf Kilometer schaffen wir beide locker.",es:"Hagámoslo. Cinco kilómetros los hacemos los dos de sobra."},{de:"Wie wäre es mit einem Ruhetag?",es:"¿Qué tal un día de descanso?"},{de:"Guter Punkt. Ohne Pause wird man nur langsamer.",es:"Buen punto. Sin descanso uno solo va más lento."}]},"Super Idee, das machen wir!":{de:"Freut mich, dass du auch Lust hast.",es:"Me alegra que también te apetezca.",mas:[{de:"Ja, gern. Wann und wo treffen wir uns?",es:"Sí, con gusto. ¿Cuándo y dónde quedamos?"},{de:"Samstag um neun, direkt beim Sportplatz.",es:"El sábado a las nueve, junto al campo de deportes."},{de:"Genau darauf hatte ich Lust.",es:"Justo eso me apetecía."},{de:"Dann passt es ja perfekt. Ich melde uns beide an.",es:"Entonces encaja perfecto. Nos apunto a los dos."},{de:"Warum eigentlich nicht? Machen wir.",es:"¿Y por qué no? Lo hacemos."},{de:"So gefällst du mir. Einmal probieren kostet nichts.",es:"Así me gustas. Probar una vez no cuesta nada."},{de:"Einverstanden, ich bin beim Wettkampf dabei.",es:"De acuerdo, me apunto a la competición."},{de:"Sehr gut, dann trainieren wir ab Montag zusammen.",es:"Muy bien, entonces entrenamos juntos desde el lunes."}]},"Kommst du am Sonntag zum Fußball?":{de:"Ohne mich, ich hasse Mannschaftssport.",es:"Sin mí, odio los deportes de equipo.",mas:[{de:"Und beim Marathon im Mai?",es:"¿Y en el maratón de mayo?"},{de:"Das ist mir ehrlich gesagt zu anstrengend.",es:"Sinceramente, eso me parece demasiado duro."},{de:"Dann komm wenigstens ins Fitnessstudio mit.",es:"Pues vente al menos al gimnasio."},{de:"Ich habe leider gerade kein Geld dafür.",es:"Ahora mismo no tengo dinero para eso."},{de:"Verstehe. Und einfach eine Runde laufen, heute Abend?",es:"Entiendo. ¿Y simplemente correr un rato esta tarde?"},{de:"Lieber ein anderes Mal, heute bin ich kaputt.",es:"Mejor otro día, hoy estoy hecho polvo."},{de:"Dann sag du mir, worauf du Lust hättest.",es:"Entonces dime tú qué te apetecería."},{de:"Schwimmen. Alles andere ist wirklich nichts für mich.",es:"Nadar. Todo lo demás de verdad no es para mí."}]},"Joggen ist super, aber das Fitnessstudio finde ich langweilig.":{de:"Da bin ich ganz bei dir. Drinnen vergeht die Zeit nicht.",es:"En eso estoy contigo. Dentro el tiempo no pasa.",mas:[{de:"Das Fitnessstudio ist mir zu teuer.",es:"El gimnasio me sale demasiado caro."},{de:"Fünfzig Euro im Monat, und im Sommer geht sowieso keiner hin.",es:"Cincuenta euros al mes, y en verano no va nadie."},{de:"Schwimmen finde ich richtig gesund.",es:"Nadar me parece muy sano."},{de:"Vor allem für den Rücken. Das sagt auch mein Arzt.",es:"Sobre todo para la espalda. También lo dice mi médico."},{de:"Ich halte Yoga für unterschätzt.",es:"Creo que el yoga está infravalorado."},{de:"Bis man es einmal macht. Danach tut alles weh.",es:"Hasta que lo haces una vez. Después duele todo."},{de:"Ich finde den Beitrag ziemlich fair.",es:"La cuota me parece bastante justa."},{de:"Für zweimal die Woche Training auf jeden Fall.",es:"Para entrenar dos veces por semana desde luego."}]},"Ich mag Mannschaftssport lieber als Einzelsport.":{de:"Warum? Wegen der Leute oder wegen des Spiels?",es:"¿Por qué? ¿Por la gente o por el juego?",mas:[{de:"Ich trainiere am liebsten allein.",es:"Prefiero entrenar solo."},{de:"Dann bist du das genaue Gegenteil von mir.",es:"Entonces eres justo lo contrario que yo."},{de:"Am liebsten trainiere ich früh am Morgen.",es:"Lo que más me gusta es entrenar por la mañana temprano."},{de:"Um sechs? Da schlafe ich noch tief und fest.",es:"¿A las seis? A esa hora yo duermo profundamente."},{de:"Ich bewege mich lieber in der Natur.",es:"Prefiero moverme en la naturaleza."},{de:"Verstehe ich gut. Im Wald läuft es sich ganz anders.",es:"Lo entiendo. En el bosque se corre de otra manera."},{de:"Ohne Musik kann ich nicht trainieren.",es:"Sin música no puedo entrenar."},{de:"Bei mir ist es umgekehrt, ich brauche die Ruhe.",es:"A mí me pasa al revés, necesito el silencio."}]},"Machst du regelmäßig Sport?":{de:"Dreimal die Woche, seit etwa zwei Jahren.",es:"Tres veces por semana, desde hace unos dos años.",mas:[{de:"Wo trainierst du im Winter?",es:"¿Dónde entrenas en invierno?"},{de:"In der Halle vom Verein, draußen ist es mir zu glatt.",es:"En el pabellón del club, fuera resbala demasiado."},{de:"Wie lange trainierst du am Stück?",es:"¿Cuánto entrenas seguido?"},{de:"Eine Stunde, danach lässt die Konzentration nach.",es:"Una hora; después baja la concentración."},{de:"Achtest du auch auf die Ernährung?",es:"¿Cuidas también la alimentación?"},{de:"Seit dem letzten Wettkampf ja, das macht viel aus.",es:"Desde la última competición sí, influye mucho."},{de:"Hast du dich schon einmal verletzt?",es:"¿Te has lesionado alguna vez?"},{de:"Einmal das Knie. Seitdem wärme ich mich immer auf.",es:"Una vez la rodilla. Desde entonces caliento siempre."}]},"Wie war das Spiel am Wochenende?":{de:"Das Spiel gestern war eine Katastrophe.",es:"El partido de ayer fue un desastre.",mas:[{de:"Habt ihr in der Halbzeit geführt?",es:"¿Ibais ganando en el descanso?"},{de:"Zwei zu null, und dann ist alles auseinandergefallen.",es:"Dos a cero, y luego todo se desmoronó."},{de:"Wie viele Zuschauer waren im Stadion?",es:"¿Cuántos espectadores había en el estadio?"},{de:"Etwa dreihundert. Bei dem Regen war das schon viel.",es:"Unos trescientos. Con esa lluvia ya era mucho."},{de:"Das Spiel war absolut fair.",es:"El partido fue absolutamente deportivo."},{de:"Das stimmt, keine einzige gelbe Karte.",es:"Es verdad, ni una sola tarjeta amarilla."},{de:"Der Erfolg kommt nicht von allein.",es:"El éxito no llega solo."},{de:"Deshalb trainieren wir ab jetzt einen Tag mehr.",es:"Por eso a partir de ahora entrenamos un día más."}]},"Heute fehlt mir einfach die Kraft.":{de:"Hast du heute Muskelkater?",es:"¿Tienes agujetas hoy?",mas:[{de:"Überall, vor allem in den Beinen.",es:"Por todas partes, sobre todo en las piernas."},{de:"Dann mach heute nur leichte Bewegung, das hilft mehr.",es:"Entonces hoy solo movimiento suave, ayuda más."},{de:"Was machst du gegen den inneren Schweinehund?",es:"¿Qué haces contra la pereza?"},{de:"Ich lege die Schuhe abends schon vor die Tür.",es:"Dejo las zapatillas por la noche junto a la puerta."},{de:"Beweglichkeit ist mir wichtiger als Kraft.",es:"La flexibilidad me importa más que la fuerza."},{de:"Mit vierzig sieht man das plötzlich ganz anders.",es:"A los cuarenta eso se ve de repente muy distinto."},{de:"Der Kurs hat sich wirklich gelohnt.",es:"El curso ha merecido mucho la pena."},{de:"Das war die beste Entscheidung seit Langem.",es:"Fue la mejor decisión en mucho tiempo."}]},"Darf ich mich vorstellen? Mein Name ist …":{de:"Sehr angenehm. Sie sind der neue Kollege, nicht wahr?",es:"Mucho gusto. Usted es el compañero nuevo, ¿verdad?",mas:[{de:"Ich fange heute bei Ihnen an.",es:"Hoy empiezo con ustedes."},{de:"Herzlich willkommen! Ich zeige Ihnen gleich Ihren Platz.",es:"¡Bienvenido! Ahora le enseño su sitio."},{de:"Ich bin für die Buchhaltung zuständig.",es:"Yo me encargo de la contabilidad."},{de:"Dann arbeiten wir viel zusammen, das freut mich.",es:"Entonces trabajaremos mucho juntos, me alegro."},{de:"Darf ich Ihnen Frau Berger vorstellen?",es:"¿Me permite presentarle a la señora Berger?"},{de:"Guten Tag, Frau Berger. Sind Sie auch neu hier?",es:"Buenos días, señora Berger. ¿Usted también es nueva aquí?"},{de:"Wir sehen uns bei der Besprechung.",es:"Nos vemos en la reunión."},{de:"Bis gleich. Der Besprechungsraum ist im zweiten Stock.",es:"Hasta ahora. La sala de reuniones está en la segunda planta."}]},"Heute ist mein erster Arbeitstag hier.":{de:"Dann zeige ich Ihnen erst einmal alles in Ruhe.",es:"Entonces primero le enseño todo con calma.",mas:[{de:"Wer ist hier mein Ansprechpartner?",es:"¿Quién es aquí mi persona de contacto?"},{de:"Das ist Frau Wolf, unsere Abteilungsleiterin.",es:"Esta es la señora Wolf, la jefa de departamento."},{de:"Freut mich, Sie persönlich kennenzulernen.",es:"Me alegra conocerle en persona."},{de:"Ganz meinerseits. Wir haben ja schon oft telefoniert.",es:"Igualmente. Ya hemos hablado por teléfono muchas veces."},{de:"Das Projekt fällt in meine Zuständigkeit.",es:"El proyecto entra en mi ámbito."},{de:"Gut zu wissen. Dann schicke ich Ihnen alles direkt.",es:"Bueno saberlo. Entonces le mando todo directamente."},{de:"Wir sehen uns bei der Besprechung um zehn.",es:"Nos vemos en la reunión de las diez."},{de:"Ich bringe die Unterlagen mit, dann gehen wir alles durch.",es:"Llevo la documentación y lo repasamos todo."}]},"Entschuldigung, da bin ich nicht mitgekommen.":{de:"Kein Problem, ich sage es noch einmal langsamer.",es:"No pasa nada, lo digo otra vez más despacio.",mas:[{de:"Können Sie das bitte noch einmal erklären?",es:"¿Me lo puede explicar otra vez?"},{de:"Gern. Der Bericht geht erst an mich, dann an den Kunden.",es:"Con gusto. El informe va primero a mí y luego al cliente."},{de:"Habe ich das richtig verstanden: bis Freitag?",es:"¿Lo he entendido bien: hasta el viernes?"},{de:"Genau, Freitag Mittag, damit ich am Nachmittag prüfen kann.",es:"Exacto, el viernes al mediodía, para poder revisarlo por la tarde."},{de:"Was heißt das für meine Arbeit?",es:"¿Y eso qué significa para mi trabajo?"},{de:"Für Sie ändert sich nur der Abgabetag, sonst nichts.",es:"Para usted solo cambia el día de entrega, nada más."},{de:"Sprechen Sie bitte etwas lauter?",es:"¿Puede hablar un poco más alto?"},{de:"Natürlich, hier hinten hört man wirklich schlecht.",es:"Por supuesto, aquí atrás se oye muy mal."}]},"Darf ich noch einmal nachfragen?":{de:"Immer, lieber einmal zu viel als zu wenig.",es:"Siempre, mejor una vez de más que de menos.",mas:[{de:"Was bedeutet diese Abkürzung?",es:"¿Qué significa esta abreviatura?"},{de:"Das steht für unseren internen Wochenbericht.",es:"Eso es nuestro informe semanal interno."},{de:"Könnten Sie mir das an einem Beispiel zeigen?",es:"¿Me lo podría enseñar con un ejemplo?"},{de:"Gern, ich öffne den vom letzten Monat.",es:"Con gusto, abro el del mes pasado."},{de:"War das eine feste Absprache oder nur eine Idee?",es:"¿Eso era un acuerdo firme o solo una idea?"},{de:"Bisher nur eine Idee. Entschieden wird es am Montag.",es:"De momento solo una idea. Se decide el lunes."},{de:"Zu wem gehe ich, wenn ich nicht weiterweiß?",es:"¿A quién acudo si me atasco?"},{de:"Zu mir, und wenn ich nicht da bin, zu Frau Berger.",es:"A mí, y si no estoy, a la señora Berger."}]},"Wie läuft das hier normalerweise ab?":{de:"Montags planen wir, freitags berichten wir. Dazwischen arbeitet man.",es:"Los lunes planificamos, los viernes informamos. En medio se trabaja.",mas:[{de:"Wann ist der Abgabetermin für den Bericht?",es:"¿Cuándo es la fecha de entrega del informe?"},{de:"Immer am letzten Werktag des Monats.",es:"Siempre el último día laborable del mes."},{de:"Diese Aufgabe schaffe ich bis Mittwoch.",es:"Esta tarea la saco para el miércoles."},{de:"Sehr gut, dann haben wir sogar noch etwas Luft.",es:"Muy bien, así incluso nos sobra algo de margen."},{de:"Ich arbeite mich gerade noch ein.",es:"Todavía me estoy familiarizando con el trabajo."},{de:"Das ist normal, dafür sind die ersten Wochen da.",es:"Es normal, para eso están las primeras semanas."},{de:"Ich hätte gern ehrliches Feedback zu meiner Arbeit.",es:"Me gustaría un feedback sincero sobre mi trabajo."},{de:"Sehr gern. Setzen wir uns nächste Woche eine halbe Stunde hin.",es:"Con mucho gusto. Sentémonos media hora la semana que viene."}]},"Ich möchte mich auf die Stelle bewerben.":{de:"Schön. Erzählen Sie mir etwas über Ihren Werdegang.",es:"Bien. Cuénteme algo sobre su trayectoria.",mas:[{de:"Ich habe fünf Jahre Erfahrung in der Branche.",es:"Tengo cinco años de experiencia en el sector."},{de:"In welchem Bereich genau waren Sie tätig?",es:"¿En qué área exactamente ha trabajado?"},{de:"Mein Deutsch ist noch nicht perfekt.",es:"Mi alemán todavía no es perfecto."},{de:"Für diese Stelle reicht es völlig, machen Sie sich keine Sorgen.",es:"Para este puesto es más que suficiente, no se preocupe."},{de:"Wann könnten Sie bei uns anfangen?",es:"¿Cuándo podría empezar con nosotros?"},{de:"In vier Wochen, ich habe noch eine Kündigungsfrist.",es:"En cuatro semanas, tengo un preaviso pendiente."},{de:"Wann bekomme ich eine Rückmeldung?",es:"¿Cuándo tendré una respuesta?"},{de:"Bis Ende der Woche, so oder so. Vielen Dank für das Gespräch.",es:"A final de semana, en cualquier caso. Gracias por la entrevista."}]},"Welche Qualifikationen erwarten Sie?":{de:"Eine abgeschlossene Ausbildung und gutes Deutsch, mehr nicht.",es:"Una formación acabada y buen alemán, nada más.",mas:[{de:"Wie sind die Arbeitszeiten geregelt?",es:"¿Cómo está regulado el horario?"},{de:"Gleitzeit, mit Kernzeit von neun bis fünfzehn Uhr.",es:"Horario flexible, con franja central de nueve a quince."},{de:"Gibt es eine Probezeit?",es:"¿Hay periodo de prueba?"},{de:"Ein Monat, wie überall bei uns in der Branche.",es:"Un mes, como en todo el sector aquí."},{de:"Zahlt der Arbeitgeber auch Fortbildungen?",es:"¿El empleador paga también formación?"},{de:"Ja, einmal im Jahr, und die Zeit gilt als Arbeitszeit.",es:"Sí, una vez al año, y el tiempo cuenta como jornada."},{de:"Wie ist das Betriebsklima bei Ihnen?",es:"¿Cómo es el ambiente laboral con ustedes?"},{de:"Ruhig und ehrlich. Wir sagen einander, was nicht passt.",es:"Tranquilo y sincero. Nos decimos lo que no funciona."}]},"Können wir kurz unter vier Augen sprechen?":{de:"Natürlich, kommen Sie in mein Büro.",es:"Por supuesto, venga a mi despacho.",mas:[{de:"Ich habe einen Fehler gemacht, es tut mir leid.",es:"He cometido un error, lo siento."},{de:"Danke, dass Sie es gleich sagen. Was ist passiert?",es:"Gracias por decirlo enseguida. ¿Qué ha pasado?"},{de:"Ich schaffe die Arbeit in der Zeit nicht.",es:"No saco el trabajo en ese tiempo."},{de:"Dann schauen wir zusammen, was warten kann.",es:"Entonces miramos juntos qué puede esperar."},{de:"Ich mache seit Wochen zu viele Überstunden.",es:"Llevo semanas haciendo demasiadas horas extra."},{de:"Das ist mir auch aufgefallen. Das ändern wir ab Montag.",es:"También me he dado cuenta. Eso lo cambiamos desde el lunes."},{de:"Könnten wir meinen Vertrag besprechen?",es:"¿Podríamos hablar de mi contrato?"},{de:"Gern, machen wir einen Termin für nächste Woche aus.",es:"Con gusto, fijamos una cita para la semana que viene."}]},"Wann ist der nächste Elternsprechtag?":{de:"Am zwölften November, von vierzehn bis achtzehn Uhr.",es:"El doce de noviembre, de catorce a dieciocho.",mas:[{de:"Wie kommt mein Kind in der Klasse zurecht?",es:"¿Cómo se desenvuelve mi hijo en clase?"},{de:"Gut. Er ist ruhig, aber er beteiligt sich immer öfter.",es:"Bien. Es tranquilo, pero participa cada vez más."},{de:"Mein Sohn war gestern krank.",es:"Mi hijo estuvo ayer enfermo."},{de:"Kein Problem, schreiben Sie mir eine kurze Entschuldigung.",es:"No hay problema, escríbame un justificante breve."},{de:"Wann bekommen die Kinder das Zeugnis?",es:"¿Cuándo reciben los niños las notas?"},{de:"Am letzten Schultag vor den Ferien, wie jedes Jahr.",es:"El último día antes de las vacaciones, como cada año."},{de:"Bekommen die Kinder Aufgaben für die Ferien?",es:"¿Les mandan tareas para las vacaciones?"},{de:"Nur Lesen, und das ganz freiwillig. Ferien sind Ferien.",es:"Solo leer, y totalmente voluntario. Vacaciones son vacaciones."}]},"Welche Schulbücher müssen wir kaufen?":{de:"Fast keine, die Bücher stellt die Schule. Nur die Hefte.",es:"Casi ninguno, los libros los pone el colegio. Solo los cuadernos.",mas:[{de:"Gibt es an dieser Schule Schulgeld?",es:"¿En este colegio hay que pagar tasas?"},{de:"Nein, die Schule ist frei. Nur Ausflüge kosten extra.",es:"No, el colegio es gratuito. Solo las excursiones se pagan aparte."},{de:"Was kostet die Klassenfahrt insgesamt?",es:"¿Cuánto cuesta en total el viaje de clase?"},{de:"Hundertachtzig Euro. Bei Bedarf gibt es eine Unterstützung.",es:"Ciento ochenta euros. Si hace falta, hay una ayuda."},{de:"Wie viel kostet die Nachmittagsbetreuung?",es:"¿Cuánto cuesta la atención de tarde?"},{de:"Das hängt vom Einkommen ab, zwischen null und neunzig Euro.",es:"Depende de los ingresos, entre cero y noventa euros."},{de:"Darf mein Kind allein nach Hause gehen?",es:"¿Puede mi hijo irse solo a casa?"},{de:"Mit Ihrer schriftlichen Erlaubnis ja, ab der dritten Klasse.",es:"Con su permiso por escrito sí, a partir de tercero."}]},"Mein Kind hat Schwierigkeiten mit der Sprache.":{de:"Das sehe ich auch, vor allem beim Schreiben.",es:"También lo veo yo, sobre todo al escribir.",mas:[{de:"Er kann sich in der Klasse schlecht konzentrieren.",es:"En clase le cuesta concentrarse."},{de:"Ich setze ihn ab Montag weiter nach vorne, das hilft oft.",es:"Desde el lunes lo siento más delante, eso suele ayudar."},{de:"Braucht mein Kind Nachhilfe?",es:"¿Mi hijo necesita clases particulares?"},{de:"Noch nicht. Probieren wir erst die Förderstunde am Donnerstag.",es:"Todavía no. Probemos primero el refuerzo del jueves."},{de:"Gibt es Probleme mit den Mitschülern?",es:"¿Hay problemas con los compañeros?"},{de:"Überhaupt nicht, er ist in der Klasse sehr beliebt.",es:"En absoluto, es muy querido en clase."},{de:"Er ist begabt, aber ziemlich faul.",es:"Es listo, pero bastante vago."},{de:"Das sagen viele Eltern. Meistens fehlt nur das Interesse.",es:"Eso lo dicen muchos padres. Casi siempre solo falta el interés."}]},"Was können wir zu Hause üben?":{de:"Lesen Sie jeden Tag zehn Minuten gemeinsam laut.",es:"Lean juntos en voz alta diez minutos al día.",mas:[{de:"Er tut sich mit den Artikeln sehr schwer.",es:"Le cuestan mucho los artículos."},{de:"Da hilft nur Wiederholung, und immer das ganze Wort mit Artikel.",es:"Ahí solo ayuda repetir, y siempre la palabra entera con artículo."},{de:"Wir üben zu Hause jeden Tag ein bisschen.",es:"En casa practicamos un poco cada día."},{de:"Das merkt man deutlich, seine Texte sind viel besser geworden.",es:"Se nota claramente, sus textos han mejorado mucho."},{de:"Was können wir für sein Selbstvertrauen tun?",es:"¿Qué podemos hacer por su autoconfianza?"},{de:"Loben Sie das Bemühen, nicht nur die Note.",es:"Elogien el esfuerzo, no solo la nota."},{de:"Hilft Loben bei ihm mehr als Schimpfen?",es:"¿Con él funciona mejor elogiar que regañar?"},{de:"Bei ihm ganz sicher. Schimpfen macht ihn nur still.",es:"Con él seguro. Regañarle solo le hace callar."}]},"Könnten Sie bitte etwas langsamer sprechen?":{de:"Natürlich, entschuldigen Sie. Ich rede oft zu schnell.",es:"Por supuesto, perdone. Suelo hablar muy rápido.",mas:[{de:"Ich brauche manchmal etwas länger zum Verstehen.",es:"A veces necesito un poco más de tiempo para entender."},{de:"Das ist völlig in Ordnung, wir haben genug Zeit.",es:"Está perfectamente bien, tenemos tiempo de sobra."},{de:"Sagen Sie es bitte mit einfachen Worten.",es:"Dígamelo con palabras sencillas, por favor."},{de:"Gern: Ihr Sohn lernt gut, er braucht nur mehr Übung im Schreiben.",es:"Con gusto: su hijo aprende bien, solo necesita practicar más la escritura."},{de:"Ist das so richtig, wie ich es sage?",es:"¿Está bien dicho así?"},{de:"Ganz richtig, und man versteht Sie sehr gut.",es:"Totalmente correcto, y se le entiende muy bien."},{de:"Gibt es das auch auf Spanisch?",es:"¿Está también en español?"},{de:"Das Infoblatt ja, ich drucke es Ihnen gleich aus.",es:"La hoja informativa sí, se la imprimo ahora."}]},"Kommt Ihr Sohn nächstes Jahr ins Gymnasium?":{de:"Ich bin mir nicht sicher.",es:"No estoy seguro.",mas:[{de:"Was sagt er selbst dazu?",es:"¿Y él qué dice?"},{de:"Ich denke ja, sicher bin ich mir aber nicht.",es:"Creo que sí, aunque no estoy seguro."},{de:"Und die Lehrerin, was empfiehlt sie?",es:"¿Y la profesora, qué recomienda?"},{de:"Das kann ich leider nicht sagen, wir sprechen erst morgen.",es:"Eso no se lo puedo decir, hablamos mañana."},{de:"Würde Nachhilfe etwas bringen?",es:"¿Servirían de algo las clases particulares?"},{de:"Ich weiß nicht, ob Nachhilfe wirklich hilft.",es:"No sé si las clases particulares ayudan de verdad."},{de:"Und was ist mit der Schule im Nachbarbezirk?",es:"¿Y qué hay del colegio del distrito de al lado?"},{de:"Ich müsste das erst nachlesen, davon weiß ich nichts.",es:"Tendría que consultarlo antes, de eso no sé nada."}]},"Sollen wir am Dienstag oder am Donnerstag reden?":{de:"Mir ist beides recht.",es:"Me vale cualquiera de las dos.",mas:[{de:"Lieber vormittags oder nachmittags?",es:"¿Mejor por la mañana o por la tarde?"},{de:"Das ist mir ehrlich gesagt egal.",es:"Sinceramente, me da igual."},{de:"Und soll die Lehrerin dabei sein?",es:"¿Y debería estar la profesora?"},{de:"Von mir aus gern, aber es muss nicht sein.",es:"Por mí bien, pero no hace falta."},{de:"Reden wir zuerst über Mathe oder über Deutsch?",es:"¿Hablamos primero de mates o de alemán?"},{de:"Ob Mathe oder Deutsch, ist mir gleich.",es:"Sea mates o alemán, me da igual."},{de:"Gut, dann entscheide ich einfach.",es:"Bien, entonces decido yo."},{de:"Mach einfach, wie du willst. Hauptsache, wir reden.",es:"Haz simplemente lo que quieras. Lo importante es que hablemos."}]},"Ich verstehe das Schulsystem hier noch nicht ganz.":{de:"Das geht vielen so. Fragen Sie mich jederzeit.",es:"A muchos les pasa. Pregúnteme cuando quiera.",mas:[{de:"Können Sie mir den Lernstoff kurz zusammenfassen?",es:"¿Me puede resumir brevemente la materia?"},{de:"Gern, und ich schreibe Ihnen die Punkte auf ein Blatt.",es:"Con gusto, y le apunto los puntos en una hoja."},{de:"Dann probieren wir es bis zum Semesterende so.",es:"Entonces lo probamos así hasta final de semestre."},{de:"Einverstanden. Danach schauen wir, ob es gewirkt hat.",es:"De acuerdo. Después vemos si ha funcionado."},{de:"Sagen Sie mir Bescheid, wenn sich etwas ändert.",es:"Avíseme si algo cambia."},{de:"Das mache ich sofort, auch wenn es Gutes ist.",es:"Lo haré enseguida, también si es algo bueno."},{de:"Ich denke, wir haben alles besprochen.",es:"Creo que lo hemos hablado todo."},{de:"Das finde ich auch. Schönen Tag noch und auf Wiedersehen.",es:"Yo también lo creo. Que pase buen día y hasta la vista."}]},"Was machst du nach der Arbeit meistens?":{de:"Ich brauche nach der Arbeit erst einmal Ruhe.",es:"Después del trabajo necesito primero tranquilidad.",mas:[{de:"Wie schaltest du nach einem harten Tag ab?",es:"¿Cómo desconectas después de un día duro?"},{de:"Ein langer Spaziergang, ohne Handy. Das wirkt besser als alles andere.",es:"Un paseo largo, sin móvil. Funciona mejor que nada."},{de:"Schaffst du es, abends wirklich abzuschalten?",es:"¿Consigues desconectar de verdad por la noche?"},{de:"Seit ich das Handy aus dem Schlafzimmer verbannt habe, ja.",es:"Desde que desterré el móvil del dormitorio, sí."},{de:"Gehst du unter der Woche aus?",es:"¿Sales entre semana?"},{de:"Am Freitag bleibe ich prinzipiell zu Hause.",es:"Los viernes por principio me quedo en casa."},{de:"Nach der Spätschicht bin ich zu nichts zu gebrauchen.",es:"Después del turno de tarde no sirvo para nada."},{de:"Das kenne ich. Da hilft nur schlafen und morgen weitersehen.",es:"Lo conozco. Ahí solo ayuda dormir y ya se verá mañana."}]},"Jetzt komm mit, das wird sicher lustig!":{de:"Ich weiß nicht, ich bin ziemlich müde.",es:"No sé, estoy bastante cansado.",mas:[{de:"Es dauert doch nur eine halbe Stunde.",es:"Si solo dura media hora."},{de:"Eine halbe Stunde? Das sagst du jedes Mal.",es:"¿Media hora? Eso lo dices siempre."},{de:"Alle anderen kommen auch mit.",es:"Todos los demás también vienen."},{de:"Das ist kein Argument, das weißt du.",es:"Eso no es un argumento, lo sabes."},{de:"Probier es wenigstens einmal.",es:"Pruébalo al menos una vez."},{de:"Na gut, aber nur eine Stunde, dann gehe ich heim.",es:"Está bien, pero solo una hora, luego me voy a casa."},{de:"Du bereust es sicher nicht.",es:"Seguro que no te arrepientes."},{de:"Das hoffe ich für dich, sonst schuldest du mir was.",es:"Eso espero por ti, si no me debes una."}]},"Ich verspreche dir, morgen stehe ich früh auf.":{de:"Das hast du letzte Woche auch gesagt.",es:"Eso también lo dijiste la semana pasada.",mas:[{de:"Ich halte immer, was ich verspreche.",es:"Siempre cumplo lo que prometo."},{de:"Meistens schon, das muss ich zugeben.",es:"Casi siempre sí, lo tengo que reconocer."},{de:"Ich mache es heute Abend, ganz sicher.",es:"Lo hago esta noche, seguro."},{de:"Gut. Dann erinnere ich dich um acht daran.",es:"Bien. Entonces te lo recuerdo a las ocho."},{de:"Ab morgen reduziere ich meine Bildschirmzeit.",es:"A partir de mañana reduzco mi tiempo de pantalla."},{de:"Sehr gute Idee. Fang mit dem Abend an, das ist am leichtesten.",es:"Muy buena idea. Empieza por la noche, es lo más fácil."},{de:"Darauf kannst du dich hundertprozentig verlassen.",es:"Puedes contar con ello al cien por cien."},{de:"Dann glaube ich dir. Du hast mich noch nie enttäuscht.",es:"Entonces te creo. Nunca me has decepcionado."}]},"Ich schaue nur eine Folge, versprochen.":{de:"Ist das ein Versprechen?",es:"¿Eso es una promesa?",mas:[{de:"Versprochen? – Versprochen!",es:"¿Prometido? – ¡Prometido!"},{de:"Gut, dann glaube ich dir dieses eine Mal.",es:"Bien, entonces te creo esta vez."},{de:"Ich kümmere mich morgen darum, versprochen.",es:"Me ocupo mañana, te lo prometo."},{de:"Verlass dich drauf, das vergesse ich nicht.",es:"Cuenta con ello, no se me olvida."},{de:"Komm schon, einmal offline schadet dir nicht.",es:"Venga, un rato sin conexión no te hace daño."},{de:"Da hast du wahrscheinlich recht. Ich lege es weg.",es:"Probablemente tengas razón. Lo dejo."},{de:"Hör dir den Podcast an, nur eine Folge.",es:"Escucha el pódcast, solo un episodio."},{de:"Abgemacht, aber dann schaust du mit mir die Serie.",es:"Trato hecho, pero luego ves la serie conmigo."}]},"Meiner Meinung nach ist die Serie überbewertet.":{de:"Wirklich? Alle reden doch davon.",es:"¿De verdad? Si todo el mundo habla de ella.",mas:[{de:"Ich finde, dass zu viel Werbung läuft.",es:"Me parece que hay demasiada publicidad."},{de:"Da stimme ich dir zu, das nervt wirklich.",es:"En eso te doy la razón, es muy molesto."},{de:"Der Hauptdarsteller spielt hervorragend.",es:"El protagonista actúa de maravilla."},{de:"Das ist das Einzige, was die Serie rettet.",es:"Es lo único que salva la serie."},{de:"Diese Schlagzeile finde ich übertrieben.",es:"Ese titular me parece exagerado."},{de:"Ich auch. Im Text steht dann etwas ganz anderes.",es:"Yo también. En el texto luego pone otra cosa."},{de:"Ich bin der Meinung, dass man weniger Handy nutzen sollte.",es:"Opino que se debería usar menos el móvil."},{de:"Sagt der, der gerade zweimal aufs Display geschaut hat.",es:"Dice el que acaba de mirar la pantalla dos veces."}]},"Was hältst du von dem Interview?":{de:"Sie sagt, der Bericht sei völlig neutral.",es:"Ella dice que el informe es totalmente neutral.",mas:[{de:"Und was sagen deine Kollegen dazu?",es:"¿Y qué dicen tus compañeros de eso?"},{de:"Er meint, Dokus seien ihm lieber als solche Interviews.",es:"Él dice que prefiere los documentales a esas entrevistas."},{de:"Sie meint, das Ende war unlogisch.",es:"Ella opina que el final no tenía lógica."},{de:"Das habe ich auch gedacht, aber sie erklärt es besser.",es:"Yo también lo pensé, pero ella lo explica mejor."},{de:"Sie behauptet, das sei längst entschieden.",es:"Ella afirma que eso está decidido hace tiempo."},{de:"Dann hätte man uns wenigstens informieren können.",es:"Entonces al menos podrían habernos informado."},{de:"Wie stehst du zu dem Thema?",es:"¿Qué postura tienes sobre el tema?"},{de:"Meiner Meinung nach ist das der falsche Weg.",es:"En mi opinión ese es el camino equivocado."}]},"Welche Serie schaust du im Moment?":{de:"Eine spanische, mit Untertiteln. Gut fürs Hörverstehen.",es:"Una española, con subtítulos. Buena para la comprensión oral.",mas:[{de:"Wie findest du die Serie?",es:"¿Qué te parece la serie?"},{de:"Die erste Staffel war stark, danach wird sie schwächer.",es:"La primera temporada era fuerte, luego flojea."},{de:"Siehst du viel fern?",es:"¿Ves mucho la tele?"},{de:"Ich schaue kaum fern, aber ich höre viele Podcasts.",es:"Casi no veo la tele, pero escucho muchos pódcast."},{de:"Hörst du Podcasts?",es:"¿Escuchas pódcasts?"},{de:"Jeden Morgen in der Straßenbahn, meistens auf Deutsch.",es:"Cada mañana en el tranvía, casi siempre en alemán."},{de:"Am Abend lese ich lieber.",es:"Por la tarde prefiero leer."},{de:"Das sollte ich auch wieder anfangen. Bildschirme machen mich müde.",es:"Yo también debería retomarlo. Las pantallas me cansan."}]},"Wo informierst du dich über Nachrichten?":{de:"Morgens im Radio, abends kurz online. Mehr brauche ich nicht.",es:"Por la mañana en la radio, por la noche un rato en internet. No necesito más.",mas:[{de:"Wie hoch ist deine Bildschirmzeit pro Tag?",es:"¿Cuál es tu tiempo de pantalla al día?"},{de:"Fünf Stunden. Als ich das gesehen habe, bin ich erschrocken.",es:"Cinco horas. Cuando lo vi, me asusté."},{de:"Bist du in sozialen Medien aktiv?",es:"¿Eres activo en redes sociales?"},{de:"Ich lese mit, aber ich schreibe fast nie etwas.",es:"Leo, pero casi nunca escribo nada."},{de:"Hast du das Abo eigentlich gekündigt?",es:"¿Al final cancelaste la suscripción?"},{de:"Noch nicht, aber diese Woche mache ich es wirklich.",es:"Todavía no, pero esta semana lo hago de verdad."},{de:"Schaltest du am Abend wirklich ab?",es:"¿De verdad desconectas por la noche?"},{de:"Ab neun ist das Handy im Flur. Das hat mein Schlafen gerettet.",es:"A partir de las nueve el móvil está en el pasillo. Eso me salvó el sueño."}]},"Kannst du mir am Samstag beim Umzug helfen?":{de:"Klar, ab wann braucht ihr mich?",es:"Claro, ¿desde qué hora me necesitáis?",mas:[{de:"Hast du den Umzugswagen schon reserviert?",es:"¿Ya has reservado la furgoneta?"},{de:"Ja, von acht bis achtzehn Uhr. Danach wird es teuer.",es:"Sí, de ocho a dieciocho. Después sale caro."},{de:"In welche Kiste kommen die Gläser?",es:"¿En qué caja van los vasos?"},{de:"In die kleinen, und bitte viel Papier dazwischen.",es:"En las pequeñas, y con mucho papel entre medias."},{de:"Die Übergabe der alten Wohnung ist am Montag.",es:"La entrega del piso viejo es el lunes."},{de:"Dann müssen wir Sonntag unbedingt noch putzen.",es:"Entonces el domingo hay que limpiar sin falta."},{de:"Danke, dass ihr alle gekommen seid!",es:"¡Gracias por venir todos!"},{de:"Dafür sind Freunde da. Und für die Pizza nachher.",es:"Para eso están los amigos. Y para la pizza de después."}]},"Fangen wir mit der Küche an?":{de:"Lieber nicht, die dauert am längsten. Erst das Schlafzimmer.",es:"Mejor no, es la que más tarda. Primero el dormitorio.",mas:[{de:"Lass uns die Kisten gleich beschriften.",es:"Vamos a rotular las cajas ahora mismo."},{de:"Unbedingt, sonst suchen wir nachher stundenlang.",es:"Sin falta, si no luego buscamos durante horas."},{de:"Sollen wir zuerst die schweren Sachen tragen?",es:"¿Llevamos primero las cosas pesadas?"},{de:"Ja, solange wir noch Kraft haben. Das ist klüger.",es:"Sí, mientras tengamos fuerzas. Es más listo."},{de:"Wir könnten die alten Möbel verschenken.",es:"Podríamos regalar los muebles viejos."},{de:"Gute Idee, ich stelle sie heute Abend online.",es:"Buena idea, los pongo esta noche en internet."},{de:"Was hältst du davon, morgen weiterzumachen?",es:"¿Qué te parece seguir mañana?"},{de:"Sehr gern, ich kann nicht mehr. Für heute reicht es.",es:"Con mucho gusto, ya no puedo más. Por hoy basta."}]},"Stellen wir das Sofa erst mal quer in den Raum?":{de:"Hmm, ich weiß nicht so recht.",es:"Mmm, no lo tengo claro.",mas:[{de:"Nur bis wir den Teppich haben.",es:"Solo hasta que tengamos la alfombra."},{de:"Na gut, dann eben provisorisch.",es:"Bueno, pues provisionalmente."},{de:"Und den alten Schrank stellen wir in den Keller?",es:"¿Y el armario viejo lo ponemos en el sótano?"},{de:"Ehrlich gesagt wäre mir das nicht recht.",es:"Sinceramente, eso no me convencería."},{de:"Dann verkaufen wir ihn einfach.",es:"Entonces lo vendemos y ya está."},{de:"Einverstanden, aber nur unter einer Bedingung.",es:"De acuerdo, pero con una condición."},{de:"Und die wäre?",es:"¿Y cuál es?"},{de:"Du machst die Fotos und die Anzeige, nicht ich.",es:"Tú haces las fotos y el anuncio, no yo."}]},"Kannst du dich um den Wagen kümmern?":{de:"Klar, das mache ich gern.",es:"Claro, lo hago con gusto.",mas:[{de:"Und die Werkzeuge? Wir brauchen einen Akkuschrauber.",es:"¿Y las herramientas? Necesitamos un atornillador."},{de:"Kein Problem, ich bringe das Werkzeug mit.",es:"No hay problema, yo llevo las herramientas."},{de:"Wer meldet die Adresse um?",es:"¿Quién cambia la dirección?"},{de:"Ich kümmere mich um den Nachsendeauftrag.",es:"Yo me ocupo del reenvío postal."},{de:"Und der ganze Karton- und Papiermüll?",es:"¿Y todo el cartón y el papel?"},{de:"Ich kümmere mich um den Müll, das ist schnell gemacht.",es:"Yo me ocupo de la basura, eso se hace rápido."},{de:"Schaffst du das alles bis Freitag?",es:"¿Sacas todo eso para el viernes?"},{de:"Das kriege ich hin, keine Sorge.",es:"Eso lo saco, no te preocupes."}]},"Vorsicht, die Kiste ist sehr schwer!":{de:"Oje, was ist da drin? Steine?",es:"Vaya, ¿qué lleva dentro? ¿Piedras?",mas:[{de:"Langsam, hier ist eine Stufe.",es:"Despacio, aquí hay un escalón."},{de:"Danke, die hätte ich glatt übersehen.",es:"Gracias, no la habría visto."},{de:"Vorsicht, diese Kiste ist zerbrechlich!",es:"¡Cuidado, esta caja es frágil!"},{de:"Dann trage ich sie lieber allein und langsam.",es:"Entonces mejor la llevo solo y despacio."},{de:"Halt die Leiter fest, bitte.",es:"Sujeta bien la escalera, por favor."},{de:"Ich halte sie, klettere du ruhig ganz nach oben.",es:"La sujeto, sube tranquilo hasta arriba."},{de:"Achte bitte auf die frische Farbe.",es:"Ten cuidado con la pintura fresca."},{de:"Zu spät, ich habe schon den Ärmel voll.",es:"Demasiado tarde, ya tengo la manga llena."}]},"Das Sofa kommt an die Wand beim Fenster.":{de:"Da ist es aber im Winter ziemlich zugig.",es:"Pero ahí en invierno hay bastante corriente.",mas:[{de:"Der Tisch soll in die Mitte.",es:"La mesa va en el centro."},{de:"Einverstanden, dann haben alle gleich viel Platz.",es:"De acuerdo, así todos tienen el mismo sitio."},{de:"Stell das Regal bitte neben die Tür.",es:"Pon la estantería al lado de la puerta."},{de:"Neben der Tür steht es gut, da stört es niemanden.",es:"Al lado de la puerta queda bien, ahí no molesta."},{de:"Wohin hängen wir den Spiegel?",es:"¿Dónde colgamos el espejo?"},{de:"In den Flur, gegenüber der Tür. Da wirkt alles größer.",es:"En el pasillo, frente a la puerta. Ahí todo parece más grande."},{de:"Die Vorhänge machen den Raum gemütlich.",es:"Las cortinas hacen la habitación acogedora."},{de:"Und sie schlucken den Lärm von der Straße.",es:"Y absorben el ruido de la calle."}]},"Entscheidend ist, dass die Kinder ein Zimmer haben.":{de:"Da bin ich ganz bei dir, alles andere kommt danach.",es:"En eso estoy contigo, lo demás viene después.",mas:[{de:"Das Wichtigste ist, dass nichts kaputtgeht.",es:"Lo más importante es que no se rompa nada."},{de:"Deshalb tragen wir das Geschirr auch selbst.",es:"Por eso la vajilla la llevamos nosotros."},{de:"Wichtiger als die Farbe ist das Licht.",es:"Más importante que el color es la luz."},{de:"Stimmt. In diesem Zimmer wird man automatisch gut gelaunt.",es:"Es verdad. En esta habitación uno se pone de buen humor solo."},{de:"Das kann warten, es eilt nicht.",es:"Eso puede esperar, no corre prisa."},{de:"Gut, dann lassen wir den Keller bis nächsten Monat.",es:"Bien, entonces dejamos el sótano para el mes que viene."},{de:"Hauptsache, es ist bis Freitag fertig.",es:"Lo importante es que esté listo el viernes."},{de:"Das schaffen wir, wenn morgen noch zwei Leute kommen.",es:"Lo conseguimos si mañana vienen dos personas más."}]},"Nimmst du bitte das andere Ende?":{de:"Habe ich. Auf drei heben wir zusammen.",es:"Ya lo tengo. A la de tres levantamos juntos.",mas:[{de:"Passt das Bett überhaupt an diese Wand?",es:"¿Cabe la cama en esa pared?"},{de:"Knapp. Wir müssen den Nachttisch woanders hinstellen.",es:"Justo. Tenemos que poner la mesilla en otro sitio."},{de:"Soll der Schreibtisch ans Fenster?",es:"¿Ponemos el escritorio junto a la ventana?"},{de:"Unbedingt, mit Tageslicht arbeitet es sich viel besser.",es:"Sin falta, con luz natural se trabaja mucho mejor."},{de:"Wie wollen wir die Küche einräumen?",es:"¿Cómo colocamos la cocina?"},{de:"Alles, was man täglich braucht, nach unten und vorne.",es:"Todo lo de uso diario, abajo y delante."},{de:"Wer macht die Endreinigung der alten Wohnung?",es:"¿Quién hace la limpieza final del piso viejo?"},{de:"Diese Lösung finde ich sehr praktisch: wir teilen sie uns.",es:"Esta solución me parece muy práctica: nos la repartimos."}]},"Wann fährt der nächste Zug nach Salzburg?":{de:"In zwanzig Minuten, um vierzehn Uhr zehn.",es:"En veinte minutos, a las catorce diez.",mas:[{de:"Muss ich umsteigen? – Ja, in Linz.",es:"¿Tengo que hacer transbordo? – Sí, en Linz."},{de:"In Linz haben Sie acht Minuten, das reicht gut.",es:"En Linz tiene ocho minutos, es suficiente."},{de:"Von welchem Gleis fährt der Zug ab?",es:"¿Por qué vía sale el tren?"},{de:"Gleis sieben, unten durch die Unterführung.",es:"Vía siete, abajo por el paso subterráneo."},{de:"Wie lange dauert die Fahrt ungefähr?",es:"¿Cuánto dura el viaje más o menos?"},{de:"Knapp drei Stunden, mit dem Umstieg etwas mehr.",es:"Casi tres horas, con el transbordo algo más."},{de:"Was kostet eine Rückfahrkarte?",es:"¿Cuánto cuesta un billete de ida y vuelta?"},{de:"Achtundfünfzig Euro, mit Vorteilscard nur die Hälfte.",es:"Cincuenta y ocho euros; con tarjeta de descuento, la mitad."}]},"Was stand gerade in der Durchsage?":{de:"Zwanzig Minuten Verspätung, wegen eines Signals.",es:"Veinte minutos de retraso, por una señal.",mas:[{de:"Muss ich für diese Strecke umsteigen?",es:"¿Tengo que hacer transbordo en este trayecto?"},{de:"Normalerweise nicht, heute aber schon, in Attnang.",es:"Normalmente no, pero hoy sí, en Attnang."},{de:"Ist die Ankunftszeit realistisch?",es:"¿La hora de llegada es realista?"},{de:"Ehrlich gesagt nein. Rechnen Sie mit einer halben Stunde mehr.",es:"Sinceramente no. Cuente con media hora más."},{de:"Bekomme ich bei Verspätung eine Entschädigung?",es:"¿Con retraso recibo una indemnización?"},{de:"Ab einer Stunde ja, das Formular gibt es online.",es:"A partir de una hora sí, el formulario está en internet."},{de:"Wann geht der letzte Zug zurück?",es:"¿Cuándo sale el último tren de vuelta?"},{de:"Um dreiundzwanzig Uhr zwölf. Verpassen Sie ihn besser nicht.",es:"A las veintitrés doce. Mejor no lo pierda."}]},"Könnten Sie mir bitte mit dem Koffer helfen?":{de:"Natürlich, ich hebe ihn Ihnen ins Gepäckfach.",es:"Por supuesto, se la subo al portaequipajes.",mas:[{de:"Dürfte ich kurz vorbei?",es:"¿Me permite pasar un momento?"},{de:"Bitte sehr, ich stelle die Tasche kurz zur Seite.",es:"Adelante, aparto la bolsa un momento."},{de:"Würden Sie so nett sein und kurz aufpassen?",es:"¿Sería tan amable de vigilar un momento?"},{de:"Gern, gehen Sie ruhig, ich passe auf Ihre Sachen auf.",es:"Con gusto, vaya tranquilo, vigilo sus cosas."},{de:"Wären Sie so freundlich, das Fenster zu schließen?",es:"¿Sería tan amable de cerrar la ventana?"},{de:"Sofort, es zieht hier wirklich unangenehm.",es:"Enseguida, aquí hay una corriente desagradable."},{de:"Könnten Sie im Ruhebereich bitte leiser sprechen?",es:"¿Podría hablar más bajo en la zona de silencio?"},{de:"Entschuldigung, das hatte ich gar nicht bemerkt.",es:"Perdone, no me había dado cuenta."}]},"Wären Sie so freundlich, mir zu helfen?":{de:"Aber gern! · Kein Problem.",es:"¡Con mucho gusto! · Sin problema.",mas:[{de:"Könnten Sie das bitte kurz halten?",es:"¿Me lo podría sujetar un momento?"},{de:"Kein Problem, ich helfe Ihnen gern.",es:"No hay problema, le ayudo con mucho gusto."},{de:"Dürfte ich Sie kurz stören?",es:"¿Le importaría que le interrumpa un momento?"},{de:"Sie stören überhaupt nicht, fragen Sie ruhig.",es:"No molesta en absoluto, pregunte tranquilo."},{de:"Soll ich Sie ein Stück begleiten?",es:"¿Le acompaño un trecho?"},{de:"Vielen Dank, das ist sehr freundlich.",es:"Muchas gracias, es usted muy amable."},{de:"Ich schicke Ihnen eine Wegbeschreibung aufs Handy.",es:"Le mando las indicaciones al móvil."},{de:"Sie können den Weg gar nicht verfehlen, immer am Fluss entlang.",es:"No se puede perder, siempre junto al río."}]},"Entschuldigung, ist der Platz noch frei?":{de:"Ja, bitte sehr. / Nein, der ist leider besetzt.",es:"Sí, adelante. / No, lo siento, está ocupado.",mas:[{de:"Ist dieser Platz reserviert?",es:"¿Está reservado este asiento?"},{de:"Ab Linz schon, bis dahin können Sie gern sitzen.",es:"A partir de Linz sí; hasta entonces puede sentarse."},{de:"Sitzt hier schon jemand?",es:"¿Hay alguien sentado aquí?"},{de:"Nein, die Jacke gehört mir, ich nehme sie weg.",es:"No, la chaqueta es mía, la quito."},{de:"Könnten wir tauschen? Ich sitze gern am Fenster.",es:"¿Podríamos cambiar? Me gusta ir en la ventanilla."},{de:"Sehr gern, mir ist der Gang sowieso lieber.",es:"Con mucho gusto, yo prefiero el pasillo."},{de:"Sind hier im Ruhebereich noch Plätze frei?",es:"¿Quedan sitios libres aquí en la zona de silencio?"},{de:"Zwei ganz hinten, dort ist es am ruhigsten.",es:"Dos al fondo, ahí es donde más tranquilo está."}]},"Gute Reise! · Gute Fahrt!":{de:"Danke! In drei Stunden bin ich da.",es:"¡Gracias! En tres horas estoy allí.",mas:[{de:"Kommen Sie gut an!",es:"¡Que llegue bien!"},{de:"Das hoffe ich, bei dem Wetter ist alles möglich.",es:"Eso espero, con este tiempo todo es posible."},{de:"Schönen Aufenthalt in Wien!",es:"¡Que tenga una buena estancia en Viena!"},{de:"Vielen Dank, ich freue mich schon sehr darauf.",es:"Muchas gracias, tengo muchas ganas."},{de:"Erhol dich gut im Urlaub!",es:"¡Descansa bien en las vacaciones!"},{de:"Das habe ich fest vor. Zwei Wochen ohne Wecker.",es:"Esa es mi intención. Dos semanas sin despertador."},{de:"Ich wünsche Ihnen einen angenehmen Flug.",es:"Le deseo un vuelo agradable."},{de:"Danke, und Ihnen einen ruhigen Tag hier am Schalter.",es:"Gracias, y a usted un día tranquilo en el mostrador."}]},"Komme ich zu Fuß zur Innenstadt?":{de:"Ohne Problem, es sind ungefähr zehn Minuten zu Fuß.",es:"Sin problema, son unos diez minutos a pie.",mas:[{de:"Gehen Sie geradeaus bis zur Brücke, dann links.",es:"Vaya recto hasta el puente y luego a la izquierda."},{de:"Und dann bin ich schon am Hauptplatz?",es:"¿Y entonces ya estoy en la plaza mayor?"},{de:"An der zweiten Ampel rechts abbiegen.",es:"En el segundo semáforo gire a la derecha."},{de:"Die zweite, nicht die erste. Ich merke es mir.",es:"El segundo, no el primero. Lo apunto."},{de:"Nehmen Sie die Fußgängerzone, das ist kürzer.",es:"Coja la zona peatonal, es más corto."},{de:"Gut, dann sehe ich unterwegs auch gleich die Altstadt.",es:"Bien, así de paso veo el casco antiguo."},{de:"Wie lang ist der Fußweg zum Hotel?",es:"¿Cuánto es el camino a pie al hotel?"},{de:"Das ist gleich um die Ecke, keine fünf Minuten.",es:"Está a la vuelta de la esquina, ni cinco minutos."}]},"Ich habe ein Doppelzimmer auf den Namen Romero reserviert.":{de:"Willkommen! Darf ich kurz Ihren Ausweis sehen?",es:"¡Bienvenido! ¿Me permite su documento un momento?",mas:[{de:"Ab wann kann ich das Zimmer beziehen?",es:"¿A partir de cuándo puedo entrar en la habitación?"},{de:"Ab vierzehn Uhr. Das Gepäck können Sie gern hierlassen.",es:"A partir de las catorce. El equipaje puede dejarlo aquí."},{de:"Ab wann wird das Frühstück serviert?",es:"¿Desde qué hora sirven el desayuno?"},{de:"Von halb sieben bis zehn, am Wochenende bis elf.",es:"De seis y media a diez; el fin de semana hasta las once."},{de:"Im Bad fehlt ein Handtuch.",es:"En el baño falta una toalla."},{de:"Das tut mir leid, ich schicke sofort jemanden hinauf.",es:"Lo siento, mando a alguien ahora mismo."},{de:"Ich würde gern auschecken.",es:"Quisiera hacer el check-out."},{de:"Gern. Kann ich das Gepäck bis nachmittags für Sie aufbewahren?",es:"Con gusto. ¿Le guardo el equipaje hasta la tarde?"}]}};Object.assign(i,l);function t(e){return e&&{...e,es:o(e.es)}}function u(e){return t(i[e])||null}function h(e){var a;return(((a=i[e])==null?void 0:a.mas)||[]).map(t)}function m(e){const a=i[e];if(!a)return[];const n=[{de:a.de,es:o(a.es),quien:"otro"}];return(a.mas||[]).forEach((s,d)=>{n.push({de:s.de,es:o(s.es),quien:d%2===0?"tu":"otro"})}),n}const r=new Map;for(const[e,a]of Object.entries(i)){r.set(e,{de:a.de,es:a.es});const n=a.mas||[];for(let s=0;s+1<n.length;s+=2)r.has(n[s].de)||r.set(n[s].de,{de:n[s+1].de,es:n[s+1].es})}function g(e){return t(r.get(e))||null}export{g as a,m as c,u as r,h as s};
